package auth

import (
	"github.com/MicahParks/keyfunc/v3"
	"github.com/go-errors/errors"
	"github.com/golang-jwt/jwt/v5"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

func NewKeyFunc(url string) (jwt.Keyfunc, error) {
	jwks, err := keyfunc.NewDefault([]string{url})
	if err != nil {
		return nil, errors.Wrap(err, 0)
	}
	return jwks.Keyfunc, nil
}

type Parser struct {
	keyFunc  jwt.Keyfunc
	issuer   string
	audience string
}

func NewParser(
	keyFunc jwt.Keyfunc,
	issuer string,
	audience string,
) *Parser {
	return &Parser{
		keyFunc:  keyFunc,
		issuer:   issuer,
		audience: audience,
	}
}

func (p *Parser) Parse(rawToken string) (*Token, error) {
	claims := Claims{}
	token, err := jwt.ParseWithClaims(
		rawToken,
		&claims,
		p.keyFunc,
		jwt.WithLeeway(60), // 1 minute leeway
		jwt.WithIssuer(p.issuer),
		jwt.WithAudience(p.audience),
		jwt.WithValidMethods([]string{"RS256"}),
	)
	if err != nil {
		return nil, errors.Errorf("%w: %v", domainerror.Unauthorized, err)
	}

	if !token.Valid {
		return nil, errors.Errorf("%w: Token is invalid", domainerror.Unauthorized)
	}

	return NewToken(token, claims), nil
}

