package grpcserver

import (
	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/api/grpcserver/contracts"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type specificationConverter struct {
	*contracts.CarSpecification
}

func newConverter(
	contract *contracts.CarSpecification,
) specificationConverter {
	return specificationConverter{
		contract,
	}
}

// nolint:gocyclo
func ToCarSpecificationEntity(
	contract *contracts.CarSpecification,
) (specification.CarSpecification, error) {
	if contract == nil {
		return specification.CarSpecification{}, errors.Errorf(
			"%w: car specification is required",
			domainerror.InvalidOperation,
		)
	}

	details, err := toDetailsEntity(contract.CarDetails)
	if err != nil {
		return specification.CarSpecification{}, err
	}

	period, err := toStructureWeekPeriodEntity(contract.StructureWeekPeriod)
	if err != nil {
		return specification.CarSpecification{}, err
	}

	forbiddenPeriods, err := toManyStructureWeekPeriodEntities(contract.ForbiddenStructureWeekPeriods)
	if err != nil {
		return specification.CarSpecification{}, err
	}

	converter := newConverter(contract)

	sMessages, err := converter.toSMessageSpecification()
	if err != nil {
		return specification.CarSpecification{}, err
	}

	styling, err := converter.toStylingSpecification()
	if err != nil {
		return specification.CarSpecification{}, err
	}

	options, err := converter.toOptionSpecification()
	if err != nil {
		return specification.CarSpecification{}, err
	}

	packages, err := converter.toPackageSpecification()
	if err != nil {
		return specification.CarSpecification{}, err
	}

	wheels, err := converter.toWheelSpecification()
	if err != nil {
		return specification.CarSpecification{}, err
	}

	return specification.NewCarSpecification(
		details,
		period,
		forbiddenPeriods,
		sMessages,
		styling,
		options,
		packages,
		wheels,
	)
}

func toDetailsEntity(contract *contracts.CarDetails) (specification.CarDetails, error) {
	if contract == nil {
		return specification.CarDetails{}, errors.Errorf(
			"%w: car details is required",
			domainerror.InvalidOperation,
		)
	}

	entity := specification.NewCarDetails(
		int(contract.ModelYear),
		contract.SpecMarket,
		contract.CarType,
		contract.Engine,
		contract.SalesVersion,
		contract.Body,
		contract.Gearbox,
		contract.Steering,
		contract.MarketingCode,
		contract.LocalEditionCode,
	)

	return entity, nil
}

func (c specificationConverter) toSMessageSpecification() (
	specification.SMessageSpecification,
	error,
) {
	if c.SMessages == nil {
		return specification.SMessageSpecification{}, errors.Errorf(
			"%w: sMessages is required",
			domainerror.InvalidOperation,
		)
	}

	contracts := c.SMessages.SMessages
	entities := make([]specification.SMessage, len(contracts))
	var err error
	for i, contract := range contracts {
		entities[i], err = toSMessageEntity(contract)
		if err != nil {
			return specification.SMessageSpecification{}, err
		}
	}

	return specification.NewSMessageSpecification(entities), nil
}

func toSMessageEntity(
	contract *contracts.SMessage,
) (specification.SMessage, error) {
	if contract == nil {
		return specification.SMessage{}, errors.Errorf(
			"%w: sMessage is required",
			domainerror.InvalidOperation,
		)
	}

	code, err := specification.NewCode(contract.Code)
	if err != nil {
		return specification.SMessage{}, err
	}

	period, err := toStructureWeekPeriodEntity(contract.Period)
	if err != nil {
		return specification.SMessage{}, err
	}

	return specification.NewSMessage(code, period), nil
}

// nolint:gocyclo
func (c specificationConverter) toStylingSpecification() (
	specification.StylingSpecification,
	error,
) {
	if c.Stylings == nil {
		return specification.StylingSpecification{}, errors.Errorf(
			"%w: stylings is required",
			domainerror.InvalidOperation,
		)
	}

	// nolint:staticcheck
	if c.Stylings.DefaultCombination != nil {
		return specification.StylingSpecification{},
			errors.Errorf(
				"%w: default combination is not supported",
				domainerror.InvalidOperation,
			)
	}

	colors, err := toColorEntities(c.Stylings.Colors)
	if err != nil {
		return specification.StylingSpecification{}, err
	}

	upholsteries, err := toUpholsteryEntities(c.Stylings.Upholsteries)
	if err != nil {
		return specification.StylingSpecification{}, err
	}

	defaultColors, err := toManyTimeBoundCodes(c.Stylings.DefaultColors)
	if err != nil {
