func toSelectionsEntity(
	selections []*contracts.Selection,
) (puan.Selections, error) {
	entities := make(puan.Selections, len(selections))
	for i, selection := range selections {
		selectionEntity, err := ToSelectionEntity(selection)
		if err != nil {
			return nil, err
		}

		entities[i] = selectionEntity
	}

	return entities, nil
}

func ToSelectionEntity(
	selection *contracts.Selection,
) (puan.Selection, error) {
	if selection == nil {
		return puan.Selection{}, errors.Errorf(
			"%w: selection is nil",
			domainerror.InvalidOperation,
		)
	}

	action, err := toActionEntity(selection.Action)
	if err != nil {
		return puan.Selection{}, err
	}

	builder := puan.NewSelectionBuilder(selection.Code).
		WithAction(action)

	for _, subSelectionCode := range selection.SubSelectionCodes {
		builder.WithSubSelectionID(subSelectionCode)
	}

	entity := builder.Build()

	return entity, nil
}

func toActionEntity(action contracts.Action) (puan.Action, error) {
	switch action {
	case contracts.Action_ADD:
		return puan.ADD, nil
	case contracts.Action_REMOVE:
		return puan.REMOVE, nil
	default:
		return "", errors.Errorf(
			"%w: unknown action %d",
			domainerror.InvalidOperation,
			action,
		)
	}
}

func toSelectionGroupEntities(
	groups []*contracts.SelectionGroup,
) ([]puan.Selections, error) {
	entities := make([]puan.Selections, len(groups))
	for i, group := range groups {
		if group == nil {
			return nil, errors.Errorf(
				"%w: selection group is nil",
				domainerror.InvalidOperation,
			)
		}
		entity, err := toSelectionsEntity(group.Selections)
		if err != nil {
			return nil, err
		}

		entities[i] = entity
	}

	return entities, nil
}

