package grpcserver

import (
	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"
	"github.com/volvo-cars/caas-car-configurator/internal/api/grpcserver/contracts"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

func toCarSpecificationContract(
	entity specification.CarSpecification,
) *contracts.CarSpecification {
	return &contracts.CarSpecification{
		CarDetails:                    ToCarDetails(entity.Details()),
		StructureWeekPeriod:           toStructureWeekPeriodContract(entity.Period()),
		ForbiddenStructureWeekPeriods: toManyStructureWeekPeriodContracts(entity.ForbiddenPeriods()),
		SMessages:                     toSMessageSpecificationContract(entity.SMessages()),
		Stylings:                      toStylingSpecificationContract(entity.Styling()),
		Options:                       toOptionSpecificationContract(entity.Options()),
		Packages:                      toPackageSpecificationContract(entity.Packages()),
		Wheels:                        toWheelSpecificationContract(entity.Wheels()),
	}
}

func toManyStructureWeekPeriodContracts(
	entities specification.ManyStructureWeekPeriods,
) []*contracts.StructureWeekPeriod {
	periods := make([]*contracts.StructureWeekPeriod, len(entities))
	for index, entity := range entities {
		periods[index] = toStructureWeekPeriodContract(entity)
	}
	return periods
}

func toSMessageSpecificationContract(
	entity specification.SMessageSpecification,
) *contracts.SMessageSpecification {
	sMessages := make([]*contracts.SMessage, len(entity.SMessages()))
	for index, sMessage := range entity.SMessages() {
		sMessages[index] = toSMessageContract(sMessage)
	}
	return &contracts.SMessageSpecification{SMessages: sMessages}
}

func toSMessageContract(entity specification.SMessage) *contracts.SMessage {
	return &contracts.SMessage{
		Code:   entity.Code().String(),
		Period: toStructureWeekPeriodContract(entity.Period()),
	}
}

func toStylingSpecificationContract(
	entity specification.StylingSpecification,
) *contracts.StylingSpecification {
	colors := make([]*contracts.Color, len(entity.Colors()))
	for index, color := range entity.Colors() {
		colors[index] = toColorContract(color)
	}
	upholsteries := make([]*contracts.Upholstery, len(entity.Upholsteries()))
	for index, upholstery := range entity.Upholsteries() {
		upholsteries[index] = toUpholsteryContract(upholstery)
	}
	return &contracts.StylingSpecification{
		Colors:              colors,
		Upholsteries:        upholsteries,
		DefaultColors:       toManyTimeBoundCodeContracts(entity.DefaultColors()),
		DefaultUpholsteries: toManyTimeBoundCodeContracts(entity.DefaultUpholsteries()),
	}
}

func toColorContract(entity specification.Color) *contracts.Color {
	return &contracts.Color{
		Code:                entity.Code().String(),
		RequiredOptions:     toManyTimeBoundAtLeastOneContracts(entity.RequiredOptions()),
		RequiredWheels:      toManyTimeBoundExactlyOneContracts(entity.RequiredWheels()),
		ForbidsOptions:      toManyForbidsContracts(entity.ForbidsOptions()),
		ForbidsWheels:       toManyForbidsContracts(entity.ForbidsWheels()),
		ForbidsUpholsteries: toManyForbidsContracts(entity.ForbidsUpholsteries()),
		Period:              toStructureWeekPeriodContract(entity.Period()),
	}
}

func toUpholsteryContract(entity specification.Upholstery) *contracts.Upholstery {
	return &contracts.Upholstery{
		Code:            entity.Code().String(),
		RequiredOptions: toManyTimeBoundAtLeastOneContracts(entity.RequiredOptions()),
		ForbidsOptions:  toManyForbidsContracts(entity.ForbidsOptions()),
		ForbidsColors:   toManyForbidsContracts(entity.ForbidsColors()),
		ForbidsWheels:   toManyForbidsContracts(entity.ForbidsWheels()),
		Period:          toStructureWeekPeriodContract(entity.Period()),
	}
}

func toManyTimeBoundCodeContracts(
	entities specification.ManyTimeBoundCodes,
) []*contracts.TimeBoundCode {
	codes := make([]*contracts.TimeBoundCode, len(entities))
	for index, entity := range entities {
		codes[index] = toTimeBoundCodeContract(entity)
	}
	return codes
}

func toTimeBoundCodeContract(entity specification.TimeBoundCode) *contracts.TimeBoundCode {
	return &contracts.TimeBoundCode{
		Code:   entity.Code().String(),
		Period: toStructureWeekPeriodContract(entity.Period()),
	}
}

func toOptionSpecificationContract(
	entity specification.OptionSpecification,
) *contracts.OptionSpecification {
	options := make([]*contracts.Option, len(entity.Options()))
	for index, option := range entity.Options() {
		options[index] = toOptionContract(option)
	}
	requirements := make([]*contracts.CombinedOptionRequirement, len(entity.CombinedRequirements()))
	for index, requirement := range entity.CombinedRequirements() {
		requirements[index] = toCombinedOptionRequirementContract(requirement)
	}
	return &contracts.OptionSpecification{
		Options:                options,
		PackageOnlyOptionCodes: entity.PackageOnlyOptions().Strings(),
		IncludedOptions:        toManyTimeBoundExactlyOneContracts(entity.IncludedOptions()),
		CombinedRequirements:   requirements,
	}
}

func toOptionContract(entity specification.Option) *contracts.Option {
	return &contracts.Option{
		Code:                 entity.Code().String(),
		RequiredColors:       toManyTimeBoundExactlyOneContracts(entity.RequiredColors()),
		RequiredUpholsteries: toManyTimeBoundExactlyOneContracts(entity.RequiredUpholsteries()),
		RequiredOptions:      toManyTimeBoundAtLeastOneContracts(entity.RequiredOptions()),
		RequiredWheels:       toManyTimeBoundExactlyOneContracts(entity.RequiredWheels()),
		ForbidsOptions:       toManyForbidsContracts(entity.ForbidsOptions()),
		ForbidsColors:        toManyForbidsContracts(entity.ForbidsColors()),
		ForbidsWheels:        toManyForbidsContracts(entity.ForbidsWheels()),
		ForbidsUpholsteries:  toManyForbidsContracts(entity.ForbidsUpholsteries()),
		Period:               toStructureWeekPeriodContract(entity.Period()),
	}
}

func toCombinedOptionRequirementContract(
	entity specification.CombinedOptionRequirement,
) *contracts.CombinedOptionRequirement {
	return &contracts.CombinedOptionRequirement{
		RequiringOptionCodes: entity.RequiringCodes().Strings(),
		RequiredOptionCode:   entity.RequiredCode().String(),
	}
}

func toPackageSpecificationContract(
	entity specification.PackageSpecification,
) *contracts.PackageSpecification {
	packages := make([]*contracts.Package, len(entity.Packages()))
	for index, pkg := range entity.Packages() {
		packages[index] = toPackageContract(pkg)
	}
	return &contracts.PackageSpecification{
		Packages:         packages,
		IncludedPackages: toManyTimeBoundExactlyOneContracts(entity.IncludedPackages()),
	}
}

func toPackageContract(entity specification.Package) *contracts.Package {
	return &contracts.Package{
		Code:                 entity.Code().String(),
		RequiredColors:       toNilableExactlyOneContract(entity.RequiredColors()),
		RequiredUpholsteries: toNilableExactlyOneContract(entity.RequiredUpholsteries()),
		RequiredWheels:       toNilableExactlyOneContract(entity.RequiredWheels()),
		RequiredOptions:      toManyExactlyOneContracts(entity.RequiredOptions()),
		Period:               toStructureWeekPeriodContract(entity.Period()),
	}
}

func toWheelSpecificationContract(
	entity specification.WheelSpecification,
) *contracts.WheelSpecification {
	wheels := make([]*contracts.Wheel, len(entity.Wheels()))
	for index, wheel := range entity.Wheels() {
		wheels[index] = toWheelContract(wheel)
	}
	return &contracts.WheelSpecification{
		Wheels:        wheels,
		StandardWheel: toNilableCodeContract(entity.StandardWheel()),
	}
}

func toWheelContract(entity specification.Wheel) *contracts.Wheel {
	return &contracts.Wheel{
		Code:                 entity.Code().String(),
		RequiredColors:       toManyTimeBoundExactlyOneContracts(entity.RequiredColors()),
		RequiredOptions:      toManyTimeBoundAtLeastOneContracts(entity.RequiredOptions()),
		RequiredUpholsteries: toManyTimeBoundExactlyOneContracts(entity.RequiredUpholsteries()),
		ForbidsOptions:       toManyForbidsContracts(entity.ForbidsOptions()),
		ForbidsUpholsteries:  toManyForbidsContracts(entity.ForbidsUpholsteries()),
		Period:               toStructureWeekPeriodContract(entity.Period()),
	}
}

func toManyExactlyOneContracts(entities specification.ManyExactlyOne) []*contracts.ExactlyOne {
	requirements := make([]*contracts.ExactlyOne, len(entities))
	for index, entity := range entities {
		requirements[index] = toExactlyOneContract(entity)
	}
	return requirements
}

func toExactlyOneContract(entity specification.ExactlyOne) *contracts.ExactlyOne {
	return &contracts.ExactlyOne{
		Codes:       entity.Codes().Strings(),
		DefaultCode: toNilableCodeContract(entity.DefaultCode()),
	}
}

func toNilableExactlyOneContract(entity *specification.ExactlyOne) *contracts.ExactlyOne {
	if entity == nil {
		return nil
	}
	return toExactlyOneContract(*entity)
}

func toManyTimeBoundExactlyOneContracts(
	entities specification.ManyTimeBoundExactlyOne,
) []*contracts.TimeBoundExactlyOne {
	requirements := make([]*contracts.TimeBoundExactlyOne, len(entities))
	for index, entity := range entities {
		requirements[index] = toTimeBoundExactlyOneContract(entity)
	}
	return requirements
}

func toTimeBoundExactlyOneContract(
	entity specification.TimeBoundExactlyOne,
) *contracts.TimeBoundExactlyOne {
	return &contracts.TimeBoundExactlyOne{
		Codes:       entity.Codes().Strings(),
		DefaultCode: toNilableCodeContract(entity.DefaultCode()),
		Period:      toStructureWeekPeriodContract(entity.Period()),
	}
}

func toManyTimeBoundAtLeastOneContracts(
	entities specification.ManyTimeBoundAtLeastOne,
) []*contracts.TimeBoundAtLeastOne {
	requirements := make([]*contracts.TimeBoundAtLeastOne, len(entities))
	for index, entity := range entities {
		requirements[index] = toTimeBoundAtLeastOneContract(entity)
	}
	return requirements
}

func toTimeBoundAtLeastOneContract(
	entity specification.TimeBoundAtLeastOne,
) *contracts.TimeBoundAtLeastOne {
	return &contracts.TimeBoundAtLeastOne{
		Codes:       entity.Codes().Strings(),
		DefaultCode: toNilableCodeContract(entity.DefaultCode()),
		Period:      toStructureWeekPeriodContract(entity.Period()),
	}
}

func toManyForbidsContracts(entities specification.ManyForbids) []*contracts.Forbids {
	forbids := make([]*contracts.Forbids, len(entities))
	for index, entity := range entities {
		forbids[index] = toForbidsContract(entity)
	}
	return forbids
}

func toForbidsContract(entity specification.Forbids) *contracts.Forbids {
	return &contracts.Forbids{
		Code:   entity.Code().String(),
		Period: toStructureWeekPeriodContract(entity.Period()),
	}
}

func toNilableCodeContract(code *specification.Code) *string {
	if code == nil {
		return nil
	}
	value := code.String()
	return &value
}

func ToCarDetails(detail specification.CarDetails) *contracts.CarDetails {
	return &contracts.CarDetails{
		ModelYear:        int32(detail.ModelYear()),
		SpecMarket:       detail.SpecMarket(),
		CarType:          detail.CarType(),
		Engine:           detail.Engine(),
		SalesVersion:     detail.SalesVersion(),
		Body:             detail.Body(),
		Gearbox:          detail.Gearbox(),
		Steering:         detail.Steering(),
		MarketingCode:    detail.MarketingCode(),
		LocalEditionCode: detail.LocalEditionCode(),
	}
}

func toCarKeyContract(entity ruleset.CarKey) *contracts.CarKey {
	details := ToCarDetails(entity.Details())

	sMessage := entity.SMessage()
	color := entity.Color()
	upholstery := entity.Upholstery()
	wheel := entity.Wheel()
	options := entity.Options()
	packages := entity.Packages()
	structureWeek := toStructureWeekContract(entity.StructureWeek())

	carKey := &contracts.CarKey{
		Details:       details,
		Color:         color.String(),
		Upholstery:    upholstery.String(),
		Wheel:         wheel.String(),
		Options:       options.Strings(),
		Packages:      packages.Strings(),
		StructureWeek: structureWeek,
	}

	if sMessage != nil {
		carKey.SMessage = (*string)(sMessage)
	}

	return carKey
}

func toStructureWeekContract(entity specification.StructureWeek) *contracts.StructureWeek {
	week := &contracts.StructureWeek{
		Year: int32(entity.Year()),
		Week: int32(entity.Week()),
	}
	return week
}

func toCarKeyInPeriodContracts(entities []ruleset.CarKeyInPeriod) []*contracts.CarKeyInPeriod {
	carKeysInPeriods := make([]*contracts.CarKeyInPeriod, len(entities))
	for i, entity := range entities {
		carKeysInPeriods[i] = toCarKeyInPeriodContract(entity)
	}

	return carKeysInPeriods
}

func toCarKeyInPeriodContract(entity ruleset.CarKeyInPeriod) *contracts.CarKeyInPeriod {
	carKey := toCarKeyContract(entity.CarKey())
	period := toStructureWeekPeriodContract(entity.StructureWeekPeriod())

	return &contracts.CarKeyInPeriod{
		CarKey: carKey,
		Period: period,
	}
}

func toStructureWeekPeriodContract(
	entity specification.StructureWeekPeriod,
) *contracts.StructureWeekPeriod {
	period := &contracts.StructureWeekPeriod{
		From: toStructureWeekContract(entity.From()),
		To:   toStructureWeekContract(entity.To()),
	}

	return period
}

func toBaseCarKeysResponse(
	baseCarKeys ruleset.BaseCarKeys,
) *contracts.BaseCarKeysResponse {
	components := toManyComponentWithCarKeysContracts(baseCarKeys.Components())
	packageComponents := toManyPackageComponentWithCarKeysContracts(baseCarKeys.PackageComponents())

	return &contracts.BaseCarKeysResponse{
		Components:        components,
		PackageComponents: packageComponents,
	}
}

func toManyComponentWithCarKeysContracts(
	entities []ruleset.ComponentCarKeys,
