	}

	return componentCarKeys
}

func toComponentWithCarKeysContract(
	entity ruleset.ComponentCarKeys,
) *contracts.ComponentWithCarKeys {
	component := toComponentContract(entity.Component())
	carKeys := toCarKeyInPeriodContracts(entity.CarKeys())

	return &contracts.ComponentWithCarKeys{
		Component: component,
		CarKeys:   carKeys,
	}
}

