	packageComponentCarKeys := make([]*contracts.PackageComponentWithCarKeys, len(entities))
	for i, entity := range entities {
		packageComponentCarKeys[i] = toPackageComponentWithCarKeysContract(entity)
	}

	return packageComponentCarKeys
}

func toPackageComponentWithCarKeysContract(
	entity ruleset.PackageVariantComponentCarKeys,
