func toManyComponentContracts(entities []ruleset.Component) []*contracts.Component {
	components := make([]*contracts.Component, len(entities))
	for i, entity := range entities {
		components[i] = toComponentContract(entity)
	}

	return components
}

func toNextCarKeysResponse(
	entities []ruleset.CarKeyForSelection,
) (*contracts.NextCarKeysResponse, error) {
	carKeysBySelection := make([]*contracts.CarKeyForSelection, len(entities))
	for i, entity := range entities {
		carKeyBySelection, err := toCarKeyForSelectionContract(entity)
		if err != nil {
			return nil, err
		}

		carKeysBySelection[i] = carKeyBySelection
	}

	return &contracts.NextCarKeysResponse{
		CarKeysBySelection: carKeysBySelection,
	}, nil
}

func toCarKeyForSelectionContract(
	entity ruleset.CarKeyForSelection,
) (*contracts.CarKeyForSelection, error) {
	selection, err := toSelectionContract(entity.Selection())
	if err != nil {
		return nil, err
	}
	carKey := toCarKeyContract(entity.CarKey())

	return &contracts.CarKeyForSelection{
		Selection: selection,
		CarKey:    carKey,
	}, nil
}

func toSelectionContract(entity puan.Selection) (*contracts.Selection, error) {
	action, err := toActionContract(entity.Action())
	if err != nil {
		return nil, err
	}

	return &contracts.Selection{
		Code:              entity.ID(),
		Action:            action,
		SubSelectionCodes: entity.SubSelectionIDs(),
	}, nil
}

func toActionContract(entity puan.Action) (contracts.Action, error) {
	switch entity {
	case puan.ADD:
		return contracts.Action_ADD, nil
	case puan.REMOVE:
		return contracts.Action_REMOVE, nil
	default:
		return contracts.Action_ADD, errors.Errorf("unknown action: %v", entity)
	}
}

func toManyCarKeysResponse(
	entities ruleset.CarKeysBySelectionGroup,
) (*contracts.CalculateManyCarKeysResponse, error) {
	carKeysBySelectionGroup := make([]*contracts.CarKeyForSelectionGroup, len(entities))
	for i, entity := range entities {
		carKeyForSelectionGroup, err := toCarKeyForSelectionGroupContract(entity)
		if err != nil {
			return nil, err
		}
		carKeysBySelectionGroup[i] = carKeyForSelectionGroup
	}

	return &contracts.CalculateManyCarKeysResponse{
		CarKeysBySelectionGroup: carKeysBySelectionGroup,
	}, nil
}

func toCarKeyForSelectionGroupContract(
	entity ruleset.CarKeyForSelectionGroup,
) (*contracts.CarKeyForSelectionGroup, error) {
	selections, err := toManySelectionContracts(entity.Selections())
	if err != nil {
		return nil, err
	}

	carKey := toCarKeyContract(entity.CarKey())

	return &contracts.CarKeyForSelectionGroup{
		Selections: selections,
		CarKey:     carKey,
	}, nil
}

func toManySelectionContracts(
	entities puan.Selections,
) ([]*contracts.Selection, error) {
	selections := make([]*contracts.Selection, len(entities))
	for i, entity := range entities {
		selection, err := toSelectionContract(entity)
		if err != nil {
			return nil, err
		}
		selections[i] = selection
	}
	return selections, nil
}

