	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

type AuthInterceptor struct {
	parser *auth.Parser
}

func NewAuthInterceptor(parser *auth.Parser) *AuthInterceptor {
	return &AuthInterceptor{parser: parser}
}

// nolint:unparam
func (i *AuthInterceptor) Intercept(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	rawToken, err := i.getBearerToken(ctx)
	if err != nil {
		return nil, err
	}

	token, err := i.parser.Parse(rawToken)
	if err != nil {
		return nil, err
	}

	clientID, err := token.ClientID()
	if err != nil {
		return nil, err
	}
	ctx = observability.EnrichContextWithClientID(ctx, clientID)

	return handler(ctx, req)
}

func (i *AuthInterceptor) getBearerToken(ctx context.Context) (string, error) {
	metadata, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return "", errors.Errorf("%w missing metadata", domainerror.Unauthorized)
	}

	values := metadata.Get("authorization")
	if len(values) == 0 {
		return "",
			errors.Errorf("%w missing authorization header", domainerror.Unauthorized)
	}
	value := values[0]

	tokenStr := ""
	noBearerPrefix := !strings.HasPrefix(strings.ToLower(value), "bearer ")
	if noBearerPrefix {
		return "",
			errors.Errorf(
				"%w expected bearer prefix in authorization header",
				domainerror.Unauthorized,
			)
	}

	tokenStr = strings.TrimSpace(value[len("bearer "):])
	return tokenStr, nil
}

