package interceptors

import (
	"context"

	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puanerror"
	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type ErrorInterceptor struct {
	logger *loggingsdk.Logger
}

func NewErrorInterceptor(logger *loggingsdk.Logger) *ErrorInterceptor {
	return &ErrorInterceptor{logger: logger}
}

// nolint:unparam
func (i *ErrorInterceptor) Intercept(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	resp, err := handler(ctx, req)

	err = i.toGRPCError(ctx, err)
	if err != nil {
		return nil, err
	}

	return resp, nil
}

// nolint:gocyclo
func (i *ErrorInterceptor) toGRPCError(ctx context.Context, err error) error {
	switch {
	case errors.Is(err, domainerror.InvalidOperation):
		return status.Error(codes.InvalidArgument, err.Error())
	case errors.Is(err, domainerror.Unauthorized):
		return status.Error(codes.Unauthenticated, err.Error())
	case errors.Is(err, domainerror.NotFound):
		return status.Error(codes.NotFound, err.Error())
	case errors.Is(err, puanerror.InvalidArgument):
		return status.Error(codes.InvalidArgument, err.Error())
	case errors.Is(err, puanerror.InvalidOperation):
		return status.Error(codes.InvalidArgument, err.Error())
	case errors.Is(err, puanerror.NotFound):
		return status.Error(codes.NotFound, err.Error())
	case errors.Is(err, context.Canceled):
		return status.Error(codes.Canceled, "Context canceled")
	case errors.Is(err, puanerror.SolverFailed):
		i.logger.Error(ctx, "Solver failed", err)
		return status.Error(codes.Internal, "Solver failed")
	case err != nil:
		i.logger.Error(ctx, "Internal server error", err)
		return status.Error(codes.Internal, "Something went wrong")
	}

	return nil
}

