package interceptors

import (
	"context"

	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
	"google.golang.org/grpc"
)

var methodKey = loggingsdk.ToCustomLabelKey("method")
var callArgumentsKey = loggingsdk.ToCustomLabelKey("call_arguments")

type LoggingInterceptor struct {
	logger *loggingsdk.Logger
}

func NewLoggingInterceptor(logger *loggingsdk.Logger) *LoggingInterceptor {
	return &LoggingInterceptor{logger: logger}
}

func (i *LoggingInterceptor) LogRequest(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	i.logger.Infow(
		ctx,
		"Received method call",
		methodKey,
		info.FullMethod,
		callArgumentsKey,
		req,
	)

	resp, err := handler(ctx, req)
	if err == nil {
		i.logger.Infow(
			ctx,
			"Method completed successfully",
			methodKey,
			info.FullMethod,
		)
	}

	return resp, err
}

func (i *LoggingInterceptor) LogRequestFailure(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	resp, err := handler(ctx, req)
	if err != nil {
		i.logger.Infow(
			ctx,
			"Method failed",
			methodKey,
			info.FullMethod,
			loggingsdk.ErrorLogKey,
			loggingsdk.ToErrorLogValue(err),
		)
	}

	return resp, err
}

