package interceptors

import (
	"context"
	"strings"
	"time"

	"github.com/go-errors/errors"
	"github.com/volvo-cars/caas-car-configurator/internal/api/grpcserver/contracts"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
	semconv "go.opentelemetry.io/otel/semconv/v1.21.0"
	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
)

type MetricsInterceptor struct {
	meter metric.Meter

	baseAttributes []attribute.KeyValue

	callCounter           metric.Int64Counter
	callDurationHistogram metric.Int64Histogram
}

func NewMetricsInterceptor(
	host string,
	port int,
	meter metric.Meter,
) (*MetricsInterceptor, error) {
	if meter == nil {
		return nil, errors.New("meter cannot be nil")
	}

	counter, err := meter.Int64Counter(
		"rpc.grpc.server.calls_total",
		metric.WithDescription("Incoming call count"),
		metric.WithUnit("call"),
	)
	if err != nil {
		return nil, err
	}

	histogram, err := meter.Int64Histogram(
		"rpc.grpc.server.duration",
		metric.WithDescription("Incoming end to end duration"),
		metric.WithUnit("ms"),
	)
	if err != nil {
		return nil, err
	}

	baseAttributes := newBaseMetricAttributes(host, port)

	return &MetricsInterceptor{
		meter: meter,

		baseAttributes: baseAttributes,

		callCounter:           counter,
		callDurationHistogram: histogram,
	}, nil
}

func newBaseMetricAttributes(
	host string,
	port int,
) []attribute.KeyValue {
	return []attribute.KeyValue{
		semconv.RPCService(contracts.CarConfigurationService_ServiceDesc.ServiceName),
		semconv.ServerAddress(host),
		semconv.ServerPort(port),
	}
}

func (i *MetricsInterceptor) Collect(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	start := time.Now()

	resp, err := handler(ctx, req)

	duration := time.Since(start).Milliseconds()
	i.collectMetrics(
		ctx,
		info.FullMethod,
		duration,
		err,
	)

	return resp, err
}

func (interceptor *MetricsInterceptor) collectMetrics(
	ctx context.Context,
	method string,
	duration int64,
	err error,
) {
	attrs := interceptor.getAttributes(
		method,
		err,
	)
	options := metric.WithAttributes(attrs...)
	interceptor.callCounter.Add(
		ctx,
		1,
		options,
	)

	interceptor.callDurationHistogram.Record(
		ctx,
		duration,
		options,
	)
}

// https://opentelemetry.io/docs/specs/semconv/rpc/grpc/
func (interceptor *MetricsInterceptor) getAttributes(
	method string,
	err error,
) []attribute.KeyValue {
	shortMethod := removeServerNameFromMethod(method)
	attrs := []attribute.KeyValue{
		semconv.RPCMethod(shortMethod),
	}
	attrs = append(attrs, interceptor.baseAttributes...)

	statusCode := interceptor.getGRPCStatusCode(err)
	statusAttribute := semconv.RPCGRPCStatusCodeKey.Int(statusCode)
	attrs = append(attrs, statusAttribute)

	return attrs
}

func (interceptor *MetricsInterceptor) getGRPCStatusCode(
	err error,
) int {
	status, ok := status.FromError(err)
	if ok {
		return int(status.Code())
	}

	return int(codes.Unknown)
}

func removeServerNameFromMethod(
	method string,
) string {
	parts := strings.Split(method, "/")
	return parts[len(parts)-1]
}

