	"google.golang.org/grpc"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/metadata"
	"google.golang.org/grpc/status"
)

type OperationIDInterceptor struct {
	logger *loggingsdk.Logger
}

func NewOperationIDInterceptor(logger *loggingsdk.Logger) *OperationIDInterceptor {
	return &OperationIDInterceptor{logger: logger}
}

func (interceptor *OperationIDInterceptor) Intercept(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	operationID, err := interceptor.obtainOperationID(ctx)
	if err != nil {
		interceptor.logger.Error(ctx, "Failed to obtain operation ID", err)
		return nil, err
	}

	ctx = loggingsdk.EnrichContextWithOperationID(ctx, operationID)

	return handler(ctx, req)
}

func (interceptor *OperationIDInterceptor) obtainOperationID(
	ctx context.Context,
) (string, error) {
	metadata, ok := metadata.FromIncomingContext(ctx)
	if !ok {
		return "", status.Error(codes.InvalidArgument, "missing metadata")
	}

	operationID := ""

	metadataIDs := metadata.Get("operation-id")
	if len(metadataIDs) > 0 {
		operationID = metadataIDs[0]
	}

	if operationID == "" {
		return uuid.NewString(), nil
	}

	return operationID, nil
}

