)

type PanicInterceptor struct {
	logger *loggingsdk.Logger
}

func NewPanicInterceptor(logger *loggingsdk.Logger) *PanicInterceptor {
	return &PanicInterceptor{logger: logger}
}

// nolint:unparam
func (i *PanicInterceptor) Intercept(
	ctx context.Context,
	req any,
	info *grpc.UnaryServerInfo,
	handler grpc.UnaryHandler,
) (any, error) {
	defer func() {
		if content := recover(); content != nil {
			err := fmt.Errorf("%v", content)
			i.logger.Error(ctx, "Panic", err)
			panic(content)
		}
	}()
	return handler(ctx, req)
}

