package grpcserver

import (
	"context"

	"github.com/go-errors/errors"
	"github.com/google/uuid"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/observability"

	"google.golang.org/protobuf/types/known/emptypb"

	"github.com/volvo-cars/caas-car-configurator/internal/api/grpcserver/contracts"
)

func (s *Server) HealthCheck(
	ctx context.Context,
	req *contracts.HealthCheckRequest,
) (*contracts.HealthCheckResponse, error) {
	return &contracts.HealthCheckResponse{
		Status: contracts.HealthStatus_HEALTHY,
	}, nil
}

func (s *Server) CreateRuleset(
	ctx context.Context,
	specificationContract *contracts.CarSpecification,
) (*contracts.CreateRulesetResponse, error) {
	specification, err := ToCarSpecificationEntity(specificationContract)
	if err != nil {
		return nil, err
	}

	rulesetID, err := s.rulesetCreator.Create(ctx, specification)
	if err != nil {
		return nil, err
	}

	return &contracts.CreateRulesetResponse{
		Id: rulesetID.String(),
	}, nil
}

func (s *Server) GetCarSpecification(
	ctx context.Context,
	req *contracts.GetCarSpecificationRequest,
) (*contracts.CarSpecification, error) {
	rulesetID, err := getRulesetID(req)
	if err != nil {
		return nil, err
	}

	enrichedCtx := observability.EnrichLogsWithRulesetID(ctx, rulesetID)

	entity, err := s.carSpecificationReader.GetCarSpecification(enrichedCtx, rulesetID)
	if err != nil {
		return nil, err
	}

	spec := toCarSpecificationContract(entity)
	return spec, nil
}

func (s *Server) DeleteRuleset(
	ctx context.Context,
	req *contracts.DeleteRulesetRequest,
) (*emptypb.Empty, error) {
	rawID := req.GetId()

	rulesetID, err := uuid.Parse(rawID)
	if err != nil {
		return nil,
			errors.Errorf(
				"%w could not parse id: %s. Error: %s",
				domainerror.InvalidOperation,
				rawID,
				err.Error(),
			)
	}

	enrichedCtx := observability.EnrichLogsWithRulesetID(ctx, rulesetID)

	if err := s.rulesetDeleter.DeleteRuleset(enrichedCtx, rulesetID); err != nil {
		return nil, err
	}
	s.logger.Info(enrichedCtx, "Deleted ruleset")

	return &emptypb.Empty{}, nil
}

func (s *Server) CalculateCarKeyV2(
	ctx context.Context,
	req *contracts.CalculateCarKeyRequestV2,
) (*contracts.CarKey, error) {
	rulesetID, err := getRulesetID(req)
	if err != nil {
		return nil, err
	}

	enrichedCtx := observability.EnrichLogsWithRulesetID(ctx, rulesetID)

	selectionsEntity, err := toSelectionsEntity(req.Selections)
	if err != nil {
		return nil, err
	}

	fromEntity, err := toNilableStructureWeekEntity(req.FromWeek)
	if err != nil {
		return nil, err
	}

	toEntity, err := toNilableStructureWeekEntity(req.ToWeek)
	if err != nil {
		return nil, err
	}

	carKeyEntity, err := s.carKeyCalculator.CalculateCarKeyV2(
		enrichedCtx,
		rulesetID,
		selectionsEntity,
		fromEntity,
		toEntity,
	)
	if err != nil {
		return nil, err
	}

	carKey := toCarKeyContract(carKeyEntity)
	return carKey, nil
}

func (s *Server) CalculateStartCarKeys(
	ctx context.Context,
	req *contracts.CalculateStartCarKeysRequest,
) (*contracts.StartCarKeysResponse, error) {
	rulesetID, err := getRulesetID(req)
	if err != nil {
		return nil, err
	}

	enrichedCtx := observability.EnrichLogsWithRulesetID(ctx, rulesetID)

	startCarKeyEntities, err := s.startCarKeysCalculator.CalculateStartCarKeys(enrichedCtx, rulesetID)
	if err != nil {
		return nil, err
	}

	startCarKeyContracts := toCarKeyInPeriodContracts(startCarKeyEntities)

	return &contracts.StartCarKeysResponse{
		CarKeys: startCarKeyContracts,
	}, nil
}

func (s *Server) CalculateBaseCarKeys(
