)

type Router struct {
	logger            *logging.Logger
	router            chi.Router
	loggingMiddleware *logging.LoggingMiddleware
}

func NewRouter(
	logger *logging.Logger,
	server *httpserver.Server,
	loggingMiddleware *logging.LoggingMiddleware,
) Router {
	return Router{
		logger:            logger,
		router:            server.GetRouter(),
		loggingMiddleware: loggingMiddleware,
	}
}

func (r Router) AddRoutes() {
	r.router.Mount("/debug", chimiddleware.Profiler())

	r.router.Route("/", func(rr chi.Router) {
		rr.Use(
			r.commonMiddlewares()...,
		)
	})
}

func (r Router) commonMiddlewares() []func(http.Handler) http.Handler {
	return []func(http.Handler) http.Handler{
		r.loggingMiddleware.LogRequest(),
		r.loggingMiddleware.LogResponse(),
		chimiddleware.Compress(5),
	}
}

