package config

import (
	"fmt"
	"os"

	"github.com/ourstudio-se/binder"
)

type Config struct {
	LogLevel string `config:"LOG_LEVEL"`

	Host     string `config:"HOST"`
	HttpPort string `config:"HTTP_PORT"`
	GrpcPort string `config:"GRPC_PORT"`

	JwksURL     string `config:"JWKS_URL"`
	JWTIssuer   string `config:"JWT_ISSUER"`
	JWTAudience string `config:"JWT_AUDIENCE"`

	SkipSentry        bool   `config:"SKIP_SENTRY"`
	SentryDSN         string `config:"SENTRY_DSN"`
	SentryEnvironment string `config:"SENTRY_ENVIRONMENT"`
	SentryServiceName string `config:"SENTRY_SERVICE_NAME"`

	GLPKUrl    string `config:"GLPK_URL"`
	GLPKApiKey string `config:"GLPK_API_KEY"`

	DatabaseHost                string `config:"DATABASE_HOST"`
	DatabaseMigrationUser       string `config:"DATABASE_MIGRATION_USER"`
	DatabaseMigrationPassword   string `config:"DATABASE_MIGRATION_PASSWORD"`
	DatabaseApplicationUser     string `config:"DATABASE_APPLICATION_USER"`
	DatabaseApplicationPassword string `config:"DATABASE_APPLICATION_PASSWORD"`
	DatabasePort                string `config:"DATABASE_PORT"`
	DatabaseName                string `config:"DATABASE_NAME"`
	DatabaseSSLMode             string `config:"DATABASE_SSL_MODE"`

	OtelServiceName       string `config:"OTEL_SERVICE_NAME"`
	SkipMetricsCollection bool   `config:"SKIP_METRICS_COLLECTION"`
}

func (cfg Config) HttpAddress() string {
	return fmt.Sprintf("%s:%s", cfg.Host, cfg.HttpPort)
}

func (cfg Config) GrpcAddress() string {
	return fmt.Sprintf("%s:%s", cfg.Host, cfg.GrpcPort)
}

func NewBinder() *binder.Config {
	return binder.New(
		binder.WithFile(".secrets", "="),
		binder.WithFile("../../.secrets", "="),
		binder.WithFile("/etc/secrets/.secrets", ":"),
		binder.WithEnv(),
	)
}

func New(binder *binder.Config) Config {
	var cfg Config
	binder.Bind(&cfg)

	setOtelExporterEnvironmentVariable(binder)
	return cfg
}

// For local development, we want to set the OTEL_EXPORTER_OTLP_ENDPOINT
// In the Bakery environment this is set by Kubernetes
func setOtelExporterEnvironmentVariable(binder *binder.Config) {
	otelEnvironmentVariable := "OTEL_EXPORTER_OTLP_ENDPOINT"
	if v, ok := binder.Values().Get(otelEnvironmentVariable); ok {
		_ = os.Setenv(otelEnvironmentVariable, v)
	}
}

