package app

import (
	"context"
	"net"

	"github.com/go-errors/errors"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/volvo-cars/caas-car-configurator/internal/api/httpserver"
	"github.com/volvo-cars/caas-car-configurator/internal/app/config"
	"github.com/volvo-cars/caas-car-configurator/internal/database/postgres"
	"github.com/volvo-cars/caas-car-configurator/internal/observability"
	httpserversdk "github.com/volvo-cars/go-httpserver"
	logging "github.com/volvo-cars/ooe-product-offer-logging"
	"go.uber.org/fx"
	"google.golang.org/grpc"
)

func startHTTPServer(
	lc fx.Lifecycle,
	server *httpserversdk.Server,
	cfg config.Config,
	logger *logging.Logger,
	shutdowner fx.Shutdowner,
) {
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			go func() {
				addr := cfg.HttpAddress()
				if err := server.Start(addr); err != nil {
					logger.Error(ctx, "run http server", err)
					shutdown(ctx, logger, shutdowner)
				}
			}()

			return nil
		},
		OnStop: func(ctx context.Context) error {
			return server.Shutdown(ctx)
		},
	})
}

func addRoutes(router httpserver.Router) {
	router.AddRoutes()
}

func startGRPCServer(
	lc fx.Lifecycle,
	server *grpc.Server,
	cfg config.Config,
	logger *logging.Logger,
	shutdowner fx.Shutdowner,
) {
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			listener, err := net.Listen("tcp", cfg.GrpcAddress())
			if err != nil {
				return errors.Wrap(err, 0)
			}
			go func() {
				if err := server.Serve(listener); err != nil {
					logger.Error(ctx, "run grpc server", err)
					shutdown(ctx, logger, shutdowner)
				}
			}()

			return nil
		},
		OnStop: func(ctx context.Context) error {
			server.Stop()
			return nil
		},
	})
}

func initializeSentry(lc fx.Lifecycle, client sentryClient) {
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			if err := client.Init(); err != nil {
				return err
			}
			return nil
		},
		OnStop: func(ctx context.Context) error {
			client.Close()
			return nil
		},
	})
}

func migrateDatabase(
	lc fx.Lifecycle,
	migrator *postgres.Migrator,
	logger *logging.Logger,
) {
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			if err := migrator.Migrate(); err != nil {
				logger.Error(ctx, "migrate database error", err)
				return err
			}

			return nil
		},
	})
}

func closePostgresPool(lc fx.Lifecycle, pool *pgxpool.Pool) {
	lc.Append(fx.Hook{
		OnStop: func(ctx context.Context) error {
			pool.Close()
			return nil
		},
	})
}

func startMetricsCollection(
	lc fx.Lifecycle,
	submitter *observability.MetricsSubmitter,
) {
	lc.Append(fx.Hook{
		OnStart: func(ctx context.Context) error {
			return submitter.Start(ctx)
		},
		OnStop: func(ctx context.Context) error {
			return submitter.Shutdown(ctx)
		},
	})
}

