}

func newSentryClient(cfg config.Config) (sentryClient, error) {
	if cfg.SkipSentry {
		return &noopSentryClientImpl{}, nil
	}

	sentryCfg, err := newSentryConfig(cfg)
	if err != nil {
		return nil, err
	}

	return newSentryClientImpl(sentryCfg), nil
}

type sentryConfig struct {
	Dsn         string
	Environment string
	LogLevel    string
	ServiceName string
}

func newSentryConfig(cfg config.Config) (sentryConfig, error) {
	if cfg.SentryDSN == "" {
		return sentryConfig{}, errors.New("no dsn specified")
	}

	if cfg.SentryEnvironment == "" {
		return sentryConfig{}, errors.New("no environment specified")
	}

	if cfg.SentryServiceName == "" {
		return sentryConfig{}, errors.New("no service name specified")
	}

	return sentryConfig{
		Dsn:         cfg.SentryDSN,
		Environment: cfg.SentryEnvironment,
		LogLevel:    cfg.LogLevel,
		ServiceName: cfg.SentryServiceName,
	}, nil
}

type noopSentryClientImpl struct{}

func (n *noopSentryClientImpl) Init() error {
	return nil
}

func (n *noopSentryClientImpl) Close() {}

func (n *noopSentryClientImpl) CaptureException(err error) {}

type sentryClientImpl struct {
	flushFunc   func()
	options     sentry.ClientOptions
	serviceName string
}

func (c *sentryClientImpl) Init() error {
	if err := sentry.Init(c.options); err != nil {
		return err
	}

	return nil
}

func (c *sentryClientImpl) Close() {
	if c.flushFunc != nil {
		c.flushFunc()
	}
}

func (c *sentryClientImpl) CaptureException(err error) {
	sentry.WithScope(func(scope *sentry.Scope) {
		scope.SetTag("service", c.serviceName)
		scope.SetTag("caas", "true")
		sentry.CaptureException(err)
	})
}

func newSentryClientImpl(cfg sentryConfig) *sentryClientImpl {
	isDebug := strings.ToLower(cfg.LogLevel) == "debug"
	return &sentryClientImpl{
		flushFunc: func() {
			sentry.Flush(2 * time.Second)
		},
		options: sentry.ClientOptions{
			Dsn:              cfg.Dsn,
			Environment:      cfg.Environment,
			Debug:            isDebug,
			AttachStacktrace: true,
		},
		serviceName: cfg.ServiceName,
	}
}

