ast.text:
package postgres

import (
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

func ToStoredCarRuleset(carRuleset ruleset.CarRuleset) StoredCarRuleset {
	carDetails := toStoredCarDetails(carRuleset.Details())
	ruleset := toStoredConfigurationRuleset(carRuleset.Ruleset())
	components := toManyStoredComponents(carRuleset.Components())
	packageComponents := toManyStoredPackageComponents(carRuleset.PackageComponents())

	return StoredCarRuleset{
		CarDetails:        carDetails,
		Ruleset:           ruleset,
		Components:        components,
		PackageComponents: packageComponents,
	}
}

func toStoredCarDetails(details specification.CarDetails) StoredCarDetails {
	return StoredCarDetails{
		ModelYear:        details.ModelYear(),
		SpecMarket:       details.SpecMarket(),
		CarType:          details.CarType(),
		Engine:           details.Engine(),
		SalesVersion:     details.SalesVersion(),
		Body:             details.Body(),
		Gearbox:          details.Gearbox(),
		Steering:         details.Steering(),
		MarketingCode:    details.MarketingCode(),
		LocalEditionCode: details.LocalEditionCode(),
	}
}

func toStoredConfigurationRuleset(ruleset *puan.Ruleset) StoredConfigurationRuleset {
	polyhedron := StoredPolyhedron{
		AMatrix: ruleset.Polyhedron().A(),
		BVector: ruleset.Polyhedron().B(),
	}

	periodVariables := toStoredTimeBoundVariables(ruleset.PeriodVariables())

	return StoredConfigurationRuleset{
		Polyhedron:           polyhedron,
		SelectableVariables:  ruleset.SelectableVariables(),
		DependentVariables:   ruleset.DependentVariables(),
		IndependentVariables: ruleset.IndependentVariables(),
		PreferredVariables:   ruleset.PreferredVariables(),
		PeriodVariables:      periodVariables,
	}
}

func toStoredTimeBoundVariables(variables puan.TimeBoundVariables) StoredTimeBoundVariables {
	storedVariables := make(StoredTimeBoundVariables, len(variables))
	for i, variable := range variables {
		storedVariables[i] = toStoredTimeBoundVariable(variable)
	}

	return storedVariables
}

func toStoredTimeBoundVariable(variable puan.TimeBoundVariable) StoredTimeBoundVariable {
	return StoredTimeBoundVariable{
		Variable: variable.Variable(),
		Period: StoredPeriod{
			From: variable.Period().From(),
			To:   variable.Period().To(),
		},
	}
}

func toManyStoredComponents(entities ruleset.ManyComponents) ManyStoredComponents {
	components := make(ManyStoredComponents, len(entities))
	for i, entity := range entities {
		components[i] = toStoredComponent(entity)
	}

	return components
}

func toStoredComponent(entity ruleset.Component) StoredComponent {
	return StoredComponent{
		Code: entity.Code().String(),
		Type: entity.Type().String(),
	}
}

func toManyStoredPackageComponents(
	entities ruleset.ManyPackageComponents,
) ManyStoredPackageComponents {
	components := make(ManyStoredPackageComponents, len(entities))
	for i, entity := range entities {
		components[i] = toStoredPackageComponent(entity)
	}

	return components
}

func toStoredPackageComponent(
	entity ruleset.PackageComponent,
) StoredPackageComponent {
	variants := toManyStoredPackageVariants(entity.Variants())

	return StoredPackageComponent{
		Code:     entity.Code().String(),
		Variants: variants,
	}
}

func toManyStoredPackageVariants(entities ruleset.ManyPackageVariants) []ManyStoredComponents {
	variants := make([]ManyStoredComponents, len(entities))
	for i, entity := range entities {
		variant := ruleset.ManyComponents(entity)
		variants[i] = toManyStoredComponents(variant)
	}

	return variants
}

func ToStoredCarSpecification(specification specification.CarSpecification) StoredCarSpecification {
	carDetails := toStoredCarDetails(specification.Details())
	period := toStoredStructureWeekPeriod(specification.Period())
	forbiddenPeriods := toManyStoredStructureWeekPeriods(specification.ForbiddenPeriods())
	sMessages := toStoredSMessageSpecification(specification.SMessages())
	styling := toStoredStylingSpecification(specification.Styling())
	options := toStoredOptionsSpecification(specification.Options())
	packages := toStoredPackageSpecification(specification.Packages())
	wheels := toStoredWheelSpecification(specification.Wheels())

	return StoredCarSpecification{
		CarDetails:          carDetails,
		StructureWeekPeriod: period,
		ForbiddenPeriods:    forbiddenPeriods,
		SMessages:           sMessages,
		Stylings:            styling,
		Options:             options,
		Packages:            packages,
		Wheels:              wheels,
	}
}

func toManyStoredStructureWeekPeriods(
	periods specification.ManyStructureWeekPeriods,
) ManyStoredStructureWeekPeriods {
	stored := make(ManyStoredStructureWeekPeriods, len(periods))
	for i, period := range periods {
		stored[i] = toStoredStructureWeekPeriod(period)
	}

	return stored
}

func toStoredStructureWeekPeriod(
	period specification.StructureWeekPeriod,
) StoredStructureWeekPeriod {
	return StoredStructureWeekPeriod{
		From: toStoredStructureWeek(period.From()),
		To:   toStoredStructureWeek(period.To()),
	}
}

func toStoredStructureWeek(structureWeek specification.StructureWeek) StoredStructureWeek {
	return StoredStructureWeek{
		Year: structureWeek.Year(),
		Week: structureWeek.Week(),
	}
}

func toStoredSMessageSpecification(
	specification specification.SMessageSpecification,
) StoredSMessageSpecification {
	storedSMessages := make([]StoredSMessage, len(specification.SMessages()))
	for i, sMessage := range specification.SMessages() {
		storedSMessages[i] = toStoredSMessage(sMessage)
	}

	return StoredSMessageSpecification{
		SMessages: storedSMessages,
	}
}

func toStoredSMessage(sMessage specification.SMessage) StoredSMessage {
	return StoredSMessage{
		Code:   sMessage.Code().String(),
		Period: toStoredStructureWeekPeriod(sMessage.Period()),
	}
}

func toStoredStylingSpecification(
	specification specification.StylingSpecification,
) StoredStylingSpecification {
	storedColors := make(ManyStoredColors, len(specification.Colors()))
	for i, color := range specification.Colors() {
		storedColors[i] = toStoredColor(color)
	}

	storedUpholsteries := make(ManyStoredUpholsteries, len(specification.Upholsteries()))
	for i, upholstery := range specification.Upholsteries() {
		storedUpholsteries[i] = toStoredUpholstery(upholstery)
	}

	storedDefaultColors := make(
		ManyStoredTimeBoundCodes,
		len(specification.DefaultColors()),
	)
	for i, defaultColor := range specification.DefaultColors() {
		storedDefaultColors[i] = toStoredTimeBoundCode(defaultColor)
	}

	storedDefaultUpholsteries := make(
		ManyStoredTimeBoundCodes,
		len(specification.DefaultUpholsteries()),
	)
	for i, defaultUpholstery := range specification.DefaultUpholsteries() {
		storedDefaultUpholsteries[i] = toStoredTimeBoundCode(defaultUpholstery)
	}

	return StoredStylingSpecification{
		Colors:              storedColors,
		Upholsteries:        storedUpholsteries,
		DefaultColors:       storedDefaultColors,
		DefaultUpholsteries: storedDefaultUpholsteries,
	}
}

func toStoredColor(color specification.Color) StoredColor {
	return StoredColor{
		Code:                color.Code().String(),
		RequiredOptions:     toStoredTimeBoundAtLeastOnes(color.RequiredOptions()),
		RequiredWheels:      toStoredTimeBoundExactlyOnes(color.RequiredWheels()),
		ForbidsOptions:      toStoredForbidden(color.ForbidsOptions()),
		ForbidsWheels:       toStoredForbidden(color.ForbidsWheels()),
		ForbidsUpholsteries: toStoredForbidden(color.ForbidsUpholsteries()),
		Period:              toStoredStructureWeekPeriod(color.Period()),
	}
}

func toStoredUpholstery(upholstery specification.Upholstery) StoredUpholstery {
	return StoredUpholstery{
		Code:            upholstery.Code().String(),
		RequiredOptions: toStoredTimeBoundAtLeastOnes(upholstery.RequiredOptions()),
		ForbidsOptions:  toStoredForbidden(upholstery.ForbidsOptions()),
		ForbidsColors:   toStoredForbidden(upholstery.ForbidsColors()),
		ForbidsWheels:   toStoredForbidden(upholstery.ForbidsWheels()),
		Period:          toStoredStructureWeekPeriod(upholstery.Period()),
	}
}

func toStoredTimeBoundCode(entity specification.TimeBoundCode) StoredTimeBoundCode {
	period := toStoredStructureWeekPeriod(entity.Period())
	return StoredTimeBoundCode{
		Code:   entity.Code().String(),
		Period: period,
	}
}

func toStoredOptionsSpecification(
	specification specification.OptionSpecification,
) StoredOptionSpecification {
	storedOptions := make([]StoredOption, len(specification.Options()))
	for i, option := range specification.Options() {
		storedOptions[i] = toStoredOption(option)
	}

	includedOptions := toStoredTimeBoundExactlyOnes(specification.IncludedOptions())
	combinedRequirements := toManyStoredCombinedOptionRequirements(
		specification.CombinedRequirements(),
	)

	return StoredOptionSpecification{
		Options:                storedOptions,
		PackageOnlyOptionCodes: specification.PackageOnlyOptions().Strings(),
		IncludedOptions:        includedOptions,
		CombinedRequirements:   combinedRequirements,
	}
}

func toManyStoredCombinedOptionRequirements(
	requirements specification.ManyCombinedOptionRequirements,
) []StoredCombinedOptionRequirement {
	stored := make(ManyStoredCombinedOptionRequirements, len(requirements))
	for i, req := range requirements {
		stored[i] = toStoredCombinedOptionRequirement(req)
	}

	return stored
}

func toStoredCombinedOptionRequirement(
	requirement specification.CombinedOptionRequirement,
) StoredCombinedOptionRequirement {
	return StoredCombinedOptionRequirement{
		RequiringCodes: requirement.RequiringCodes().Strings(),
		RequiredCode:   requirement.RequiredCode().String(),
	}
}

func toStoredOption(option specification.Option) StoredOption {
	return StoredOption{
		Code:                 option.Code().String(),
		RequiredColors:       toStoredTimeBoundExactlyOnes(option.RequiredColors()),
		RequiredUpholsteries: toStoredTimeBoundExactlyOnes(option.RequiredUpholsteries()),
		RequiredOptions:      toStoredTimeBoundAtLeastOnes(option.RequiredOptions()),
		RequiredWheels:       toStoredTimeBoundExactlyOnes(option.RequiredWheels()),
		ForbidsOptions:       toStoredForbidden(option.ForbidsOptions()),
		ForbidsColors:        toStoredForbidden(option.ForbidsColors()),
		ForbidsWheels:        toStoredForbidden(option.ForbidsWheels()),
		ForbidsUpholsteries:  toStoredForbidden(option.ForbidsUpholsteries()),
		Period:               toStoredStructureWeekPeriod(option.Period()),
	}
}

func toStoredPackageSpecification(
	specification specification.PackageSpecification,
) StoredPackageSpecification {
	storedPackages := make([]StoredPackage, len(specification.Packages()))
	for i, pkg := range specification.Packages() {
		storedPackages[i] = toStoredPackage(pkg)
	}

	return StoredPackageSpecification{
		Packages:         storedPackages,
		IncludedPackages: toStoredTimeBoundExactlyOnes(specification.IncludedPackages()),
	}
}

func toStoredPackage(pkg specification.Package) StoredPackage {
	return StoredPackage{
		Code:                 pkg.Code().String(),
		RequiredColors:       toNilableStoredExactlyOne(pkg.RequiredColors()),
		RequiredUpholsteries: toNilableStoredExactlyOne(pkg.RequiredUpholsteries()),
		RequiredWheels:       toNilableStoredExactlyOne(pkg.RequiredWheels()),
		RequiredOptions:      toStoredExactlyOnes(pkg.RequiredOptions()),
		Period:               toStoredStructureWeekPeriod(pkg.Period()),
	}
}

func toStoredWheelSpecification(
	specification specification.WheelSpecification,
) StoredWheelSpecification {
	storedWheels := make([]StoredWheel, len(specification.Wheels()))
	for i, wheel := range specification.Wheels() {
		storedWheels[i] = toStoredWheel(wheel)
	}

	standardWheel := toNilableString(specification.StandardWheel())

	return StoredWheelSpecification{
		Wheels:        storedWheels,
		StandardWheel: standardWheel,
	}
}

func toStoredWheel(wheel specification.Wheel) StoredWheel {
	return StoredWheel{
		Code:                 wheel.Code().String(),
		RequiredColors:       toStoredTimeBoundExactlyOnes(wheel.RequiredColors()),
		RequiredOptions:      toStoredTimeBoundAtLeastOnes(wheel.RequiredOptions()),
		RequiredUpholsteries: toStoredTimeBoundExactlyOnes(wheel.RequiredUpholsteries()),
		ForbidsOptions:       toStoredForbidden(wheel.ForbidsOptions()),
		ForbidsUpholsteries:  toStoredForbidden(wheel.ForbidsUpholsteries()),
		Period:               toStoredStructureWeekPeriod(wheel.Period()),
	}
}

func toStoredExactlyOnes(
	exactlyOnes specification.ManyExactlyOne,
) []StoredPermanentExactlyOne {
	storedExactlyOnes := make([]StoredPermanentExactlyOne, len(exactlyOnes))
	for i, exactlyOne := range exactlyOnes {
		storedExactlyOnes[i] = toStoredExactlyOne(exactlyOne)
	}

	return storedExactlyOnes
}

func toStoredExactlyOne(
	exactlyOne specification.ExactlyOne,
) StoredPermanentExactlyOne {
	return StoredPermanentExactlyOne{
		Codes:       exactlyOne.Codes().Strings(),
		DefaultCode: toNilableString(exactlyOne.DefaultCode()),
	}
}

func toNilableStoredExactlyOne(
	exactlyOne *specification.ExactlyOne,
) *StoredPermanentExactlyOne {
	if exactlyOne == nil {
		return nil
	}

	storedExactlyOne := toStoredExactlyOne(*exactlyOne)

	return &storedExactlyOne
}

func toStoredTimeBoundExactlyOnes(
	exactlyOnes specification.ManyTimeBoundExactlyOne,
) []StoredTimeBoundExactlyOne {
	storedExactlyOnes := make([]StoredTimeBoundExactlyOne, len(exactlyOnes))
	for i, exactlyOne := range exactlyOnes {
		storedExactlyOnes[i] = toStoredTimeBoundExactlyOne(exactlyOne)
	}

