	return StoredTimeBoundExactlyOne{
		Codes:       exactlyOne.Codes().Strings(),
		DefaultCode: toNilableString(exactlyOne.DefaultCode()),
		Period:      toStoredStructureWeekPeriod(exactlyOne.Period()),
	}
}

func toStoredTimeBoundAtLeastOnes(
	atLeastOnes specification.ManyTimeBoundAtLeastOne,
