package postgres

import (
	"github.com/google/uuid"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

func (r *StoredCarRuleset) AsEntity(id uuid.UUID) (ruleset.CarRuleset, error) {
	rulesetEntity, err := r.Ruleset.asEntity()
	if err != nil {
		return ruleset.CarRuleset{}, err
	}

	carDetailsEntity := r.CarDetails.asEntity()

	components, packageComponents, err := r.getComponentEntities()
	if err != nil {
		return ruleset.CarRuleset{}, err
	}

	return ruleset.Hydrate(
		id,
		&rulesetEntity,
		carDetailsEntity,
		components,
		packageComponents,
	), nil
}

func (r *StoredCarRuleset) getComponentEntities() (
	components ruleset.ManyComponents,
	packageComponents ruleset.ManyPackageComponents,
	err error,
) {
	components, err = r.Components.asManyEntities()
	if err != nil {
		return nil, nil, err
	}

	packageComponents, err = r.PackageComponents.asManyEntities()
	if err != nil {
		return nil, nil, err
	}

	return
}

func (d *StoredCarDetails) asEntity() specification.CarDetails {
	return specification.NewCarDetails(
		d.ModelYear,
		d.SpecMarket,
		d.CarType,
		d.Engine,
		d.SalesVersion,
		d.Body,
		d.Gearbox,
		d.Steering,
		d.MarketingCode,
		d.LocalEditionCode,
	)
}

func (c ManyStoredComponents) asManyEntities() (ruleset.ManyComponents, error) {
	entities := make(ruleset.ManyComponents, len(c))
	for i, component := range c {
		entity, err := component.asEntity()
		if err != nil {
			return nil, err
		}

		entities[i] = entity
	}
	return entities, nil
}

func (c StoredComponent) asEntity() (ruleset.Component, error) {
	code, err := specification.NewCode(c.Code)
	if err != nil {
		return ruleset.Component{}, err
	}

	typ, err := ruleset.NewComponentType(c.Type)
	if err != nil {
		return ruleset.Component{}, err
	}

	entity := ruleset.NewComponent(code, typ)

	return entity, nil
}

func (c ManyStoredPackageComponents) asManyEntities() (ruleset.ManyPackageComponents, error) {
	entities := make(ruleset.ManyPackageComponents, len(c))
	for i, component := range c {
		entity, err := component.asEntity()
		if err != nil {
			return nil, err
		}

		entities[i] = entity
	}
	return entities, nil
}

func (c StoredPackageComponent) asEntity() (ruleset.PackageComponent, error) {
	code, err := specification.NewCode(c.Code)
	if err != nil {
		return ruleset.PackageComponent{}, err
	}

	variantEntities := make(ruleset.ManyPackageVariants, len(c.Variants))
	for i, variant := range c.Variants {
		components, err := variant.asManyEntities()
		if err != nil {
			return ruleset.PackageComponent{}, err
		}

		variantEntity, err := ruleset.NewPackageVariant(components)
		if err != nil {
			return ruleset.PackageComponent{}, err
		}

		variantEntities[i] = variantEntity
	}

	return ruleset.NewPackageComponent(code, variantEntities)
}

func (r *StoredConfigurationRuleset) asEntity() (puan.Ruleset, error) {
	aMatrix := r.Polyhedron.AMatrix
	bVector := r.Polyhedron.BVector
	periodVariables, err := r.PeriodVariables.asEntity()
	if err != nil {
		return puan.Ruleset{}, err
	}

	return puan.HydrateRuleSet(
		aMatrix,
		bVector,
		r.DependentVariables,
		r.IndependentVariables,
		r.SelectableVariables,
		r.PreferredVariables,
		periodVariables,
	)
}

func (r StoredTimeBoundVariables) asEntity() (puan.TimeBoundVariables, error) {
	variables := make(puan.TimeBoundVariables, len(r))
	var err error
	for i, variable := range r {
