	return exactlyOnes, nil
}

func (s StoredTimeBoundExactlyOne) asEntity() (specification.TimeBoundExactlyOne, error) {
	codes, err := specification.NewCodes(s.Codes)
	if err != nil {
		return specification.TimeBoundExactlyOne{}, err
	}

	defaultCode, err := toNilableCodeEntity(s.DefaultCode)
	if err != nil {
		return specification.TimeBoundExactlyOne{}, err
	}

	period, err := s.Period.asEntity()
	if err != nil {
		return specification.TimeBoundExactlyOne{}, err
	}

	return specification.NewTimeBoundExactlyOne(codes, defaultCode, period)
}

