package postgres

import (
	"context"
	"embed"

	"github.com/go-errors/errors"
	"github.com/golang-migrate/migrate/v4"
	_ "github.com/golang-migrate/migrate/v4/database/postgres"
	_ "github.com/golang-migrate/migrate/v4/source/file"
	"github.com/golang-migrate/migrate/v4/source/iofs"
	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
)

//go:embed migrations/*.sql
var fs embed.FS

type Migrator struct {
	connectionString string
	logger           *loggingsdk.Logger
}

func NewMigrator(
	connectionString string,
	logger *loggingsdk.Logger,
) *Migrator {
	return &Migrator{
		connectionString: connectionString,
		logger:           logger,
	}
}

func (m *Migrator) Migrate() error {
	driver, err := iofs.New(fs, "migrations")
	if err != nil {
		return errors.Wrap(err, 0)
	}

	migration, err := migrate.NewWithSourceInstance("iofs", driver, m.connectionString)
	if err != nil {
		return errors.Wrap(err, 0)
	}
	defer migration.Close()

	m.logger.Info(context.Background(), "Attempting to apply new migrations")
	if err = migration.Up(); err != nil {
		switch {
		case errors.Is(err, migrate.ErrNoChange):
			m.logger.Info(context.Background(), "No new migrations")
			return nil
		default:
			return errors.Wrap(err, 0)
		}
	} else {
		m.logger.Info(context.Background(), "New migrations applied!")
	}

	return nil
}

