package postgres

import (
	"context"

	"github.com/go-errors/errors"
	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
	"github.com/volvo-cars/caas-car-configurator/internal/observability"
)

type Repository struct {
	pool   *pgxpool.Pool
	logger *loggingsdk.Logger
}

func NewRepository(pool *pgxpool.Pool, logger *loggingsdk.Logger) *Repository {
	return &Repository{
		pool:   pool,
		logger: logger,
	}
}

func (r *Repository) GetRuleset(
	ctx context.Context,
	id uuid.UUID,
) (ruleset.CarRuleset, error) {
	row := r.pool.QueryRow(
		ctx,
		`SELECT ruleset 
		FROM car_rulesets 
		WHERE id = $1`,
		id,
	)

	var stored StoredCarRuleset
	if err := row.Scan(&stored); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return ruleset.CarRuleset{},
				errors.Errorf(
					"%w ruleset with id '%s' not found",
					domainerror.NotFound,
					id,
				)
		}

		return ruleset.CarRuleset{}, errors.Wrap(err, 0)
	}

	return stored.AsEntity(id)
}

func (r *Repository) GetCarSpecification(
	ctx context.Context,
	rulesetID uuid.UUID,
) (specification.CarSpecification, error) {
	row := r.pool.QueryRow(
		ctx,
		`SELECT specification
		FROM car_specifications
		WHERE ruleset_id = $1`,
		rulesetID,
	)

	var spec StoredCarSpecification
	if err := row.Scan(&spec); err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return specification.CarSpecification{},
				errors.Errorf(
					"%w car specification for ruleset with id '%s' not found",
					domainerror.NotFound,
					rulesetID,
				)
		}

		return specification.CarSpecification{}, errors.Wrap(err, 0)
	}

	return spec.asEntity()
}

func (r *Repository) CreateRulesetForSpecification(
	ctx context.Context,
	rulesetEntity ruleset.CarRuleset,
	specificationEntity specification.CarSpecification,
) error {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return errors.Wrap(err, 0)
	}
	defer rollback(ctx, tx, r.logger)

	if err := r.insertRuleset(ctx, tx, rulesetEntity); err != nil {
		return errors.Wrap(err, 0)
	}

	// Store car specification of ruleset for:
	// - Auditing
	// - Troubleshooting
	// - Future reference if we need to recreate the ruleset
	if err := r.insertSpecification(ctx, tx, rulesetEntity.ID(), specificationEntity); err != nil {
		return errors.Wrap(err, 0)
	}

	return tx.Commit(ctx)
}

func (r *Repository) insertRuleset(
	ctx context.Context,
	tx pgx.Tx,
	ruleset ruleset.CarRuleset,
) error {
	stored := ToStoredCarRuleset(ruleset)
	clientID := observability.ClientIDFromContext(ctx)
	_, err := tx.Exec(
		ctx,
		`INSERT INTO car_rulesets (id, ruleset, client_id) 
			 VALUES ($1, $2, $3)`,
		ruleset.ID(),
		stored,
		clientID,
	)
	if err != nil {
		return errors.Wrap(err, 0)
	}

	return nil
}

func (r *Repository) insertSpecification(
	ctx context.Context,
	tx pgx.Tx,
	rulesetID uuid.UUID,
	specification specification.CarSpecification,
) error {
	stored := ToStoredCarSpecification(specification)
	_, err := tx.Exec(
		ctx,
		`INSERT INTO car_specifications (ruleset_id, specification) 
			 VALUES ($1, $2)`,
		rulesetID,
		stored,
	)
	if err != nil {
		return errors.Wrap(err, 0)
	}

	return nil
}

func (r *Repository) DeleteRuleset(
	ctx context.Context,
	id uuid.UUID,
) error {
	commandTag, err := r.pool.Exec(
		ctx,
		`DELETE FROM car_rulesets 
		WHERE id = $1`,
		id,
	)
	if err != nil {
		return errors.Wrap(err, 0)
	}

	if commandTag.RowsAffected() == 0 {
		return errors.Errorf(
			"%w ruleset with id '%s' not found",
			domainerror.NotFound,
			id,
		)
	}

	return nil
}

