func rollback(ctx context.Context, tx pgx.Tx, logger *logging.Logger) {
	err := tx.Rollback(ctx)
	if err != nil && err != pgx.ErrTxClosed {
		logger.Error(ctx, "rollback transaction", err)
	}
}

