ast.text:
package ruleset

import "github.com/go-errors/errors"

type BaseCarKeys struct {
	components        []ComponentCarKeys
	packageComponents []PackageVariantComponentCarKeys
}

func NewBaseCarKeys(
	components []ComponentCarKeys,
	packageComponents []PackageVariantComponentCarKeys,
) BaseCarKeys {
	return BaseCarKeys{
		components:        components,
		packageComponents: packageComponents,
	}
}

func (c BaseCarKeys) Components() []ComponentCarKeys {
	return c.components
}

func (c BaseCarKeys) PackageComponents() []PackageVariantComponentCarKeys {
	return c.packageComponents
}

type BaseCarKeysCreator struct {
	carKeysLookup map[string][]CarKeyInPeriod
}

func NewBaseCarKeysCreator(
	carKeysLookup map[string][]CarKeyInPeriod,
) *BaseCarKeysCreator {
	return &BaseCarKeysCreator{
		carKeysLookup: carKeysLookup,
	}
}

func (c *BaseCarKeysCreator) New(
	components ManyComponents,
	packageVariantComponents ManyPackageVariantComponents,
) (BaseCarKeys, error) {
	componentKeys, err := c.toComponentBaseCarKeys(components)
	if err != nil {
		return BaseCarKeys{}, err
	}

	packageVariantComponentKeys, err := c.toPackageVariantComponentBaseCarKeys(
		packageVariantComponents,
	)
	if err != nil {
		return BaseCarKeys{}, err
	}

	baseCarKeys := NewBaseCarKeys(componentKeys, packageVariantComponentKeys)
	return baseCarKeys, nil
}

func (c *BaseCarKeysCreator) toComponentBaseCarKeys(
	components []Component,
) (ManyComponentCarKeys, error) {
	keys, err := c.toManyComponentCarKeys(components)
	if err != nil {
		return nil, err
	}

	validKeys, err := c.filterOutInvalid(keys)
	if err != nil {
		return nil, err
	}

	return validKeys, nil
}

func (c *BaseCarKeysCreator) filterOutInvalid(
	keys ManyComponentCarKeys,
) (ManyComponentCarKeys, error) {
	var validated ManyComponentCarKeys
	for _, componentKeys := range keys {
		var validCarKeys []CarKeyInPeriod
		for _, carKey := range componentKeys.CarKeys() {
			isValid, err := isValidBaseCarKey(carKey, componentKeys.Component())
			if err != nil {
				return nil, err
			}

			if isValid {
				validCarKeys = append(validCarKeys, carKey)
			}
		}

		validComponentKeys := NewComponentCarKeys(componentKeys.Component(), validCarKeys)
		validated = append(validated, validComponentKeys)
	}

	return validated, nil
}

func (c *BaseCarKeysCreator) toManyComponentCarKeys(
	components []Component,
) (ManyComponentCarKeys, error) {
	allComponentKeys := make(ManyComponentCarKeys, len(components))
	for i, component := range components {
		componentKeys, err := c.newComponentCarKeys(component)
		if err != nil {
			return nil, err
		}

		allComponentKeys[i] = componentKeys
	}

	return allComponentKeys, nil
}

func (c *BaseCarKeysCreator) newComponentCarKeys(
	component Component,
) (ComponentCarKeys, error) {
	id := component.ID()
	keys, ok := c.carKeysLookup[id]
	if !ok {
		return ComponentCarKeys{}, errors.Errorf("Car keys not found for component with id %q", id)
	}

	componentKeys := NewComponentCarKeys(component, keys)

	return componentKeys, nil
}

func (c *BaseCarKeysCreator) toPackageVariantComponentBaseCarKeys(
	packageVariantComponents []PackageVariantComponent,
) (ManyPackageVariantComponentCarKeys, error) {
	keys, err := c.toManyPackageVariantComponentCarKeys(packageVariantComponents)
	if err != nil {
		return nil, err
	}

	validKeys, err := c.filterOutInvalidForPackages(keys)
	if err != nil {
		return nil, err
	}

	return validKeys, nil
}

func (c *BaseCarKeysCreator) filterOutInvalidForPackages(
	keys ManyPackageVariantComponentCarKeys,
) (ManyPackageVariantComponentCarKeys, error) {
	var validated ManyPackageVariantComponentCarKeys
	for _, componentKeys := range keys {
		var validCarKeys []CarKeyInPeriod
		for _, carKey := range componentKeys.CarKeys() {
			isValid, err := isValidBaseCarKeyForPackage(carKey, componentKeys.Component())
			if err != nil {
				return nil, err
			}

			if isValid {
				validCarKeys = append(validCarKeys, carKey)
			}
		}

		validComponentKeys := NewPackageVariantComponentCarKeys(componentKeys.Component(), validCarKeys)
		validated = append(validated, validComponentKeys)
	}

	return validated, nil
}

func (c *BaseCarKeysCreator) toManyPackageVariantComponentCarKeys(
	packageVariantComponents []PackageVariantComponent,
) (ManyPackageVariantComponentCarKeys, error) {
	allComponentKeys := make(ManyPackageVariantComponentCarKeys, len(packageVariantComponents))
	for i, component := range packageVariantComponents {
		componentKeys, err := c.toPackageVariantComponentCarKeys(component)
		if err != nil {
			return nil, err
		}

		allComponentKeys[i] = componentKeys
	}

	return allComponentKeys, nil
}

func (c *BaseCarKeysCreator) toPackageVariantComponentCarKeys(
	component PackageVariantComponent,
) (PackageVariantComponentCarKeys, error) {
	id := component.ID()
	keys, ok := c.carKeysLookup[id]
	if !ok {
		return PackageVariantComponentCarKeys{},
			errors.Errorf(
				"Car keys not found for package component with id %q",
				id,
			)
	}

	componentKeys := NewPackageVariantComponentCarKeys(component, keys)

	return componentKeys, nil
}

func isValidBaseCarKey(
	carKey CarKeyInPeriod,
	component Component,
) (bool, error) {
	if carKey.isOutsideItsPeriod() {
		return false, nil
	}

	return carKey.CarKey().containsComponent(component)
}

func isValidBaseCarKeyForPackage(
	carKey CarKeyInPeriod,
	component PackageVariantComponent,
) (bool, error) {
	if carKey.isOutsideItsPeriod() {
		return false, nil
	}

	return carKey.CarKey().containsPackageVariant(component)
}

