package ruleset

import (
	"slices"

	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type CarKey struct {
	details specification.CarDetails

	sMessage   *specification.Code
	color      specification.Code
	upholstery specification.Code
	wheel      specification.Code
	options    []specification.Code
	packages   []specification.Code

	structureWeek specification.StructureWeek
}

func (key CarKey) Details() specification.CarDetails {
	return key.details
}

func (key CarKey) SMessage() *specification.Code {
	return key.sMessage
}

func (key CarKey) Color() specification.Code {
	return key.color
}

func (key CarKey) Upholstery() specification.Code {
	return key.upholstery
}

func (key CarKey) Wheel() specification.Code {
	return key.wheel
}

func (key CarKey) Options() specification.Codes {
	return key.options
}

func (key CarKey) Packages() specification.Codes {
	return key.packages
}

func (key CarKey) StructureWeek() specification.StructureWeek {
	return key.structureWeek
}

// nolint:gocyclo
func (key CarKey) containsComponent(component Component) (bool, error) {
	switch component.Type() {
	case ComponentTypeSMessage:
		return key.sMessage != nil && *key.sMessage == component.Code(), nil
	case ComponentTypeColor:
		return key.color == component.Code(), nil
	case ComponentTypeUpholstery:
		return key.upholstery == component.Code(), nil
	case ComponentTypeWheel:
		return key.wheel == component.Code(), nil
	case ComponentTypeOption:
		return slices.Contains(key.options, component.Code()), nil
	default:
		return false, errors.Errorf("unknown component type: %s", component.Type())
	}
}

func (key CarKey) containsPackageVariant(
	packageComponent PackageVariantComponent,
) (bool, error) {
	packageMissing := !slices.Contains(key.packages, packageComponent.Code())
	if packageMissing {
		return false, nil
	}

	for _, component := range packageComponent.Variant() {
		containsComponent, err := key.containsComponent(component)
		if err != nil {
			return false, err
		}

		if !containsComponent {
			return false, nil
		}
	}

	return true, nil
}

func (key CarKey) containsPackage(
	code specification.Code,
) bool {
	return slices.Contains(key.packages, code)
}

func NewCarKey(
	ruleset CarRuleset,
	solution puan.Solution,
	fromWeek *specification.StructureWeek,
) (CarKey, error) {
	structureWeek, err := resolveStructureWeek(solution, ruleset.ruleset, fromWeek)
	if err != nil {
		return CarKey{}, errors.WrapPrefix(err, "failed to resolve structure week", 0)
	}

	sMessageCodes := ruleset.components.filterByType(ComponentTypeSMessage).Codes()
	sMessage, err := extractOneOrNoneSelection(solution, sMessageCodes)
	if err != nil {
		return CarKey{}, errors.WrapPrefix(err, "failed to extract sMessage", 0)
	}

	colorCodes := ruleset.components.filterByType(ComponentTypeColor).Codes()
	color, err := extractSingleSelection(solution, colorCodes)
	if err != nil {
		return CarKey{}, errors.WrapPrefix(err, "failed to extract color", 0)
	}

	upholsteryCodes := ruleset.components.filterByType(ComponentTypeUpholstery).Codes()
	upholstery, err := extractSingleSelection(solution, upholsteryCodes)
	if err != nil {
		return CarKey{}, errors.WrapPrefix(err, "failed to extract upholstery", 0)
	}

	wheelCodes := ruleset.components.filterByType(ComponentTypeWheel).Codes()
	wheel, err := extractSingleSelection(solution, wheelCodes)
	if err != nil {
		return CarKey{}, errors.WrapPrefix(err, "failed to extract wheel", 0)
	}

	optionCodes := ruleset.components.filterByType(ComponentTypeOption).Codes()
	options := extractManySelections(solution, optionCodes)

	packageCodes := ruleset.packageComponents.Codes()
	packages := extractManySelections(solution, packageCodes)

	return CarKey{
		details:       ruleset.details,
		structureWeek: structureWeek,
		sMessage:      sMessage,
		color:         color,
		upholstery:    upholstery,
		wheel:         wheel,
		options:       options,
		packages:      packages,
	}, nil
}

func resolveStructureWeek(
	solution puan.Solution,
	ruleset *puan.Ruleset,
	fromWeek *specification.StructureWeek,
) (specification.StructureWeek, error) {
	solutionPeriod, err := ExtractSolutionPeriod(solution, ruleset)
	if err != nil {
		return specification.StructureWeek{}, err
	}

	if err := validateSolutionPeriod(solutionPeriod, fromWeek); err != nil {
		return specification.StructureWeek{}, err
	}

	structureWeek := selectStructureWeek(fromWeek, solutionPeriod.From())

	return structureWeek, nil
}

func ExtractSolutionPeriod(
	solution puan.Solution,
	ruleset *puan.Ruleset,
) (specification.StructureWeekPeriod, error) {
	period, err := ruleset.FindPeriodInSolution(solution)
	if err != nil {
		return specification.StructureWeekPeriod{}, err
	}

	return toStructureWeekPeriod(period)
}

func validateSolutionPeriod(
	period specification.StructureWeekPeriod,
	fromWeek *specification.StructureWeek,
) error {
	if fromWeek == nil {
		return nil
	}

	if period.To().IsBefore(*fromWeek) {
		return errors.Errorf(
			"%w: solution period to %v is before week %v",
			domainerror.InvalidOperation,
			period.To(),
			*fromWeek,
		)
	}

	return nil
}

func selectStructureWeek(
	fromWeek *specification.StructureWeek,
	solutionWeek specification.StructureWeek,
) specification.StructureWeek {
	if fromWeek == nil {
		return solutionWeek
	}

	if fromWeek.IsBefore(solutionWeek) {
		return solutionWeek
	}

	return *fromWeek
}

func extractOneOrNoneSelection(
	solution puan.Solution,
	codes specification.Codes,
) (*specification.Code, error) {
	var selected *specification.Code
	for _, code := range codes {
		if isSet := solution[code.String()]; isSet == 1 {
			alreadySet := selected != nil
			if alreadySet {
				return nil, errors.Errorf(
					"found multiple matches in solution: %s and %s",
					selected,
					code,
				)
			}

			selected = &code
		}
	}

	return selected, nil
}

func extractSingleSelection(
	solution puan.Solution,
	colors specification.Codes,
) (specification.Code, error) {
	selected, err := extractOneOrNoneSelection(solution, colors)
	if err != nil {
		return "", err
	}

	if selected == nil {
		return "", errors.New("no selection found")
	}

	return *selected, nil
}

func extractManySelections(
	solution puan.Solution,
	codes specification.Codes,
) specification.Codes {
	var selections specification.Codes
	for _, code := range codes {
		if isSet := solution[code.String()]; isSet == 1 {
			selections = append(selections, code)
		}
	}

	return selections
}

type CarKeyInPeriod struct {
	carKey              CarKey
	structureWeekPeriod specification.StructureWeekPeriod
}

func (key CarKeyInPeriod) CarKey() CarKey {
	return key.carKey
}

func (key CarKeyInPeriod) StructureWeekPeriod() specification.StructureWeekPeriod {
	return key.structureWeekPeriod
}

func (key CarKeyInPeriod) isOutsideItsPeriod() bool {
	period := key.StructureWeekPeriod()
	week := key.CarKey().StructureWeek()
	return !week.IsWithin(period)
}

func NewCarKeyInPeriod(
	ruleset CarRuleset,
	solution puan.Solution,
	period specification.StructureWeekPeriod,
) (CarKeyInPeriod, error) {
	from := period.From()
	carKey, err := NewCarKey(ruleset, solution, &from)
	if err != nil {
		return CarKeyInPeriod{}, errors.WrapPrefix(err, "failed to create car key with period", 0)
	}

	return CarKeyInPeriod{
		carKey:              carKey,
		structureWeekPeriod: period,
	}, nil
}

type (
	CarKeyForSelectionGroup struct {
		carKey     CarKey
		selections puan.Selections
	}
	CarKeysBySelectionGroup []CarKeyForSelectionGroup
)

func NewCarKeyForSelectionGroup(
	carKey CarKey,
	selections puan.Selections,
) CarKeyForSelectionGroup {
	return CarKeyForSelectionGroup{
		carKey:     carKey,
		selections: selections,
	}
}

func (key CarKeyForSelectionGroup) CarKey() CarKey {
	return key.carKey
}

func (key CarKeyForSelectionGroup) Selections() puan.Selections {
	return key.selections
}

func NewCarKeysBySelectionGroup(
	ruleset CarRuleset,
	solutionsBySelectionGroup []puan.SolutionForSelectionGroup,
	fromWeek *specification.StructureWeek,
) (CarKeysBySelectionGroup, error) {
	carKeyBySelectionGroup := make(CarKeysBySelectionGroup, len(solutionsBySelectionGroup))
	for i, solutionForSelectionGroup := range solutionsBySelectionGroup {
		carKey, err := NewCarKey(
			ruleset,
			solutionForSelectionGroup.Solution(),
			fromWeek,
		)
		if err != nil {
			return nil, err
		}

		carKeyBySelectionGroup[i] = CarKeyForSelectionGroup{
			carKey:     carKey,
			selections: solutionForSelectionGroup.Selections(),
		}
	}

	return carKeyBySelectionGroup, nil
}

