package ruleset

import (
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type componentConfigurator struct {
	creator *puan.RulesetCreator

	code                specification.Code
	requiredExactlyOnes specification.ManyTimeBoundExactlyOne
	requiredAtLeastOnes specification.ManyTimeBoundAtLeastOne
	forbidden           specification.ManyForbids
}

func (c *configurationRulesetCreator) newComponentConfigurator(
	code specification.Code,
) *componentConfigurator {
	return &componentConfigurator{
		creator: c.RulesetCreator,
		code:    code,
	}
}

func (c *componentConfigurator) withForbidden(
	forbidden specification.ManyForbids,
) *componentConfigurator {
	c.forbidden = append(c.forbidden, forbidden...)

	return c
}

func (c *componentConfigurator) withRequiredTimeBoundExactlyOnes(
	required specification.ManyTimeBoundExactlyOne,
) *componentConfigurator {
	c.requiredExactlyOnes = append(c.requiredExactlyOnes, required...)

	return c
}

func (c *componentConfigurator) withRequiredTimeBoundAtLeastOnes(
	required specification.ManyTimeBoundAtLeastOne,
) *componentConfigurator {
	c.requiredAtLeastOnes = append(c.requiredAtLeastOnes, required...)

	return c
}

func (c *componentConfigurator) configure() error {
	err := c.addTimeBoundRequiredExactlyOnes()
	if err != nil {
		return err
	}

	err = c.addRequiredTimeBoundAtLeastOnes()
	if err != nil {
		return err
	}

	return c.addForbidden()
}

func (c *componentConfigurator) addTimeBoundRequiredExactlyOnes() error {
	for _, exactlyOne := range c.requiredExactlyOnes {
		err := c.addTimeBoundRequiredExactlyOne(exactlyOne)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *componentConfigurator) addTimeBoundRequiredExactlyOne(
	required specification.TimeBoundExactlyOne,
) error {
	exactlyOneID, err := c.setTimeBoundExactlyOne(required)
	if err != nil {
		return err
	}

	return c.assumeInPeriod(exactlyOneID, required.Period())
}

func (c *componentConfigurator) setTimeBoundExactlyOne(
	required specification.TimeBoundExactlyOne,
) (string, error) {
	id, err := setExactlyOne(c.creator, required.Codes())
	if err != nil {
		return "", err
	}

	if required.HasPreferred() {
		err = c.preferExactlyOne(*required.DefaultCode(), required.Period())
		if err != nil {
			return "", err
		}
	}

	return id, nil
}

func (c *componentConfigurator) assumeInPeriod(
	requiredID string,
	period specification.StructureWeekPeriod,
) error {
	id, err := c.creator.SetImply(c.code.String(), requiredID)
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.creator.AssumeInPeriod(
		id,
		from,
		to,
	)
}

func (c *componentConfigurator) addRequiredTimeBoundAtLeastOnes() error {
	for _, atLeastOne := range c.requiredAtLeastOnes {
		err := c.addRequiredTimeBoundAtLeastOne(atLeastOne)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *componentConfigurator) addRequiredTimeBoundAtLeastOne(
	required specification.TimeBoundAtLeastOne,
) error {
	atLeastOneID, err := c.setTimeBoundAtLeastOne(required)
	if err != nil {
		return err
	}

	return c.assumeInPeriod(atLeastOneID, required.Period())
}

func (c *componentConfigurator) setTimeBoundAtLeastOne(
	required specification.TimeBoundAtLeastOne,
) (string, error) {
	id, err := setAtLeastOne(c.creator, required.Codes())
	if err != nil {
		return "", err
	}

	if required.HasPreferred() {
		err = c.preferAtLeastOne(
			required.Codes(),
			*required.DefaultCode(),
			required.Period(),
		)
		if err != nil {
			return "", err
		}
	}

	return id, nil
}

func (c *componentConfigurator) addForbidden() error {
	for _, forbids := range c.forbidden {
		err := c.addForbids(forbids)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *componentConfigurator) addForbids(forbids specification.Forbids) error {
	forbidID, err := c.creator.SetNot(forbids.Code().String())
	if err != nil {
		return err
	}

	return c.assumeInPeriod(forbidID, forbids.Period())
}

func (c *componentConfigurator) preferExactlyOne(
	defaultCode specification.Code,
	period specification.StructureWeekPeriod,
) error {
	preferredID, err := c.creator.SetImply(c.code.String(), defaultCode.String())
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.creator.PreferInPeriod(preferredID, from, to)
}

func (c *componentConfigurator) preferAtLeastOne(
	requiredCodes specification.Codes,
	defaultRequiredCode specification.Code,
	period specification.StructureWeekPeriod,
) error {
	onlyPreferredID, err := setOnlyPreferred(
		c.creator,
		requiredCodes,
		defaultRequiredCode,
	)
	if err != nil {
		return err
	}

	preferredID, err := c.creator.SetImply(c.code.String(), onlyPreferredID)
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.creator.PreferInPeriod(preferredID, from, to)
}

// When doing preferred for OR, we need to create a support id for `x ∧ ¬y ∧ ¬z`,
// where x is the preferred code, and y and z are not-preferred codes.
// This function creates that support id.
func setOnlyPreferred(
	creator *puan.RulesetCreator,
	codes specification.Codes,
	defaultCode specification.Code,
) (string, error) {
	nonPreferred, err := codes.Without(defaultCode)
	if err != nil {
		return "", err
	}

	nonPreferredID, err := creator.SetNot(nonPreferred.Strings()...)
	if err != nil {
		return "", err
	}

	onlyPreferredID, err := creator.SetAnd(defaultCode.String(), nonPreferredID)
	if err != nil {
		return "", err
	}

	return onlyPreferredID, nil
}

