package ruleset

import (
	"slices"

	"github.com/go-errors/errors"
)

type ComponentType string

const (
	ComponentTypeSMessage   ComponentType = "S_MESSAGE"
	ComponentTypeOption     ComponentType = "OPTION"
	ComponentTypeColor      ComponentType = "COLOR"
	ComponentTypeUpholstery ComponentType = "UPHOLSTERY"
	ComponentTypeWheel      ComponentType = "WHEEL"
	ComponentTypePackage    ComponentType = "PACKAGE"
)

var validComponentTypes = []ComponentType{
	ComponentTypeSMessage,
	ComponentTypeOption,
	ComponentTypeColor,
	ComponentTypeUpholstery,
	ComponentTypeWheel,
}

func NewComponentType(raw string) (ComponentType, error) {
	typ := ComponentType(raw)
	invalidType := !slices.Contains(validComponentTypes, typ)
	if invalidType {
		return "", errors.Errorf("invalid component type: %s", raw)
	}
	return typ, nil
}

func (t ComponentType) String() string {
	return string(t)
}

