package ruleset

import (
	"fmt"
	"slices"
	"strings"

	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type (
	Component struct {
		code specification.Code
		typ  ComponentType
	}
	ManyComponents []Component
)

func NewComponent(
	code specification.Code,
	typ ComponentType,
) Component {
	return Component{
		code: code,
		typ:  typ,
	}
}

func (c Component) Code() specification.Code {
	return c.code
}

func (c Component) Type() ComponentType {
	return c.typ
}

func (c Component) ID() string {
	return fmt.Sprintf("%s-%s", c.typ, c.code)
}

func (c Component) AsAddSelection() puan.Selection {
	return c.asSelection(puan.ADD)
}

func (c Component) asSelection(
	action puan.Action,
) puan.Selection {
	selection := puan.NewSelectionBuilder(c.Code().String()).
		WithAction(action).
		Build()
	return selection
}

func (c ManyComponents) Codes() specification.Codes {
	var codes specification.Codes
	for _, component := range c {
		codes = append(codes, component.Code())
	}
	return codes
}

func (c ManyComponents) AsSelections() puan.Selections {
	selections := make(puan.Selections, len(c))
	for i, component := range c {
		selections[i] = component.AsAddSelection()
	}

	return selections
}

func (c ManyComponents) filterByType(typ ComponentType) ManyComponents {
	var filtered ManyComponents
	for _, component := range c {
		if component.Type() == typ {
			filtered = append(filtered, component)
		}
	}
	return filtered
}

type (
	PackageComponent struct {
		code     specification.Code
		variants ManyPackageVariants
	}
	ManyPackageComponents []PackageComponent
)

func NewPackageComponent(
	code specification.Code,
	variants ManyPackageVariants,
) (PackageComponent, error) {
	if len(variants) == 0 {
		return PackageComponent{}, errors.New("package component must have at least one variant")
	}

	return PackageComponent{
		code:     code,
		variants: variants,
	}, nil
}

func (c PackageComponent) Code() specification.Code {
	return c.code
}

func (c PackageComponent) Variants() ManyPackageVariants {
	return c.variants
}

func (c PackageComponent) hasSingleVariant() bool {
	return len(c.variants) == 1
}

func (c ManyPackageComponents) Codes() specification.Codes {
	var codes specification.Codes
	for _, component := range c {
		codes = append(codes, component.Code())
	}
	return codes
}

func (c ManyPackageComponents) AsVariants() (ManyPackageVariantComponents, error) {
	var variants ManyPackageVariantComponents
	for _, component := range c {
		for _, variant := range component.Variants() {
			variantComponent, err := NewPackageVariantComponent(component.Code(), variant)
			if err != nil {
				return nil, err
			}
			variants = append(variants, variantComponent)
		}
	}
	return variants, nil
}

type (
	PackageVariantComponent struct {
		code    specification.Code
		variant PackageVariant
	}
	ManyPackageVariantComponents []PackageVariantComponent
)

func NewPackageVariantComponent(
	code specification.Code,
	variant PackageVariant,
) (PackageVariantComponent, error) {
	if len(variant) == 0 {
		return PackageVariantComponent{}, errors.New("variant cannot be empty")
	}

	return PackageVariantComponent{
		code:    code,
		variant: variant,
	}, nil
}

func (c PackageVariantComponent) Code() specification.Code {
	return c.code
}

func (c PackageVariantComponent) Variant() PackageVariant {
	return c.variant
}

func (c PackageVariantComponent) AsAddSelection() puan.Selection {
	return c.asSelection(puan.ADD)
}

func (c PackageVariantComponent) asSelection(
	action puan.Action,
) puan.Selection {
	builder := puan.NewSelectionBuilder(c.Code().String()).
		WithAction(action)

	for _, subSelectionCode := range c.Variant().codes() {
		builder.WithSubSelectionID(subSelectionCode.String())
	}

	selection := builder.Build()
	return selection
}

func (c PackageVariantComponent) ID() string {
	variantComponentIDs := make([]string, len(c.variant))
	for i, component := range c.variant {
		variantComponentIDs[i] = component.ID()
	}

	slices.Sort(variantComponentIDs)

	return fmt.Sprintf(
		"%s-%s",
		c.Code(),
		strings.Join(variantComponentIDs, "-"),
	)
}

func (c ManyPackageVariantComponents) AsSelections() puan.Selections {
	selections := make(puan.Selections, len(c))
	for i, component := range c {
		selections[i] = component.AsAddSelection()
	}

	return selections
}

