func newComponentsFromSpecification(
	spec specification.CarSpecification,
) ManyComponents {
	var components ManyComponents

	sMessages := newComponents(
		spec.SMessages().SMessages().Codes(),
		ComponentTypeSMessage,
	)
	colors := newComponents(
		spec.Styling().Colors().Codes(),
		ComponentTypeColor,
	)
	upholsteries := newComponents(
		spec.Styling().Upholsteries().Codes(),
		ComponentTypeUpholstery,
	)
	wheels := newComponents(
		spec.Wheels().Wheels().Codes(),
		ComponentTypeWheel,
	)
	options := newComponents(
		spec.Options().Options().Codes(),
		ComponentTypeOption,
	)

	components = append(components, sMessages...)
	components = append(components, colors...)
	components = append(components, upholsteries...)
	components = append(components, wheels...)
	components = append(components, options...)

	return components
}

func newComponents(
	codes specification.Codes,
	componentType ComponentType,
) ManyComponents {
	components := make(ManyComponents, len(codes))
	for i, code := range codes {
		components[i] = NewComponent(code, componentType)
	}

	return components
}

func newPackageComponentsFromPackages(
	packages specification.Packages,
) (ManyPackageComponents, error) {
	packageComponents := make(ManyPackageComponents, len(packages))
	for i, pkg := range packages {
		packageComponent, err := newPackageComponentFromPackage(pkg)
		if err != nil {
			return nil, err
		}

		packageComponents[i] = packageComponent
	}

	return packageComponents, nil
}

func newPackageComponentFromPackage(
	pkg specification.Package,
) (PackageComponent, error) {
	variants := newPackageVariants(pkg)

	return NewPackageComponent(pkg.Code(), variants)
}

