package ruleset

import (
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

// groupPackagesByConnectedPeriods groups packages by their periods
// and merging any that are connected.
// Two periods are considered connected if one can reach the other
// through a chain of overlapping or touching periods.
// Period edges are inclusive since "from" starts at the beginning
// of the week and "to" ends at the end of the week.
// Example:
//
//	pkgA: 2025-W01 to 2025-W02
//	pkgB: 2025-W02 to 2025-W03
//	pkgC: 2025-W05 to 2025-W06
//
// Result:
//
//	2025-W01 to 2025-W03: [pkgA, pkgB]
//	2025-W05 to 2025-W06: [pkgC]
func groupPackagesByConnectedPeriods(
	packages specification.Packages,
) map[specification.StructureWeekPeriod]specification.Codes {
	groups := make(map[specification.StructureWeekPeriod]specification.Codes)

	packagesByPeriod := packages.GroupCodesByPeriod()
	periods := packages.Periods()
	sortedPeriods := periods.Sorted()
	if len(sortedPeriods) == 0 {
		return groups
	}

	period := sortedPeriods[0]
	codes := packagesByPeriod[period]
	for i := 1; i < len(sortedPeriods); i++ {
		nextPeriod := sortedPeriods[i]
		if period.ConnectsTo(nextPeriod) {
			codes = append(
				codes,
				packagesByPeriod[nextPeriod]...,
			)
			period = period.Join(nextPeriod)
		} else {
			groups[period] = append(
				groups[period],
				codes...,
			)
			period = nextPeriod
			codes = packagesByPeriod[nextPeriod]
		}
	}

	groups[period] = append(
		groups[period],
		codes...,
	)

	return groups
}

