package ruleset

import (
	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type (
	CarKeyForSelection struct {
		selection puan.Selection
		carKey    CarKey
	}
)

func NewCarKeyForSelection(
	selection puan.Selection,
	carKey CarKey,
) CarKeyForSelection {
	return CarKeyForSelection{
		selection: selection,
		carKey:    carKey,
	}
}

func (c CarKeyForSelection) Selection() puan.Selection {
	return c.selection
}

func (c CarKeyForSelection) CarKey() CarKey {
	return c.carKey
}

type NextSelectionsCalculator struct {
	carRuleset        CarRuleset
	currentSelections puan.Selections
}

func NewNextSelectionsCalculator(
	carRuleset CarRuleset,
	currentSelections puan.Selections,
) *NextSelectionsCalculator {
	return &NextSelectionsCalculator{
		carRuleset:        carRuleset,
		currentSelections: currentSelections,
	}
}

func (c *NextSelectionsCalculator) ValidateCurrentSelections() error {
	for _, selection := range c.currentSelections {
		if selection.Action() != puan.ADD {
			return errors.Errorf(
				"%w: only ADD selections are supported for next selections. Got %v",
				domainerror.InvalidOperation,
				selection,
			)
		}
	}

	return nil
}

func (c *NextSelectionsCalculator) Calculate() (puan.Selections, error) {
	nextComponentSelections := c.calculateAllComponentSelections()

	nextPackageComponentSelections, err := c.calculateAllPackageSelections()
	if err != nil {
		return nil, err
	}

	var nextSelections puan.Selections
	nextSelections = append(nextSelections, nextComponentSelections...)
	nextSelections = append(nextSelections, nextPackageComponentSelections...)

	return nextSelections, nil
}

func (c *NextSelectionsCalculator) calculateAllComponentSelections() puan.Selections {
	var selections puan.Selections
	for _, component := range c.carRuleset.Components() {
		selection := c.calculateSelectionForComponent(component)
		selections = append(selections, selection)
	}
	return selections
}

func (c *NextSelectionsCalculator) calculateSelectionForComponent(
	component Component,
) puan.Selection {
	action := c.calculateActionForCode(component.Code())
	selection := component.asSelection(action)

	return selection
}

func (c *NextSelectionsCalculator) calculateActionForCode(
	code specification.Code,
) puan.Action {
	builder := puan.NewSelectionBuilder(code.String())
	addSelection := builder.Build()

	hasSelection := selectionsContain(c.currentSelections, addSelection)
	if hasSelection {
		return puan.REMOVE
	}

	return puan.ADD
}

func (c *NextSelectionsCalculator) calculateAllPackageSelections() (puan.Selections, error) {
	var selections puan.Selections
	for _, packageComponent := range c.carRuleset.PackageComponents() {
		selectionsForPackage, err := c.calculateAllSelectionsForPackage(
			packageComponent,
		)
		if err != nil {
			return nil, err
		}

		selections = append(selections, selectionsForPackage...)
	}
	return selections, nil
}

func (c *NextSelectionsCalculator) calculateAllSelectionsForPackage(
	component PackageComponent,
) (puan.Selections, error) {
	if component.hasSingleVariant() {
		selection := c.calculateSelectionForSingleVariantPackage(component.Code())
		return puan.Selections{selection}, nil
	}

	return c.calculateSelectionsForMultiVariantPackage(component)
}

func (c *NextSelectionsCalculator) calculateSelectionForSingleVariantPackage(
	packageCode specification.Code,
) puan.Selection {
	builder := puan.NewSelectionBuilder(packageCode.String())

	action := c.calculateActionForCode(packageCode)
	builder.WithAction(action)

	selection := builder.Build()
	return selection
}

// To be consistent with the old solution, we only use
// package variant selections without mandatory codes.
//
// Example:
// Package has 2 variants:
// [a, b]
// [a, c]
//
// Used variants:
// [b]
// [c]
func (c *NextSelectionsCalculator) calculateSelectionsForMultiVariantPackage(
	component PackageComponent,
) (puan.Selections, error) {
	variantsWithoutMandatory := c.calculateNonMandatoryVariants(component.Variants())

	selections := make(puan.Selections, len(variantsWithoutMandatory))
	for i, variant := range variantsWithoutMandatory {
		variantComponent, err := NewPackageVariantComponent(component.Code(), variant)
		if err != nil {
			return nil, err
		}

		selection := c.calculateSelectionForPackageVariant(
			variantComponent,
		)
		selections[i] = selection
	}
	return selections, nil
}

func (c *NextSelectionsCalculator) calculateNonMandatoryVariants(
	variants ManyPackageVariants,
) ManyPackageVariants {
	sharedCodes := variants.sharedCodes()
	variantsWithoutMandatory := variants.withoutCodes(sharedCodes)
	return variantsWithoutMandatory
}

func (c *NextSelectionsCalculator) calculateSelectionForPackageVariant(
	variant PackageVariantComponent,
) puan.Selection {
	action := c.calculateActionForPackageVariantComponent(variant)
	selection := variant.asSelection(action)

	return selection
}

func (c *NextSelectionsCalculator) calculateActionForPackageVariantComponent(
	component PackageVariantComponent,
) puan.Action {
	builder := puan.NewSelectionBuilder(component.Code().String())

	for _, subSelectionCode := range component.Variant().codes() {
		builder.WithSubSelectionID(subSelectionCode.String())
	}

	addSelection := builder.Build()

	hasSelection := selectionsContain(c.currentSelections, addSelection)
	if hasSelection {
		return puan.REMOVE
	}

	return puan.ADD
}

type NextCarKeyCreator struct {
	carRuleset CarRuleset
}

func NewNextCarKeyCreator(
	carRuleset CarRuleset,
) *NextCarKeyCreator {
	return &NextCarKeyCreator{
		carRuleset: carRuleset,
	}
}

func (c *NextCarKeyCreator) New(
	nextSelections puan.Selections,
	envelope puan.SolutionsBySelectionEnvelope,
	fromWeek *specification.StructureWeek,
) ([]CarKeyForSelection, error) {
	if err := c.validateSolutionCount(nextSelections, envelope); err != nil {
		return nil, err
	}

	carKeysBySelection, err := c.newCarKeysBySelection(
		nextSelections,
		envelope,
		fromWeek,
	)
	if err != nil {
		return nil, err
	}

	filterer := newNextCarKeysFilterer(c.carRuleset)
	availableCarKeysBySelection, err := filterer.filterOutUnavailable(carKeysBySelection)
	if err != nil {
		return nil, err
	}

	return availableCarKeysBySelection, nil
}

func (c *NextCarKeyCreator) validateSolutionCount(
	nextSelections puan.Selections,
	envelope puan.SolutionsBySelectionEnvelope,
) error {
	selectionCount := len(nextSelections)
	solutionCount := len(envelope.SolutionsBySelection())
	if selectionCount != solutionCount {
		return errors.Errorf(
			"next selections count %d does not match solution count %d",
			selectionCount,
			solutionCount,
		)
	}

	return nil
}

func (c *NextCarKeyCreator) newCarKeysBySelection(
	selections puan.Selections,
	envelope puan.SolutionsBySelectionEnvelope,
	fromWeek *specification.StructureWeek,
) ([]CarKeyForSelection, error) {
	carKeysBySelection := make([]CarKeyForSelection, len(selections))
	for i, selection := range selections {
		solutionBySelection, err := envelope.GetSolutionBySelection(selection)
		if err != nil {
			return nil, err
		}

		carKeyForSelection, err := c.newCarKeyForSelection(
			solutionBySelection,
			fromWeek,
		)

		if err != nil {
			return nil, err
		}
		carKeysBySelection[i] = carKeyForSelection
	}
	return carKeysBySelection, nil
}

func (c *NextCarKeyCreator) newCarKeyForSelection(
	solutionBySelection puan.SolutionBySelection,
	fromWeek *specification.StructureWeek,
) (CarKeyForSelection, error) {
	carKey, err := NewCarKey(
		c.carRuleset,
		solutionBySelection.Solution(),
		fromWeek,
	)
	if err != nil {
		return CarKeyForSelection{}, err
	}

	carKeyForSelection := NewCarKeyForSelection(
		solutionBySelection.Selection(),
		carKey,
	)
	return carKeyForSelection, nil
}

type NextCarKeysFilterer struct {
	typeLookup map[specification.Code]ComponentType
}

func newNextCarKeysFilterer(
	carRuleset CarRuleset,
) *NextCarKeysFilterer {
	typeLookup := carRuleset.newTypeLookup()
	return &NextCarKeysFilterer{
		typeLookup: typeLookup,
	}
}

func (c *NextCarKeysFilterer) filterOutUnavailable(
	carKeysBySelection []CarKeyForSelection,
) ([]CarKeyForSelection, error) {
	var filtered []CarKeyForSelection
	for _, carKeyBySelection := range carKeysBySelection {
		isAvailable, err := c.isAvailable(carKeyBySelection)
		if err != nil {
			return nil, err
		}

		if isAvailable {
			filtered = append(filtered, carKeyBySelection)
		}
	}

	return filtered, nil
}

func (c *NextCarKeysFilterer) isAvailable(
	carKeyForSelection CarKeyForSelection,
) (bool, error) {
	isRemove := carKeyForSelection.Selection().Action() == puan.REMOVE
	if isRemove {
		return true, nil
	}

	isPackage, err := c.isPackage(carKeyForSelection)
	if err != nil {
		return false, err
	}

	if isPackage {
		return c.isPackageAvailable(carKeyForSelection)
	}
	return c.isComponentAvailable(carKeyForSelection)
}

func (c *NextCarKeysFilterer) isPackage(
	carKeyForSelection CarKeyForSelection,
) (bool, error) {
	primarySelectionCode, err := specification.NewCode(carKeyForSelection.Selection().ID())
	if err != nil {
		return false, err
	}

	typ, err := c.getType(primarySelectionCode)
	if err != nil {
		return false, err
	}

	isPackage := typ == ComponentTypePackage
	return isPackage, nil
}

func (c *NextCarKeysFilterer) isComponentAvailable(
	carKeyForSelection CarKeyForSelection,
) (bool, error) {
	component, err := c.toComponent(carKeyForSelection.Selection().ID())
	if err != nil {
		return false, err
	}

	hasComponent, err := carKeyForSelection.carKey.containsComponent(component)
	if err != nil {
		return false, err
	}

	return hasComponent, nil
}

func (c *NextCarKeysFilterer) toComponent(
	rawCode string,
) (Component, error) {
	code, err := specification.NewCode(rawCode)
	if err != nil {
		return Component{}, err
	}

	typ, err := c.getType(code)
	if err != nil {
		return Component{}, err
	}

	component := NewComponent(code, typ)

	return component, nil
}

func (c *NextCarKeysFilterer) isPackageAvailable(
	carKeyForSelection CarKeyForSelection,
) (bool, error) {
	selection := carKeyForSelection.Selection()

	isVariantSelection := len(selection.SubSelectionIDs()) > 0
	if isVariantSelection {
		return c.isPackageVariantAvailable(carKeyForSelection)
	}

	isPackageAvailable := carKeyForSelection.carKey.containsPackage(
		specification.Code(selection.ID()),
	)
	return isPackageAvailable, nil
}

func (c *NextCarKeysFilterer) isPackageVariantAvailable(
	carKeyForSelection CarKeyForSelection,
) (bool, error) {
	component, err := c.toPackageVariantComponent(carKeyForSelection.Selection())
	if err != nil {
		return false, err
	}

	hasPackageVariant, err := carKeyForSelection.carKey.containsPackageVariant(
		component,
	)
	if err != nil {
		return false, err
	}

	return hasPackageVariant, nil
}

func (c *NextCarKeysFilterer) toPackageVariantComponent(
	selection puan.Selection,
) (PackageVariantComponent, error) {
	var variantComponents PackageVariant
	for _, subSelectionID := range selection.SubSelectionIDs() {
		component, err := c.toComponent(subSelectionID)
		if err != nil {
			return PackageVariantComponent{}, err
		}
		variantComponents = append(variantComponents, component)
	}

	packageCode, err := specification.NewCode(selection.ID())
	if err != nil {
		return PackageVariantComponent{}, err
	}
	packageVariantComponent, err := NewPackageVariantComponent(
		packageCode,
		variantComponents,
	)
	if err != nil {
		return PackageVariantComponent{}, err
	}

	return packageVariantComponent, nil
}

func (c *NextCarKeysFilterer) getType(code specification.Code) (ComponentType, error) {
	typ, found := c.typeLookup[code]
	if !found {
		return "", errors.Errorf(
			"component type not found for code %s",
			code,
		)
	}

	return typ, nil
}

