package ruleset

import (
	"github.com/ourstudio-se/puan-sdk-go/puan"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

// package codes mapped to the package codes it overlaps with.
type packageOverlapsGraph map[specification.Code]specification.CodeLookup

// returns package codes present in the graph as a lookup.
func (o packageOverlapsGraph) nodes() specification.CodeLookup {
	nodes := make(specification.CodeLookup, len(o))
	for code := range o {
		nodes[code] = struct{}{}
	}

	return nodes
}

type packageExclusivityRuleCreator struct {
	creator               *puan.RulesetCreator
	overlapsByPackageCode packageOverlapsGraph
}

func newPackageExclusivityRulesCreator(
	creator *puan.RulesetCreator,
	packages specification.Packages,
) *packageExclusivityRuleCreator {
	overlapsByPackageCode := calculateOverlapsByPackages(packages)
	return &packageExclusivityRuleCreator{
		creator:               creator,
		overlapsByPackageCode: overlapsByPackageCode,
	}
}

func calculateOverlapsByPackages(
	packages specification.Packages,
) packageOverlapsGraph {
	requirementsByPackage := newRequirementsByPackageCode(packages)

	graph := make(packageOverlapsGraph, len(requirementsByPackage))
	for code := range requirementsByPackage {
		overlapping := findOverlappingPackages(code, requirementsByPackage)
		graph[code] = overlapping
	}

	return graph
}

func newRequirementsByPackageCode(
	packages specification.Packages,
) map[specification.Code]specification.CodeLookup {
	contents := make(map[specification.Code]specification.CodeLookup, len(packages))
	for _, pkg := range packages {
		requirementsLookup := pkg.Requirements().Codes().AsLookup()
		contents[pkg.Code()] = requirementsLookup
	}

	return contents
}

func findOverlappingPackages(
	code specification.Code,
	contents map[specification.Code]specification.CodeLookup,
) specification.CodeLookup {
	requirements := contents[code]

	overlapping := make(specification.CodeLookup)
	for otherCode, otherRequirements := range contents {
		if otherCode == code {
			continue
		}

		if requirements.OverlapsWith(otherRequirements) {
			overlapping[otherCode] = struct{}{}
		}
	}

	return overlapping
}

func (c *packageExclusivityRuleCreator) addRules() error {
	overlappingGroups := c.calculateOverlappingGroups()
	return c.newRules(overlappingGroups)
}

func (c *packageExclusivityRuleCreator) calculateOverlappingGroups() []specification.Codes {
	packageCodeLookup := c.overlapsByPackageCode.nodes()
	return c.findMaximalGroups(
		nil,
		packageCodeLookup,
		nil,
	)
}

// [Bron–Kerbosch algorithm](https://rosettacode.org/wiki/Bron%E2%80%93Kerbosch_algorithm)
//
// Recursively finds all maximal "cliques" for an undirected graph.
// A maximal clique is a subset of vertices where every two distinct vertices are adjacent
// (in our case, the packages overlap), and the clique cannot be extended by including any
// adjacent vertex not already in the clique.
//
// nolint:gocyclo
func (c *packageExclusivityRuleCreator) findMaximalGroups(
	group specification.CodeLookup,
	candidates specification.CodeLookup,
	excluded specification.CodeLookup,
) []specification.Codes {
	searchComplete := len(candidates) == 0
	if searchComplete {
		groupFound := len(group) >= 2 && len(excluded) == 0
		if groupFound {
			return []specification.Codes{
				group.AsSlice(),
			}
		}

		return nil
	}

	var groups []specification.Codes
	remaining := candidates
	explored := excluded
	for candidate := range candidates {
		groupsForCandidate := c.findMaximalGroupForCandidate(
			group,
			candidate,
			remaining,
			explored,
		)
		groups = append(groups, groupsForCandidate...)

		remaining = remaining.Without(candidate)
		explored = explored.With(candidate)
	}

	return groups
}

func (c *packageExclusivityRuleCreator) findMaximalGroupForCandidate(
	group specification.CodeLookup,
	candidate specification.Code,
	candidates specification.CodeLookup,
	excluded specification.CodeLookup,
) []specification.Codes {
	groupWithCandidate := group.With(candidate)

	// Only need to care about packages that overlap with the candidate
	overlapsWithCandidate := c.overlapsByPackageCode[candidate]

	toExploreForCandidate := candidates.Intersect(overlapsWithCandidate)
	excludedForCandidate := excluded.Intersect(overlapsWithCandidate)

	return c.findMaximalGroups(
		groupWithCandidate,
		toExploreForCandidate,
		excludedForCandidate,
	)
}

func (c *packageExclusivityRuleCreator) newRules(
	exclusivePackageGroups []specification.Codes,
) error {
	for _, group := range exclusivePackageGroups {
		if err := c.newRule(group); err != nil {
			return err
		}
	}

	return nil
}

func (c *packageExclusivityRuleCreator) newRule(
	exclusivePackageCodes specification.Codes,
) error {
	noOverlap := len(exclusivePackageCodes) < 2
	if noOverlap {
		return nil
	}

	id, err := c.creator.SetOneOrNone(exclusivePackageCodes.Strings()...)
	if err != nil {
		return err
	}

	return c.creator.Assume(id)
}

