package ruleset

import (
	"slices"
	"strings"

	"github.com/go-errors/errors"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type (
	PackageVariant      ManyComponents
	ManyPackageVariants []PackageVariant
)

func NewPackageVariant(
	components ManyComponents,
) (PackageVariant, error) {
	if err := validatePackageVariant(components); err != nil {
		return nil, err
	}

	return PackageVariant(components), nil
}

func validatePackageVariant(
	components ManyComponents,
) error {
	seen := make(map[specification.Code]struct{})
	for _, component := range components {
		code := component.Code()
		if _, exists := seen[code]; exists {
			return errors.Errorf(
				"duplicate component code in package variant: %s",
				code,
			)
		}

		seen[code] = struct{}{}

		if component.Type() == ComponentTypePackage {
			return errors.Errorf(
				"package component type is not allowed in package variant: %s",
				code,
			)
		}
	}

	return nil
}

func (variant PackageVariant) codes() specification.Codes {
	return ManyComponents(variant).Codes()
}

func (variant PackageVariant) dedupe() PackageVariant {
	seen := make(map[specification.Code]struct{})
	var deduped PackageVariant
	for _, component := range variant {
		if _, alreadySeen := seen[component.Code()]; !alreadySeen {
			seen[component.Code()] = struct{}{}
			deduped = append(deduped, component)
		}
	}

	return deduped
}

func (variant PackageVariant) contains(other PackageVariant) bool {
	codeSet := make(map[specification.Code]struct{})
	for _, component := range variant {
		codeSet[component.Code()] = struct{}{}
	}

	for _, component := range other {
		if _, ok := codeSet[component.Code()]; !ok {
			return false
		}
	}

	return true
}

func (variant PackageVariant) asKey() string {
	codes := variant.codes()
	slices.Sort(codes)
	return strings.Join(codes.Strings(), "|")
}

func (variants ManyPackageVariants) contains(other PackageVariant) bool {
	for _, variant := range variants {
		if variant.contains(other) {
			return true
		}
	}

	return false
}

func (variants ManyPackageVariants) hasAnyVariantContainedIn(others ManyPackageVariants) bool {
	for _, variant := range variants {
		if others.contains(variant) {
			return true
		}
	}

	return false
}

func (variants ManyPackageVariants) dedupe() ManyPackageVariants {
	variantSet := make(map[string]PackageVariant)
	for _, variant := range variants {
		variantSet[variant.asKey()] = variant
	}

	var deduped ManyPackageVariants
	for _, variant := range variantSet {
		deduped = append(deduped, variant)
	}

	return deduped
}

func (variants ManyPackageVariants) sharedCodes() specification.Codes {
	occurrences := make(map[specification.Code]int)
	for _, variant := range variants {
		seenInVariant := make(map[specification.Code]struct{})
		for _, component := range variant {
			code := component.Code()
			if _, alreadySeen := seenInVariant[code]; alreadySeen {
				continue
			}

			seenInVariant[code] = struct{}{}
			occurrences[code]++
		}
	}

	var shared specification.Codes
	for code, count := range occurrences {
		if count == len(variants) {
			shared = append(shared, code)
		}
	}

	return shared
}

func (variants ManyPackageVariants) withoutCodes(codes specification.Codes) ManyPackageVariants {
	sharedLookup := make(map[specification.Code]struct{})
	for _, code := range codes {
		sharedLookup[code] = struct{}{}
	}

	filtered := make(ManyPackageVariants, 0, len(variants))
	for _, variant := range variants {
		filteredVariant := make(PackageVariant, 0, len(variant))
		for _, component := range variant {
			if _, found := sharedLookup[component.Code()]; !found {
				filteredVariant = append(filteredVariant, component)
			}
		}
		if len(filteredVariant) > 0 {
			filtered = append(filtered, filteredVariant)
		}
	}

	return filtered
}

type PackageVariantCalculator struct{}

func newPackageVariantCalculator() *PackageVariantCalculator {
	return &PackageVariantCalculator{}
}

func (c *PackageVariantCalculator) newVariantsByPackage(
	packages specification.Packages,
) map[specification.Code]ManyPackageVariants {
	variantsByPackage := make(map[specification.Code]ManyPackageVariants)
	for _, pkg := range packages {
		requirements := c.getXORRequirements(pkg)
		variants := c.calculateVariants(requirements)
		variantsByPackage[pkg.Code()] = variants
	}

	return variantsByPackage
}

func (c *PackageVariantCalculator) calculateVariantsForPackage(
	pkg specification.Package,
) ManyPackageVariants {
	xorRequirements := c.getXORRequirements(pkg)
	variants := c.calculateVariants(xorRequirements)
	return variants
}

func (c *PackageVariantCalculator) getXORRequirements(
	pkg specification.Package,
) []ManyComponents {
	var requirements []ManyComponents

	if requiredColors := pkg.RequiredColors(); requiredColors != nil {
		requirements = append(
			requirements,
			newComponents(requiredColors.Codes(), ComponentTypeColor),
		)
	}

	if requiredUpholsteries := pkg.RequiredUpholsteries(); requiredUpholsteries != nil {
		requirements = append(
			requirements,
			newComponents(requiredUpholsteries.Codes(), ComponentTypeUpholstery),
		)
	}

	if requiredWheels := pkg.RequiredWheels(); requiredWheels != nil {
		requirements = append(
			requirements,
			newComponents(requiredWheels.Codes(), ComponentTypeWheel),
		)
	}

	for _, requiredOption := range pkg.RequiredOptions() {
		requirements = append(
			requirements,
			newComponents(requiredOption.Codes(), ComponentTypeOption),
		)
	}

	return requirements
}

// Generates all possible unique variants
// using depth-first search algorithm (dfs)
// and returns them as a slice of serialized keys.
// nolint:gocyclo
func (c *PackageVariantCalculator) calculateVariants(
	xorRequirements []ManyComponents,
) ManyPackageVariants {
	if len(xorRequirements) == 0 {
		return nil
	}

	combination := make(ManyComponents, len(xorRequirements))
	var variants ManyPackageVariants

	var dfs func(i int, selected map[specification.Code]bool)
	dfs = func(i int, selected map[specification.Code]bool) {
		if i == len(xorRequirements) {
			variant := make(PackageVariant, len(combination))
			copy(variant, combination)
			deduped := variant.dedupe()
			variants = append(variants, deduped)
			return
		}

		previousPossibleChoices := make(map[specification.Code]bool)
		for j := range i {
			for _, component := range xorRequirements[j] {
				previousPossibleChoices[component.Code()] = true
			}
		}

		for _, component := range xorRequirements[i] {
			code := component.Code()
			if isInvalidDueToPreviousOccurrence(code, previousPossibleChoices, selected) {
				continue
			}

			if isConflictWithExistingSelection(code, xorRequirements[i].Codes(), selected) {
				continue
			}

			// isSelectedNow: when we backtrack, we must only undo selections introduced
			// by this level. If an outer recursion level had already selected this code,
			// we must leave it intact — otherwise we’d accidentally erase state that
			// another branch of the search still depends on.
			isSelectedNow := !selected[code]
			selected[code] = true
			combination[i] = component
			dfs(i+1, selected)

			// Only unselect if this recursion level was the one that selected it
			if isSelectedNow {
				selected[code] = false
			}
		}
	}

	dfs(0, make(map[specification.Code]bool))
	return variants
}

// isInvalidDueToPreviousOccurrence
// If the candidate code appeared in a previous ExactlyOne group
// (i.e., it exists in previousPossibleChoices) but was not selected
// (i.e., it is not present in selected), then it is invalid to introduce it now.
//
// Example:
//   - Group 0: {opt1, opt2} → we selected opt2
//   - Group 1: {opt1, opt3} → we must not select opt1 here, because it
//     appeared earlier but was not chosen.
func isInvalidDueToPreviousOccurrence(
	candidate specification.Code,
	previousPossibleChoices map[specification.Code]bool,
	selected map[specification.Code]bool,
) bool {
	isInPrevious := previousPossibleChoices[candidate]
	hasNotBeenSelected := !selected[candidate]
	return isInPrevious && hasNotBeenSelected
}

// isConflictWithExistingSelection
// If any other code in the same ExactlyOne group has already been selected
// (i.e., it exists in the selected map) and it is different from the current
// candidate (v) we are trying to choose, the function returns true.
// This ensures that once a component has been "locked" to a specific code,
// we cannot choose a different code for the same component in a later step.
//
// Example:
//   - Group 0: {opt1, opt2} → we selected opt1
//   - Group 1: {opt1, opt3} → we must not select opt3 here,
//     because the component is already locked to opt1.
func isConflictWithExistingSelection(
	candidate specification.Code,
	group specification.Codes,
	selected map[specification.Code]bool,
) bool {
	for _, code := range group {
		if code != candidate && selected[code] {
			return true
		}
	}

	return false
}

func newPackageVariants(
	pkg specification.Package,
) ManyPackageVariants {
	calculator := newPackageVariantCalculator()
	variants := calculator.calculateVariantsForPackage(pkg)
	return variants
}

