package ruleset

import (
	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type ReversePackageRuleCreator struct {
	*puan.RulesetCreator

	packages          specification.Packages
	variantsByPackage map[specification.Code]ManyPackageVariants
}

func newReversePackageRuleCreator(
	creator *puan.RulesetCreator,
	packages specification.Packages,
) *ReversePackageRuleCreator {
	packageVariantCalculator := newPackageVariantCalculator()
	variantsByPackage := packageVariantCalculator.newVariantsByPackage(packages)

	return &ReversePackageRuleCreator{
		RulesetCreator:    creator,
		packages:          packages,
		variantsByPackage: variantsByPackage,
	}
}

func (c *ReversePackageRuleCreator) addRules() error {
	isolatedPackages, subsetPackages := c.categorizePackages()

	err := c.addIsolatedPackages(isolatedPackages)
	if err != nil {
		return err
	}

	return c.addSubsetPackages(subsetPackages)
}

func (c *ReversePackageRuleCreator) categorizePackages() (
	isolatedPackages specification.Packages,
	subsetPackages specification.Packages,
) {
	for _, pkg := range c.packages {
		if c.isIsolated(pkg) {
			isolatedPackages = append(isolatedPackages, pkg)
		} else {
			subsetPackages = append(subsetPackages, pkg)
		}
	}

	return isolatedPackages, subsetPackages
}

func (c *ReversePackageRuleCreator) isIsolated(pkg specification.Package) bool {
	variants := c.variantsByPackage[pkg.Code()]

	for _, otherPkg := range c.packages {
		if pkg.Code() == otherPkg.Code() {
			continue
		}

		otherVariants := c.variantsByPackage[otherPkg.Code()]

		hasVariant := variants.hasAnyVariantContainedIn(otherVariants)
		if hasVariant {
			return false
		}
	}

	return true
}

func (c *ReversePackageRuleCreator) addIsolatedPackages(
	packages specification.Packages,
) error {
	for _, pkg := range packages {
		err := c.addIsolatedPackage(pkg)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *ReversePackageRuleCreator) addIsolatedPackage(
	pkg specification.Package,
) error {
	requirements := pkg.Requirements()

	requirementConstraintIDs := make([]string, len(requirements))
	for i, requirement := range requirements {
		constraintID, err := setExactlyOne(c.RulesetCreator, requirement.Codes())
		if err != nil {
			return err
		}

		requirementConstraintIDs[i] = constraintID
	}

	return c.assumeInPeriod(requirementConstraintIDs, pkg.Period(), pkg.Code())
}

func (c *ReversePackageRuleCreator) addSubsetPackages(
	packages specification.Packages,
) error {
	variants := c.getVariantsInSubsetPackages(packages.Codes())
	for _, variant := range variants {
		err := c.addSubsetPackagesByVariant(variant)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *ReversePackageRuleCreator) getVariantsInSubsetPackages(
	codes specification.Codes,
) ManyPackageVariants {
	var variants ManyPackageVariants
	for _, code := range codes {
		variantsInPackage := c.variantsByPackage[code]
		variants = append(variants, variantsInPackage...)
	}

	// dedupe the variants to avoid processing the same variant multiple times
	// duplicates could occur if multiple packages share the same variant.
	return variants.dedupe()
}

func (c *ReversePackageRuleCreator) addSubsetPackagesByVariant(variant PackageVariant) error {
	packageCodes := c.findPackageCodesContainingVariant(variant)
	packages := c.findPackagesByCodes(packageCodes...)
	if len(packages) == 0 {
		return errors.Errorf(
			"no packages found containing variant %v",
			variant,
		)
	}

	packagesByPeriod := groupPackagesByConnectedPeriods(packages)

	return c.assumeInPeriods(variant, packagesByPeriod)
}

func (c *ReversePackageRuleCreator) findPackageCodesContainingVariant(
	variant PackageVariant,
) specification.Codes {
	var packagesContainingVariant specification.Codes
	for pkg, otherVariants := range c.variantsByPackage {
		if otherVariants.contains(variant) {
			packagesContainingVariant = append(packagesContainingVariant, pkg)
		}
	}

	return packagesContainingVariant
}

func (c *ReversePackageRuleCreator) findPackagesByCodes(
	codes ...specification.Code,
) specification.Packages {
	packageByCode := make(map[specification.Code]specification.Package)
	for _, pkg := range c.packages {
		packageByCode[pkg.Code()] = pkg
	}

	var packages specification.Packages
	for _, code := range codes {
		if pkg, ok := packageByCode[code]; ok {
			packages = append(packages, pkg)
		}
	}

	return packages
}

func (c *ReversePackageRuleCreator) assumeInPeriods(
	variant PackageVariant,
	packagesByPeriod map[specification.StructureWeekPeriod]specification.Codes,
) error {
	requirementIDs := variant.codes().Strings()
	for period, packageCodes := range packagesByPeriod {
		err := c.assumeInPeriod(requirementIDs, period, packageCodes...)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *ReversePackageRuleCreator) assumeInPeriod(
	requirementIDs []string,
	period specification.StructureWeekPeriod,
	packageCodes ...specification.Code,
) error {
	groupID, err := setAll(c.RulesetCreator, requirementIDs)
	if err != nil {
		return err
	}

	requiredPackageID, err := setAtLeastOne(c.RulesetCreator, packageCodes)
	if err != nil {
		return err
	}

	id, err := c.SetImply(groupID, requiredPackageID)
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.AssumeInPeriod(
		id,
		from,
		to,
	)
}

func setAll(
	creator *puan.RulesetCreator,
	ids []string,
) (string, error) {
	if len(ids) == 0 {
		return "", errors.Errorf(
			"%w: no ids provided",
			domainerror.InvalidOperation,
		)
	}

	if len(ids) == 1 {
		return ids[0], nil
	}

	return creator.SetAnd(ids...)
}

