	periodVariables puan.TimeBoundVariables,
) (specification.ManyStructureWeekPeriods, error) {
	entities := make(specification.ManyStructureWeekPeriods, len(periodVariables))
	var err error
	for i, variable := range periodVariables {
		entities[i], err = toStructureWeekPeriod(variable.Period())
		if err != nil {
			return nil, err
		}
	}

	return entities, nil
}

func toStructureWeekPeriod(period puan.Period) (specification.StructureWeekPeriod, error) {
	from, err := specification.NewStructureWeekFromTimestamp(period.From())
	if err != nil {
		return specification.StructureWeekPeriod{}, err
	}

	// Subtracting a millisecond to ensure that the "to" timestamp falls within the correct week,
	// since the "to" timestamp is exclusive.
	offset := -time.Millisecond
	to, err := specification.NewStructureWeekFromTimestamp(period.To().Add(offset))

	if err != nil {
		return specification.StructureWeekPeriod{}, err
	}

	return specification.NewStructureWeekPeriod(from, to)
}

func (r CarRuleset) newTypeLookup() map[specification.Code]ComponentType {
	lookup := make(map[specification.Code]ComponentType)
	for _, component := range r.components {
		lookup[component.Code()] = component.Type()
	}

	for _, packageComponent := range r.packageComponents {
		lookup[packageComponent.Code()] = ComponentTypePackage
	}

	return lookup
}

func (r CarRuleset) ValidateTimestamps(
	fromWeek *specification.StructureWeek,
	toWeek *specification.StructureWeek,
) error {
	periods, err := r.StructureWeekPeriods()
	if err != nil {
		return err
	}

	return validateTimestamps(
		periods,
		fromWeek,
		toWeek,
	)
}

