ast.text:
package ruleset

import (
	"fmt"

	"github.com/go-errors/errors"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type configurationRulesetCreator struct {
	*puan.RulesetCreator
	period *specification.StructureWeekPeriod
}

func newConfigurationRulesetCreator() configurationRulesetCreator {
	return configurationRulesetCreator{
		RulesetCreator: puan.NewRulesetCreator(),
	}
}

func (c *configurationRulesetCreator) addTime(
	period specification.StructureWeekPeriod,
	forbiddenPeriods specification.ManyStructureWeekPeriods,
) error {
	if err := c.enableTime(period); err != nil {
		return err
	}

	if err := c.addForbiddenPeriods(forbiddenPeriods); err != nil {
		return err
	}

	return nil
}

func (c *configurationRulesetCreator) enableTime(
	period specification.StructureWeekPeriod,
) error {
	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	if err := c.EnableTime(
		from,
		to,
	); err != nil {
		return err
	}

	c.period = &period

	return nil
}

func (c *configurationRulesetCreator) addForbiddenPeriods(
	forbiddenPeriods specification.ManyStructureWeekPeriods,
) error {
	for _, period := range forbiddenPeriods {
		err := c.forbidPeriod(period)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) forbidPeriod(
	period specification.StructureWeekPeriod,
) error {
	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	err = c.ForbidPeriod(from, to)
	if err != nil {
		return err
	}

	return nil
}

func (c *configurationRulesetCreator) addRules(
	carSpecification specification.CarSpecification,
) error {
	err := c.addMessageSpecification(carSpecification.SMessages())
	if err != nil {
		return err
	}

	err = c.addStylingSpecification(carSpecification.Styling())
	if err != nil {
		return err
	}

	packages := carSpecification.Packages().Packages()
	err = c.addOptionSpecification(carSpecification.Options(), packages)
	if err != nil {
		return err
	}

	err = c.addPackageSpecification(carSpecification.Packages())
	if err != nil {
		return err
	}

	return c.addWheelSpecification(carSpecification.Wheels())
}

func (c *configurationRulesetCreator) addMessageSpecification(
	specification specification.SMessageSpecification,
) error {
	return c.addSMessages(specification.SMessages())
}

func (c *configurationRulesetCreator) addSMessages(sMessages specification.SMessages) error {
	err := c.addOneOrNone(sMessages.Codes())
	if err != nil {
		return err
	}

	for _, sMessage := range sMessages {
		err = c.forbidInInactivePeriods(sMessage)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addOneOrNone(codes specification.Codes) error {
	if len(codes) < 2 {
		return nil
	}

	id, err := c.SetOneOrNone(codes.Strings()...)
	if err != nil {
		return err
	}

	return c.Assume(id)
}

func (c *configurationRulesetCreator) addStylingSpecification(
	specification specification.StylingSpecification,
) error {
	err := c.addColors(specification.Colors())
	if err != nil {
		return err
	}

	err = c.addManyDefaultStylings(specification.DefaultColors())
	if err != nil {
		return err
	}

	err = c.addUpholsteries(specification.Upholsteries())
	if err != nil {
		return err
	}

	return c.addManyDefaultStylings(specification.DefaultUpholsteries())
}

func (c *configurationRulesetCreator) addColors(colors specification.Colors) error {
	for _, color := range colors {
		err := c.addColorComponent(color)
		if err != nil {
			return err
		}

		err = c.forbidInInactivePeriods(color)
		if err != nil {
			return err
		}
	}

	return c.assumeExactlyOne(colors.Codes())
}

func (c *configurationRulesetCreator) addColorComponent(color specification.Color) error {
	return c.newComponentConfigurator(color.Code()).
		withRequiredTimeBoundAtLeastOnes(color.RequiredOptions()).
		withRequiredTimeBoundExactlyOnes(color.RequiredWheels()).
		withForbidden(color.ForbidsOptions()).
		withForbidden(color.ForbidsWheels()).
		withForbidden(color.ForbidsUpholsteries()).
		configure()
}

func (c *configurationRulesetCreator) assumeExactlyOne(codes specification.Codes) error {
	id, err := setExactlyOne(c.RulesetCreator, codes)
	if err != nil {
		return err
	}

	return c.Assume(id)
}

func (c *configurationRulesetCreator) addUpholsteries(
	upholsteries specification.Upholsteries,
) error {
	for _, upholstery := range upholsteries {
		err := c.addUpholsteryComponent(upholstery)
		if err != nil {
			return err
		}

		err = c.forbidInInactivePeriods(upholstery)
		if err != nil {
			return err
		}
	}

	return c.assumeExactlyOne(upholsteries.Codes())
}

func (c *configurationRulesetCreator) addUpholsteryComponent(
	upholstery specification.Upholstery,
) error {
	return c.newComponentConfigurator(upholstery.Code()).
		withRequiredTimeBoundAtLeastOnes(upholstery.RequiredOptions()).
		withForbidden(upholstery.ForbidsOptions()).
		withForbidden(upholstery.ForbidsColors()).
		withForbidden(upholstery.ForbidsWheels()).
		configure()
}

func (c *configurationRulesetCreator) addManyDefaultStylings(
	stylings specification.ManyTimeBoundCodes,
) error {
	for _, styling := range stylings {
		err := c.addDefaultStyling(styling)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addDefaultStyling(
	styling specification.TimeBoundCode,
) error {
	from, to, err := styling.Period().Timestamps()
	if err != nil {
		return err
	}

	err = c.PreferInPeriod(styling.Code().String(), from, to)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"failed to prefer default styling code %s",
				styling.Code().String(),
			),
			0,
		)
	}

	return nil
}

func (c *configurationRulesetCreator) addOptionSpecification(
	specification specification.OptionSpecification,
	packages specification.Packages,
) error {
	err := c.addOptions(specification.Options())
	if err != nil {
		return err
	}

	err = c.addManyTimeBoundExactlyOne(specification.IncludedOptions())
	if err != nil {
		return err
	}

	err = c.addPackageOnlyOptions(specification.PackageOnlyOptions(), packages)
	if err != nil {
		return err
	}

	err = c.addCombinedOptionRequirements(specification.CombinedRequirements())
	if err != nil {
		return err
	}

	return nil
}

func (c *configurationRulesetCreator) addOptions(options specification.Options) error {
	for _, option := range options {
		err := c.addOptionComponent(option)
		if err != nil {
			return err
		}

		err = c.forbidInInactivePeriods(option)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addOptionComponent(option specification.Option) error {
	return c.newComponentConfigurator(option.Code()).
		withForbidden(option.ForbidsOptions()).
		withForbidden(option.ForbidsColors()).
		withForbidden(option.ForbidsWheels()).
		withForbidden(option.ForbidsUpholsteries()).
		withRequiredTimeBoundAtLeastOnes(option.RequiredOptions()).
		withRequiredTimeBoundExactlyOnes(option.RequiredColors()).
		withRequiredTimeBoundExactlyOnes(option.RequiredUpholsteries()).
		withRequiredTimeBoundExactlyOnes(option.RequiredWheels()).
		configure()
}

func (c *configurationRulesetCreator) addManyTimeBoundExactlyOne(
	exactlyOnes specification.ManyTimeBoundExactlyOne,
) error {
	for _, exactlyOne := range exactlyOnes {
		err := c.addTimeBoundExactlyOne(exactlyOne)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addTimeBoundExactlyOne(
	exactlyOne specification.TimeBoundExactlyOne,
) error {
	id, err := c.setExactlyOneWithPreferred(exactlyOne)
	if err != nil {
		return err
	}

	from, to, err := exactlyOne.Period().Timestamps()
	if err != nil {
		return err
	}

	return c.AssumeInPeriod(
		id,
		from,
		to,
	)
}

func (c *configurationRulesetCreator) setExactlyOneWithPreferred(
	exactlyOne specification.TimeBoundExactlyOne,
) (string, error) {
	codes := exactlyOne.Codes()
	id, err := setExactlyOne(c.RulesetCreator, codes)
	if err != nil {
		return "", err
	}

	if exactlyOne.HasPreferred() {
		err = c.preferTimeBoundExactlyOne(
			id,
			*exactlyOne.DefaultCode(),
			exactlyOne.Period(),
		)
		if err != nil {
			return "", err
		}
	}

	return id, nil
}

func (c *configurationRulesetCreator) preferTimeBoundExactlyOne(
	exactlyOneID string,
	defaultCode specification.Code,
	period specification.StructureWeekPeriod,
) error {
	id, err := c.SetImply(exactlyOneID, defaultCode.String())
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.PreferInPeriod(id, from, to)
}

func (c *configurationRulesetCreator) addPackageOnlyOptions(
	packageOnlyOptions specification.Codes,
	packages specification.Packages,
) error {
	for _, code := range packageOnlyOptions {
		packagesWithOption := packages.ContainingOption(code)
		if len(packagesWithOption) == 0 {
			return errors.Errorf(
				"%w: could not find packages with code %s",
				domainerror.InvalidOperation,
				code,
			)
		}

		err := c.assumeRequiresAny(code, packagesWithOption.Codes())
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) assumeRequiresAny(
	requiring specification.Code,
	required specification.Codes,
) error {
	requiredID, err := setAtLeastOne(c.RulesetCreator, required)
	if err != nil {
		return err
	}

	id, err := c.SetImply(requiring.String(), requiredID)
	if err != nil {
		return err
	}

	return c.Assume(id)
}

func (c *configurationRulesetCreator) addCombinedOptionRequirements(
	requirements specification.ManyCombinedOptionRequirements,
) error {
	for _, requirement := range requirements {
		requiringID, err := c.SetAnd(requirement.RequiringCodes().Strings()...)
		if err != nil {
			return err
		}

		implyID, err := c.SetImply(requiringID, requirement.RequiredCode().String())
		if err != nil {
			return err
		}

		err = c.Assume(implyID)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addPackageSpecification(
	specification specification.PackageSpecification,
) error {
	err := c.addPackages(
		specification.Packages(),
	)
	if err != nil {
		return err
	}

	return c.addManyTimeBoundExactlyOne(specification.IncludedPackages())
}

func (c *configurationRulesetCreator) addPackages(
	packages specification.Packages,
) error {
	for _, pkg := range packages {
		err := c.addPackage(pkg)
		if err != nil {
			return err
		}

		err = c.forbidInInactivePeriods(pkg)
		if err != nil {
			return err
		}
	}

	reverseRuleCreator := newReversePackageRuleCreator(
		c.RulesetCreator,
		packages,
	)
	if err := reverseRuleCreator.addRules(); err != nil {
		return err
	}

	exclusiveRulesCreator := newPackageExclusivityRulesCreator(
		c.RulesetCreator,
		packages,
	)
	if err := exclusiveRulesCreator.addRules(); err != nil {
		return err
	}

	return nil
}

func (c *configurationRulesetCreator) addPackage(pkg specification.Package) error {
	for _, required := range pkg.Requirements() {
		err := c.addPackageRequirement(pkg.Code(), required)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) addPackageRequirement(
	pkg specification.Code,
	required specification.ExactlyOne,
) error {
	exactlyOneID, err := setExactlyOne(c.RulesetCreator, required.Codes())
	if err != nil {
		return err
	}

	if required.HasPreferred() {
		preferredID, err := c.SetImply(pkg.String(), required.DefaultCode().String())
		if err != nil {
			return err
		}

		err = c.Prefer(preferredID)
		if err != nil {
			return err
		}
	}

	id, err := c.SetImply(pkg.String(), exactlyOneID)
	if err != nil {
		return err
	}

	return c.Assume(id)
}

func (c *configurationRulesetCreator) addWheelSpecification(
	specification specification.WheelSpecification,
) error {
	err := c.addWheels(specification.Wheels())
	if err != nil {
		return err
	}

	return c.addStandardWheels(specification.StandardWheel())
}

func (c *configurationRulesetCreator) addWheels(wheels specification.Wheels) error {
	for _, wheel := range wheels {
		err := c.addWheelComponent(wheel)
		if err != nil {
			return err
		}

		err = c.forbidInInactivePeriods(wheel)
		if err != nil {
			return err
		}
	}

	return c.assumeExactlyOne(wheels.Codes())
}

func (c *configurationRulesetCreator) addWheelComponent(wheel specification.Wheel) error {
	return c.newComponentConfigurator(wheel.Code()).
		withRequiredTimeBoundExactlyOnes(wheel.RequiredColors()).
		withRequiredTimeBoundAtLeastOnes(wheel.RequiredOptions()).
		withRequiredTimeBoundExactlyOnes(wheel.RequiredUpholsteries()).
		withForbidden(wheel.ForbidsOptions()).
		withForbidden(wheel.ForbidsUpholsteries()).
		configure()
}

func (c *configurationRulesetCreator) addStandardWheels(
	standardWheel *specification.Code,
) error {
	if standardWheel == nil {
		return nil
	}

	return c.Prefer(standardWheel.String())
}

type timeBoundComponent interface {
	Code() specification.Code
	Period() specification.StructureWeekPeriod
}

func (c *configurationRulesetCreator) forbidInInactivePeriods(component timeBoundComponent) error {
	forbiddenPeriods, err := c.period.Difference(component.Period())
	if err != nil {
		return err
	}

	return c.forbidInPeriods(forbiddenPeriods, component.Code())
}

func (c *configurationRulesetCreator) forbidInPeriods(
	periods specification.ManyStructureWeekPeriods,
	codes ...specification.Code,
) error {
	for _, period := range periods {
		err := c.forbidInPeriod(period, codes)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *configurationRulesetCreator) forbidInPeriod(
	period specification.StructureWeekPeriod,
	codes specification.Codes,
) error {
	id, err := c.SetNot(codes.Strings()...)
	if err != nil {
		return err
	}

	from, to, err := period.Timestamps()
	if err != nil {
		return err
	}

	return c.AssumeInPeriod(
		id,
		from,
		to,
	)
}

func setAtLeastOne(
	creator *puan.RulesetCreator,
	codes specification.Codes,
) (string, error) {
	if len(codes) == 0 {
		return "", errors.Errorf(
			"%w: no codes provided",
			domainerror.InvalidOperation,
		)
	}

	if len(codes) == 1 {
		return codes[0].String(), nil
	}

	return creator.SetOr(codes.Strings()...)
}

func setExactlyOne(
	creator *puan.RulesetCreator,
	codes specification.Codes,
) (string, error) {
	if len(codes) == 0 {
		return "", errors.Errorf(
			"%w: no codes provided",
			domainerror.InvalidOperation,
		)
	}

	if len(codes) == 1 {
		return codes[0].String(), nil
	}

	return creator.SetXor(codes.Strings()...)
}

