package ruleset

import (
	"context"
	"fmt"

	"github.com/ourstudio-se/puan-sdk-go/puan"
	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
)

type SelectionValidator struct {
	logger *loggingsdk.Logger
}

func NewSelectionValidator(logger *loggingsdk.Logger) *SelectionValidator {
	return &SelectionValidator{
		logger: logger,
	}
}

func (v *SelectionValidator) FilterOutInvalid(
	ctx context.Context,
	selections puan.Selections,
	selectableIDs []string,
) (validSelections puan.Selections) {
	validSelections, invalidSelectionIDs := splitBySelectability(
		selections,
		selectableIDs,
	)

	if len(invalidSelectionIDs) > 0 {
		v.logger.Warnf(
			ctx,
			fmt.Sprintf(
				"invalid selections: %v are not selectable",
				invalidSelectionIDs,
			),
		)
	}

	return validSelections
}
func (v *SelectionValidator) FilterOutInvalidInGroups(
	ctx context.Context,
	selectionGroups []puan.Selections,
	selectableIDs []string,
) []puan.Selections {
	filteredGroups := make([]puan.Selections, len(selectionGroups))
	for i, selections := range selectionGroups {
		filteredGroup := v.FilterOutInvalid(
			ctx,
			selections,
			selectableIDs,
		)
		filteredGroups[i] = filteredGroup
	}
	return filteredGroups
}

func splitBySelectability(
	selections puan.Selections,
	selectableIDs []string,
) (
	validSelections puan.Selections,
	invalidSelectionIDs []string,
) {
	selectableSet := make(map[string]struct{}, len(selectableIDs))
	for _, id := range selectableIDs {
		selectableSet[id] = struct{}{}
	}

	for _, selected := range selections {
		valid := true
		for _, id := range selected.IDs() {
			if _, ok := selectableSet[id]; !ok {
				valid = false
				invalidSelectionIDs = append(invalidSelectionIDs, id)
			}
		}

		if valid {
			validSelections = append(validSelections, selected)
		}
	}

	return validSelections, invalidSelectionIDs
}

func selectionsContain(
	selections puan.Selections,
	toCheck puan.Selection,
) bool {
	for _, selection := range selections {
		if selection.Equals(toCheck) {
			return true
		}
	}
	return false
}

