package specification

import (
	"fmt"

	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type carSpecificationValidator struct {
	period           StructureWeekPeriod
	forbiddenPeriods ManyStructureWeekPeriods
	periods          ManyStructureWeekPeriods
	periodByCode     map[Code]StructureWeekPeriod
	sMessages        SMessageSpecification
	styling          StylingSpecification
	options          OptionSpecification
	packages         PackageSpecification
	wheels           WheelSpecification
}

func newCarSpecificationValidator(
	specification CarSpecification,
) (*carSpecificationValidator, error) {
	periods, err := specification.period.differenceToMany(specification.forbiddenPeriods)
	if err != nil {
		return nil, err
	}

	periodByCode := specification.periodsLookup()
	return &carSpecificationValidator{
		period:           specification.period,
		forbiddenPeriods: specification.forbiddenPeriods,
		periods:          periods,
		periodByCode:     periodByCode,
		sMessages:        specification.sMessages,
		styling:          specification.styling,
		options:          specification.options,
		packages:         specification.packages,
		wheels:           specification.wheels,
	}, nil
}

func (c *carSpecificationValidator) validate() error {
	err := c.validateForbiddenPeriods()
	if err != nil {
		return err
	}

	err = c.validateSMessageSpecification()
	if err != nil {
		return err
	}

	err = c.validateStylingSpecification()
	if err != nil {
		return err
	}

	err = c.validateOptionSpecification()
	if err != nil {
		return err
	}

	err = c.validatePackageSpecification()
	if err != nil {
		return err
	}

	return c.validateWheelSpecification()
}

func (c *carSpecificationValidator) validateForbiddenPeriods() error {
	if !c.period.containsAll(c.forbiddenPeriods) {
		return errors.Errorf(
			"%w: forbidden periods are outside the specification period",
			domainerror.InvalidOperation,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateSMessageSpecification() error {
	if err := c.validatePeriodsWithinSpecificationPeriod(c.sMessages.periods()); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid sMessages",
			0,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateStylingSpecification() error {
	if err := c.validatePeriodsWithinSpecificationPeriod(c.styling.periods()); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid styling",
			0,
		)
	}

	err := c.validateManyColors()
	if err != nil {
		return err
	}

	return c.validateManyUpholsteries()
}

func (c *carSpecificationValidator) validateManyColors() error {
	periods := c.styling.colors.periods()
	if err := c.validateFullPeriodCoverage(periods); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid colors",
			0,
		)
	}

	for _, color := range c.styling.colors {
		err := c.validateColorRelations(color)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateColorRelations(color Color) error {
	err := c.validateManyAtLeastOneRelations(color.requiredOptions)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"color %s has invalid required options",
				color.code,
			),
			0,
		)
	}

	err = c.validateManyExactlyOneRelations(color.requiredWheels)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"color %s has invalid required wheels",
				color.code,
			),
			0,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateManyUpholsteries() error {
	periods := c.styling.upholsteries.periods()
	if err := c.validateFullPeriodCoverage(periods); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid upholsteries",
			0,
		)
	}

	for _, upholstery := range c.styling.upholsteries {
		err := c.validateUpholsteryRelations(upholstery)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateUpholsteryRelations(upholstery Upholstery) error {
	err := c.validateManyAtLeastOneRelations(upholstery.requiredOptions)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"upholstery %s has invalid required options",
				upholstery.code,
			),
			0,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateOptionSpecification() error {
	if err := c.validatePeriodsWithinSpecificationPeriod(c.options.periods()); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid options",
			0,
		)
	}

	err := c.validatePackageOnlyOptions()
	if err != nil {
		return err
	}

	err = c.validateManyOptionRelations()
	if err != nil {
		return err
	}

	err = c.validateManyCombinedOptionRequirements(c.options.combinedRequirements)
	if err != nil {
		return err
	}

	return nil
}

func (c *carSpecificationValidator) validatePackageOnlyOptions() error {
	optionsInPackages := c.packages.packages.optionsCodeMap()
	for _, code := range c.options.packageOnlyOptions {
		if _, ok := optionsInPackages[code]; !ok {
			return errors.Errorf(
				"%w: package only option code %s does not exist in package options",
				domainerror.InvalidOperation,
				code,
			)
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateManyOptionRelations() error {
	for _, option := range c.options.options {
		err := c.validateOptionRelations(option)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateOptionRelations(option Option) error {
	err := c.validateManyExactlyOneRelations(option.requiredColors)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"option %s has invalid required colors",
				option.code,
			),
			0,
		)
	}

	err = c.validateManyExactlyOneRelations(option.requiredUpholsteries)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"option %s has invalid required upholsteries",
				option.code,
			),
			0,
		)
	}

	err = c.validateManyAtLeastOneRelations(option.requiredOptions)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"option %s has invalid required options",
				option.code,
			),
			0,
		)
	}

	err = c.validateManyExactlyOneRelations(option.requiredWheels)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"option %s has invalid required wheels",
				option.code,
			),
			0,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validatePackageSpecification() error {
	if err := c.validatePeriodsWithinSpecificationPeriod(c.packages.periods()); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid packages",
			0,
		)
	}

	return c.validateManyPackageRelations()
}

func (c *carSpecificationValidator) validateManyPackageRelations() error {
	for _, pkg := range c.packages.packages {
		err := c.validatePackageRelations(pkg)
		if err != nil {
			return err
		}
	}

	return nil
}

// nolint:gocyclo
func (c *carSpecificationValidator) validatePackageRelations(pkg Package) error {
	if pkg.requiredColors != nil {
		colors := *pkg.requiredColors
		err := c.validateRequireRelations(
			pkg.period,
			colors.codes,
		)
		if err != nil {
			return errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"package code %s has invalid required colors",
					pkg.code,
				),
				0,
			)
		}
	}

	if pkg.requiredUpholsteries != nil {
		upholsteries := *pkg.requiredUpholsteries
		err := c.validateRequireRelations(
			pkg.period,
			upholsteries.codes,
		)
		if err != nil {
			return errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"package code %s has invalid required upholsteries",
					pkg.code,
				),
				0,
			)
		}
	}

	if pkg.requiredWheels != nil {
		wheels := *pkg.requiredWheels
		err := c.validateRequireRelations(
			pkg.period,
			wheels.codes,
		)
		if err != nil {
			return errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"package code %s has invalid required wheels",
					pkg.code,
				),
				0,
			)
		}
	}

	return c.validatePackageOptions(
		pkg.code,
		pkg.period,
		pkg.requiredOptions,
	)
}

func (c *carSpecificationValidator) validatePackageOptions(
	code Code,
	period StructureWeekPeriod,
	requiredOptions ManyExactlyOne,
) error {
	for _, option := range requiredOptions {
		err := c.validateRequireRelations(period, option.codes)
		if err != nil {
			return errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"package code %s has invalid option codes %v",
					code,
					option.codes,
				),
				0,
			)
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateWheelSpecification() error {
	periods := c.wheels.periods()
	if err := c.validatePeriodsWithinSpecificationPeriod(periods); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid wheels",
			0,
		)
	}

	if err := c.validateFullPeriodCoverage(periods); err != nil {
		return errors.WrapPrefix(
			err,
			"Invalid wheels",
			0,
		)
	}

	return c.validateManyWheelRelations()
}

func (c *carSpecificationValidator) validatePeriodsWithinSpecificationPeriod(
	periods ManyStructureWeekPeriods,
) error {
	allWithin := c.period.containsAll(periods)

	if !allWithin {
		return errors.Errorf(
			"%w: periods %v are outside specification's period %v",
			domainerror.InvalidOperation,
			periods,
			c.period,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateFullPeriodCoverage(
	periods ManyStructureWeekPeriods,
) error {
	for _, carPeriod := range c.periods {
		remaining, err := carPeriod.differenceToMany(periods)
		if err != nil {
			return err
		}
		if len(remaining) > 0 {
			return errors.Errorf(
				"%w: no component available for period %v",
				domainerror.InvalidOperation,
				remaining,
			)
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateManyWheelRelations() error {
	for _, wheel := range c.wheels.wheels {
		err := c.validateWheelRelations(wheel)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateWheelRelations(wheel Wheel) error {
	err := c.validateManyAtLeastOneRelations(wheel.requiredOptions)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"wheel %s has invalid required options",
				wheel.code,
			),
			0,
		)
	}

	err = c.validateManyExactlyOneRelations(wheel.requiredColors)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"wheel %s has invalid required colors",
				wheel.code,
			),
			0,
		)
	}

	err = c.validateManyExactlyOneRelations(wheel.requiredUpholsteries)
	if err != nil {
		return errors.WrapPrefix(
			err,
			fmt.Sprintf(
				"wheel %s has invalid required upholsteries",
				wheel.code,
			),
			0,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateManyExactlyOneRelations(
	exactlyOnes ManyTimeBoundExactlyOne,
) error {
	for _, exactlyOne := range exactlyOnes {
		err := c.validateRequireRelations(
			exactlyOne.period,
			exactlyOne.codes,
		)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateManyAtLeastOneRelations(
	atLeastOnes ManyTimeBoundAtLeastOne,
) error {
	for _, atLeastOne := range atLeastOnes {
		err := c.validateRequireRelations(
			atLeastOne.period,
			atLeastOne.codes,
		)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateRequireRelations(
	requiringPeriod StructureWeekPeriod,
	requiredCodes Codes,
) error {
	for _, code := range requiredCodes {
		err := c.validateRequireRelation(requiringPeriod, code)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateRequireRelation(
	requiringPeriod StructureWeekPeriod,
	requiredCode Code,
) error {
	availablePeriod, ok := c.periodByCode[requiredCode]
	if !ok {
		return errors.Errorf(
			"%w: required code %s does not exist",
			domainerror.InvalidOperation,
			requiredCode,
		)
	}

	if !availablePeriod.contains(requiringPeriod) {
		return errors.Errorf(
			"%w: available period %v for required code %s does not contain requiring period %v",
			domainerror.InvalidOperation,
			availablePeriod,
			requiredCode,
			requiringPeriod,
		)
	}

	return nil
}

func (c *carSpecificationValidator) validateManyCombinedOptionRequirements(
	requirements ManyCombinedOptionRequirements,
) error {
	for _, requirement := range requirements {
		if err := c.validateCombinedOptionRequirement(requirement); err != nil {
			return errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"combined option requirement %v is invalid",
					requirement,
				),
				0,
			)
		}
	}

	return nil
}

func (c *carSpecificationValidator) validateCombinedOptionRequirement(
	requirement CombinedOptionRequirement,
) error {
	requiringPeriod, err := c.calculateIntersectionOfPeriods(requirement.RequiringCodes())
	if err != nil {
		return err
	}

	requiredCode := requirement.RequiredCode()
	if err := c.validateRequireRelation(requiringPeriod, requiredCode); err != nil {
		return err
	}

	return nil
}

func (c *carSpecificationValidator) calculateIntersectionOfPeriods(
	codes Codes,
) (StructureWeekPeriod, error) {
	periods := make(ManyStructureWeekPeriods, len(codes))
	for i, code := range codes {
		availablePeriod, ok := c.periodByCode[code]
		if !ok {
			return StructureWeekPeriod{}, errors.Errorf(
				"%w: code %s does not exist",
				domainerror.InvalidOperation,
				code,
			)
		}
		periods[i] = availablePeriod
	}

	intersection, err := periods.Intersection()
	if err != nil {
		return StructureWeekPeriod{},
			errors.WrapPrefix(
				err,
				fmt.Sprintf(
					"codes %v periods does not intersect",
					codes,
				),
				0,
			)
	}

	return intersection, nil
}

