func (cleaner *CarSpecificationCleaner) removeRedundantForbidsInColors(
	ctx context.Context,
) error {
	colors := cleaner.spec.styling.colors

	for i, color := range colors {
		cleanedForbidsOptions, err := cleaner.filterOutRedundantForbids(
			ctx,
			color.code,
			color.forbidsOptions,
		)
		if err != nil {
			return err
		}

		colors[i].forbidsOptions = cleanedForbidsOptions

		cleanedForbidsUpholsteries, err := cleaner.filterOutRedundantForbids(
			ctx,
			color.code,
			color.forbidsUpholsteries,
		)
		if err != nil {
