package specification

import (
	"context"

	"github.com/go-errors/errors"
	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
)

type CarSpecificationCleaner struct {
	spec          *CarSpecification
	periodsByCode map[Code]StructureWeekPeriod

	logger *loggingsdk.Logger
}

func NewCarSpecificationCleaner(
	spec *CarSpecification,
	logger *loggingsdk.Logger,
) *CarSpecificationCleaner {
	periodsByCode := spec.periodsLookup()
	return &CarSpecificationCleaner{
		spec:          spec,
		periodsByCode: periodsByCode,
		logger:        logger,
	}
}

// Remove redundant forbid rules, which can't have an effect.
// The reason is that that the period of the forbidee, forbidden
// or the rule itself don't overlap.
func (cleaner *CarSpecificationCleaner) RemoveRedundantForbids(
	ctx context.Context,
) error {
	if err := cleaner.removeRedundantForbidsInColors(ctx); err != nil {
		return err
	}
	if err := cleaner.removeRedundantForbidsInUpholsteries(ctx); err != nil {
		return err
	}
	if err := cleaner.removeRedundantForbidsInOptions(ctx); err != nil {
		return err
	}
	if err := cleaner.removeRedundantForbidsInWheels(ctx); err != nil {
		return err
	}

	return nil
}

func (cleaner *CarSpecificationCleaner) removeRedundantForbidsInColors(
	ctx context.Context,
) error {
	colors := cleaner.spec.styling.colors

	for i, color := range colors {
		cleanedForbidsOptions, err := cleaner.filterOutRedundantForbids(
			ctx,
			color.code,
			color.forbidsOptions,
		)
		if err != nil {
			return err
		}

		colors[i].forbidsOptions = cleanedForbidsOptions

		cleanedForbidsUpholsteries, err := cleaner.filterOutRedundantForbids(
			ctx,
			color.code,
			color.forbidsUpholsteries,
		)
		if err != nil {
			return err
		}

		colors[i].forbidsUpholsteries = cleanedForbidsUpholsteries

		cleanedForbidsWheels, err := cleaner.filterOutRedundantForbids(
			ctx,
			color.code,
			color.forbidsWheels,
		)
		if err != nil {
			return err
		}

		colors[i].forbidsWheels = cleanedForbidsWheels
	}

	return nil
}

func (cleaner *CarSpecificationCleaner) removeRedundantForbidsInUpholsteries(
	ctx context.Context,
) error {
	upholsteries := cleaner.spec.styling.upholsteries

	for i, upholstery := range upholsteries {
		cleanedForbidsOptions, err := cleaner.filterOutRedundantForbids(
			ctx,
			upholstery.code,
			upholstery.forbidsOptions,
		)
		if err != nil {
			return err
		}

		upholsteries[i].forbidsOptions = cleanedForbidsOptions

		cleanedForbidsColors, err := cleaner.filterOutRedundantForbids(
			ctx,
			upholstery.code,
			upholstery.forbidsColors,
		)
		if err != nil {
			return err
		}

		upholsteries[i].forbidsColors = cleanedForbidsColors

		cleanedForbidsWheels, err := cleaner.filterOutRedundantForbids(
			ctx,
			upholstery.code,
			upholstery.forbidsWheels,
		)
		if err != nil {
			return err
		}

		upholsteries[i].forbidsWheels = cleanedForbidsWheels
	}

	return nil
}

func (cleaner *CarSpecificationCleaner) removeRedundantForbidsInOptions(
	ctx context.Context,
) error {
	options := cleaner.spec.options.options

	for i, option := range options {
		cleanedForbidsOptions, err := cleaner.filterOutRedundantForbids(
			ctx,
			option.code,
			option.forbidsOptions,
		)
		if err != nil {
			return err
		}

		options[i].forbidsOptions = cleanedForbidsOptions

		cleanedForbidsColors, err := cleaner.filterOutRedundantForbids(
			ctx,
			option.code,
			option.forbidsColors,
		)
		if err != nil {
			return err
		}

		options[i].forbidsColors = cleanedForbidsColors

		cleanedForbidsWheels, err := cleaner.filterOutRedundantForbids(
			ctx,
			option.code,
			option.forbidsWheels,
		)
		if err != nil {
			return err
		}

		options[i].forbidsWheels = cleanedForbidsWheels

		cleanedForbidsUpholsteries, err := cleaner.filterOutRedundantForbids(
			ctx,
			option.code,
			option.forbidsUpholsteries,
		)
		if err != nil {
			return err
		}

		options[i].forbidsUpholsteries = cleanedForbidsUpholsteries
	}

	return nil
}

func (cleaner *CarSpecificationCleaner) removeRedundantForbidsInWheels(
	ctx context.Context,
) error {
	wheels := cleaner.spec.wheels.wheels

	for i, wheel := range wheels {
		cleanedForbidsOptions, err := cleaner.filterOutRedundantForbids(
			ctx,
			wheel.code,
			wheel.forbidsOptions,
		)
		if err != nil {
			return err
		}

		wheels[i].forbidsOptions = cleanedForbidsOptions

		cleanedForbidsUpholsteries, err := cleaner.filterOutRedundantForbids(
			ctx,
			wheel.code,
			wheel.forbidsUpholsteries,
		)
		if err != nil {
			return err
		}

		wheels[i].forbidsUpholsteries = cleanedForbidsUpholsteries
	}

	return nil
}

func (cleaner *CarSpecificationCleaner) filterOutRedundantForbids(
	ctx context.Context,
	forbideeCode Code,
	rules ManyForbids,
) (ManyForbids, error) {
	var cleaned ManyForbids

	for _, rule := range rules {
		isRedundant, err := cleaner.isRedundantForbids(forbideeCode, rule)
		if err != nil {
			return nil, err
		}

		if isRedundant {
			cleaner.logger.Warnf(
				ctx,
				"Filtering out redundant forbids %v for forbidee %s",
				rule,
				forbideeCode,
			)
			continue
		}

		cleaned = append(cleaned, rule)
	}

	return cleaned, nil
}

func (cleaner *CarSpecificationCleaner) isRedundantForbids(
	forbideeCode Code,
	rule Forbids,
) (bool, error) {
	forbideePeriod, ok := cleaner.periodsByCode[forbideeCode]
	if !ok {
		return false, errors.Errorf("No period found for forbidee code %s", forbideeCode)
	}
	forbiddenPeriod, ok := cleaner.periodsByCode[rule.code]
	if !ok {
		return false, errors.Errorf("No period found for forbidden code %s", rule.code)
	}

	noOverlapBetweenForbideeAndRule := !forbideePeriod.overlaps(rule.period)
	if noOverlapBetweenForbideeAndRule {
		return true, nil
	}

	noOverlapBetweenForbiddenAndRule := !forbiddenPeriod.overlaps(rule.period)
	if noOverlapBetweenForbiddenAndRule {
		return true, nil
	}

	noOverlapBetweenForbideeAndForbidden := !forbideePeriod.overlaps(forbiddenPeriod)
	if noOverlapBetweenForbideeAndForbidden {
		return true, nil
	}

	return false, nil
}

