package specification

import (
	"slices"

	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type Code string

func (c Code) String() string {
	return string(c)
}

func NewCode(code string) (Code, error) {
	if code == "" {
		return Code(""), errors.Errorf(
			"%w: code %s is empty",
			domainerror.InvalidOperation,
			code,
		)
	}
	return Code(code), nil
}

type Codes []Code

func NewCodes(rawCodes []string) (Codes, error) {
	codes := make(Codes, len(rawCodes))
	for i, code := range rawCodes {
		c, err := NewCode(code)
		if err != nil {
			return nil, err
		}
		codes[i] = c
	}

	return codes, nil
}

func (c Codes) Strings() []string {
	codes := make([]string, len(c))
	for i, code := range c {
		codes[i] = code.String()
	}

	return codes
}

func (c Codes) Dedupe() Codes {
	codeMap := make(map[Code]bool)
	for _, code := range c {
		codeMap[code] = true
	}

	var deduped Codes
	for code := range codeMap {
		deduped = append(deduped, code)
	}

	return deduped
}

func (c Codes) Without(code Code) (Codes, error) {
	var codes Codes
	for _, c := range c {
		if c != code {
			codes = append(codes, c)
		}
	}

	if len(codes) == len(c) {
		return nil, errors.Errorf(
			"%w: code %s not found in codes %v",
			domainerror.InvalidOperation,
			code,
			c,
		)
	}

	return codes, nil
}

func (c Codes) contains(code Code) bool {
	return slices.Contains(c, code)
}

func (c Codes) AsLookup() CodeLookup {
	lookup := make(CodeLookup)
	for _, code := range c {
		lookup[code] = struct{}{}
	}

	return lookup
}

func UnionOfCodes(codesGroups ...Codes) Codes {
	codeMap := make(map[Code]bool)
	for _, codes := range codesGroups {
		for _, code := range codes {
			codeMap[code] = true
		}
	}

	var union Codes
	for code := range codeMap {
		union = append(union, code)
	}

	return union
}

type ManyTimeBoundCodes []TimeBoundCode

func (m ManyTimeBoundCodes) periods() ManyStructureWeekPeriods {
	periods := make(ManyStructureWeekPeriods, len(m))
	for i, timeBoundCode := range m {
		periods[i] = timeBoundCode.Period()
	}

	return periods
}

type TimeBoundCode struct {
	code   Code
	period StructureWeekPeriod
}

func NewTimeBoundCode(code Code, period StructureWeekPeriod) TimeBoundCode {
	return TimeBoundCode{
		code:   code,
		period: period,
	}
}

func (t TimeBoundCode) Code() Code {
	return t.code
}

func (t TimeBoundCode) Period() StructureWeekPeriod {
	return t.period
}

type CodeLookup map[Code]struct{}

func (c CodeLookup) OverlapsWith(other CodeLookup) bool {
	for code := range c {
		if other.contains(code) {
			return true
		}
	}

	return false
}

func (c CodeLookup) contains(code Code) bool {
	_, found := c[code]
	return found
}

func (p CodeLookup) Intersect(
	other CodeLookup,
) CodeLookup {
	intersection := make(CodeLookup)
	for code := range p {
		if _, found := other[code]; found {
			intersection[code] = struct{}{}
		}
	}

	return intersection
}

func (p CodeLookup) With(
	added Code,
) CodeLookup {
	extended := make(CodeLookup)
	for code := range p {
		extended[code] = struct{}{}
	}
	extended[added] = struct{}{}

	return extended
}

func (p CodeLookup) Without(
	removed Code,
) CodeLookup {
	remaining := make(CodeLookup)
	for code := range p {
		if code != removed {
			remaining[code] = struct{}{}
		}
	}

	return remaining
}

func (p CodeLookup) AsSlice() Codes {
	var slice Codes
	for code := range p {
		slice = append(slice, code)
	}

	return slice
}

