package specification

import (
	"slices"

	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type TimeBoundExactlyOne struct {
	codes       Codes
	defaultCode *Code
	period      StructureWeekPeriod
}

func NewTimeBoundExactlyOne(
	codes Codes,
	defaultCode *Code,
	period StructureWeekPeriod,
) (TimeBoundExactlyOne, error) {
	if len(codes) == 0 {
		return TimeBoundExactlyOne{}, errors.Errorf(
			"%w: no codes provided",
			domainerror.InvalidOperation,
		)
	}
	if defaultCode != nil {
		if !slices.Contains(codes, *defaultCode) {
			return TimeBoundExactlyOne{}, errors.Errorf(
				"%w: default code %s is not in codes %v",
				domainerror.InvalidOperation,
				defaultCode,
				codes,
			)
		}
	}

	return TimeBoundExactlyOne{
		codes:       codes,
		defaultCode: defaultCode,
		period:      period,
	}, nil
}

func (e TimeBoundExactlyOne) HasPreferred() bool {
	return len(e.codes) > 1 && e.defaultCode != nil
}

func (e TimeBoundExactlyOne) Codes() Codes {
	return e.codes
}

func (e TimeBoundExactlyOne) DefaultCode() *Code {
	return e.defaultCode
}

func (e TimeBoundExactlyOne) Period() StructureWeekPeriod {
	return e.period
}

type ManyTimeBoundExactlyOne []TimeBoundExactlyOne

func (m ManyTimeBoundExactlyOne) codes() Codes {
	codesGroups := make([]Codes, len(m))
	for i, exactlyOne := range m {
		codesGroups[i] = exactlyOne.Codes()
	}

	return UnionOfCodes(codesGroups...)
}

func (m ManyTimeBoundExactlyOne) periods() ManyStructureWeekPeriods {
	periods := make(ManyStructureWeekPeriods, len(m))
	for i, exactlyOne := range m {
		periods[i] = exactlyOne.Period()
	}

	return periods
}

func (m ManyTimeBoundExactlyOne) areValidInPeriod(period StructureWeekPeriod) bool {
	// TODO: Implement period validation.
	return true
}

type ManyExactlyOne []ExactlyOne

func (m ManyExactlyOne) Codes() Codes {
	codesGroups := make([]Codes, len(m))
	for i, permanentExactlyOne := range m {
		codesGroups[i] = permanentExactlyOne.Codes()
	}

	return UnionOfCodes(codesGroups...)
}

type ExactlyOne struct {
	codes       Codes
	defaultCode *Code
}

func NewExactlyOne(
	codes Codes,
	defaultCode *Code,
) (ExactlyOne, error) {
	if len(codes) == 0 {
		return ExactlyOne{}, errors.Errorf(
			"%w: no codes provided",
			domainerror.InvalidOperation,
		)
	}
	if defaultCode != nil {
		if !slices.Contains(codes, *defaultCode) {
			return ExactlyOne{}, errors.Errorf(
				"%w: default code %s is not in codes %v",
				domainerror.InvalidOperation,
				defaultCode,
				codes,
			)
		}
	}
	return ExactlyOne{
		codes:       codes,
		defaultCode: defaultCode,
	}, nil
}

func (e ExactlyOne) HasPreferred() bool {
	return len(e.codes) > 1 && e.defaultCode != nil
}

func (e ExactlyOne) Codes() Codes {
	return e.codes
}

func (e ExactlyOne) DefaultCode() *Code {
	return e.defaultCode
}

