						code:   styling.colors[0].code,
						period: period,
					},
				},
			},
			{
				code:   optionCode2,
				period: period,
			},
			{
				code:   optionCode3,
				period: period,
			},
		},
		combinedRequirements: ManyCombinedOptionRequirements{
			{
				requiringCodes: Codes{
					optionCode1,
					optionCode2,
				},
				requiredCode: optionCode3,
			},
		},
	}

	packageCode := fake.New[Code]()
	packages := PackageSpecification{
		packages: Packages{
			{
				code:   packageCode,
				period: period,
				requiredColors: &ExactlyOne{
					codes: Codes{
						styling.colors[0].code,
					},
				},
				requiredUpholsteries: &ExactlyOne{
					codes: Codes{
						styling.upholsteries[0].code,
					},
				},
			},
		},
	}

	wheels := newFakeWheels(period)
	details := newFakeCarDetails()

	return CarSpecification{
		details:   details,
		period:    period,
		sMessages: sMessage,
		styling:   styling,
		options:   options,
		packages:  packages,
		wheels:    wheels,
	}
}

