ast.text:
package specification

import (
	"github.com/volvo-cars/caas-car-configurator/internal/fake"
)

type fakeCarSpecificationBuilder struct {
	details          CarDetails
	period           StructureWeekPeriod
	forbiddenPeriods ManyStructureWeekPeriods

	sMessages SMessages

	colors              Colors
	upholsteries        Upholsteries
	defaultColors       ManyTimeBoundCodes
	defaultUpholsteries ManyTimeBoundCodes

	options                    Options
	includedOptions            ManyTimeBoundExactlyOne
	includedPackages           ManyTimeBoundExactlyOne
	packageOnlyOptionCodes     Codes
	combinedOptionRequirements ManyCombinedOptionRequirements

	packages Packages

	wheels        Wheels
	standardWheel *Code
}

func NewFakeCarSpecificationBuilder() *fakeCarSpecificationBuilder {
	return &fakeCarSpecificationBuilder{
		details: newFakeCarDetails(),
		period:  NewFakePeriod(),
	}
}

func (b *fakeCarSpecificationBuilder) Details(details CarDetails) *fakeCarSpecificationBuilder {
	b.details = details
	return b
}

func (b *fakeCarSpecificationBuilder) Period() *fakePeriodBuilder[*fakeCarSpecificationBuilder] {
	return &fakePeriodBuilder[*fakeCarSpecificationBuilder]{
		apply: func(period StructureWeekPeriod) *fakeCarSpecificationBuilder {
			b.period = period
			return b
		},
		from: b.period.from,
		to:   b.period.to,
	}
}

func (
	b *fakeCarSpecificationBuilder,
) ForbidPeriod() *fakePeriodBuilder[*fakeCarSpecificationBuilder] {
	return &fakePeriodBuilder[*fakeCarSpecificationBuilder]{
		apply: func(period StructureWeekPeriod) *fakeCarSpecificationBuilder {
			b.forbiddenPeriods = append(b.forbiddenPeriods, period)
			return b
		},
	}
}

func (b *fakeCarSpecificationBuilder) FakeStyling() *fakeCarSpecificationBuilder {
	styling := newFakeStyling(b.period)

	b.colors = styling.colors
	b.upholsteries = styling.upholsteries

	return b
}

func (b *fakeCarSpecificationBuilder) FakeWheels() *fakeCarSpecificationBuilder {
	wheels := newFakeWheels(b.period)

	b.wheels = wheels.wheels
	b.standardWheel = wheels.standardWheel

	return b
}

func (b *fakeCarSpecificationBuilder) Color() *fakeColorSpecBuilder {
	return &fakeColorSpecBuilder{
		specBuilder: b,
		code:        fake.New[Code](),
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) Upholstery() *fakeUpholsterySpecBuilder {
	return &fakeUpholsterySpecBuilder{
		specBuilder: b,
		code:        fake.New[Code](),
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) DefaultColor(
	color string,
) *fakeDefaultColorSpecBuilder {
	code := Code(color)
	return &fakeDefaultColorSpecBuilder{
		specBuilder: b,
		color:       code,
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) DefaultUpholstery(
	upholstery string,
) *fakeDefaultUpholsterySpecBuilder {
	code := Code(upholstery)
	return &fakeDefaultUpholsterySpecBuilder{
		specBuilder: b,
		upholstery:  code,
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) Option() *fakeOptionSpecBuilder {
	return &fakeOptionSpecBuilder{
		specBuilder: b,
		code:        fake.New[Code](),
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) IncludedOptions(
	rawCodes ...string,
) *fakeTimeBoundExactlyOneBuilder[*fakeCarSpecificationBuilder] {
	codes, err := NewCodes(rawCodes)
	if err != nil {
		panic(err)
	}

	return &fakeTimeBoundExactlyOneBuilder[*fakeCarSpecificationBuilder]{
		codes:       codes,
		defaultCode: nil,
		period:      b.period,
		apply: func(rule TimeBoundExactlyOne) *fakeCarSpecificationBuilder {
			b.includedOptions = append(b.includedOptions, rule)
			return b
		},
	}
}

func (b *fakeCarSpecificationBuilder) IncludedPackages(
	rawCodes ...string,
) *fakeTimeBoundExactlyOneBuilder[*fakeCarSpecificationBuilder] {
	codes, err := NewCodes(rawCodes)
	if err != nil {
		panic(err)
	}

	return &fakeTimeBoundExactlyOneBuilder[*fakeCarSpecificationBuilder]{
		codes:       codes,
		defaultCode: nil,
		period:      b.period,
		apply: func(rule TimeBoundExactlyOne) *fakeCarSpecificationBuilder {
			b.includedPackages = append(b.includedPackages, rule)
			return b
		},
	}
}

func (b *fakeCarSpecificationBuilder) PackageOnlyOptionCodes(
	rawCodes ...string,
) *fakeCarSpecificationBuilder {
	codes, err := NewCodes(rawCodes)
	if err != nil {
		panic(err)
	}

	b.packageOnlyOptionCodes = codes
	return b
}

func (b *fakeCarSpecificationBuilder) CombinedOptionRequirement(
	requiringCodes ...string,
) *fakeCombinedOptionsBuilder {
	requiring := make(Codes, len(requiringCodes))
	for i, code := range requiringCodes {
		requiring[i] = Code(code)
	}

	return &fakeCombinedOptionsBuilder{
		requiringCodes: requiring,
		apply: func(rule CombinedOptionRequirement) *fakeCarSpecificationBuilder {
			b.combinedOptionRequirements = append(b.combinedOptionRequirements, rule)
			return b
		},
	}
}

func (b *fakeCarSpecificationBuilder) Wheel() *fakeWheelSpecBuilder {
	return &fakeWheelSpecBuilder{
		specBuilder: b,
		code:        fake.New[Code](),
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) StandardWheel(
	code string,
) *fakeCarSpecificationBuilder {
	standardWheel := Code(code)
	b.standardWheel = &standardWheel
	return b
}

func (b *fakeCarSpecificationBuilder) Package() *fakePackageSpecBuilder {
	return &fakePackageSpecBuilder{
		specBuilder: b,
		code:        fake.New[Code](),
		period:      b.period,
	}
}

func (b *fakeCarSpecificationBuilder) Build() (CarSpecification, error) {
	sMessageSpec := NewSMessageSpecification(
		b.sMessages,
	)

	stylingSpec, err := NewStylingSpecification(
		b.colors,
		b.upholsteries,
		b.defaultColors,
		b.defaultUpholsteries,
	)
	if err != nil {
		return CarSpecification{}, err
	}

	optionSpec, err := NewOptionSpecification(
		b.options,
		b.packageOnlyOptionCodes,
		b.includedOptions,
		b.combinedOptionRequirements,
	)
	if err != nil {
		return CarSpecification{}, err
	}

	packageSpec, err := NewPackageSpecification(
		b.packages,
		b.includedPackages,
	)
	if err != nil {
		return CarSpecification{}, err
	}

	wheelSpec, err := NewWheelSpecification(
		b.wheels,
		b.standardWheel,
	)
	if err != nil {
		return CarSpecification{}, err
	}

	return NewCarSpecification(
		b.details,
		b.period,
		b.forbiddenPeriods,
		sMessageSpec,
		stylingSpec,
		optionSpec,
		packageSpec,
		wheelSpec,
	)
}

