func NewOptionSpecification(
	options Options,
	packageOnlyOptions Codes,
	includedOptions ManyTimeBoundExactlyOne,
	combinedRequirements ManyCombinedOptionRequirements,
) (OptionSpecification, error) {
	optionCodes := options.codeMap()
	if err := validateOptionCodes(packageOnlyOptions, optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid package only options", 0)
	}

	if err := validateOptionCodes(includedOptions.codes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid included options", 0)
	}

	if err := validateOptionCodes(options.forbiddenOptionCodes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid forbidden options", 0)
	}

	if err := validateOptionCodes(combinedRequirements.codes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid combined requirements", 0)
	}

	return OptionSpecification{
		options:              options,
		packageOnlyOptions:   packageOnlyOptions,
		includedOptions:      includedOptions,
		combinedRequirements: combinedRequirements,
	}, nil
}

