package specification

import (
	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type OptionSpecification struct {
	options              Options
	packageOnlyOptions   Codes
	includedOptions      ManyTimeBoundExactlyOne
	combinedRequirements ManyCombinedOptionRequirements
}

func NewOptionSpecification(
	options Options,
	packageOnlyOptions Codes,
	includedOptions ManyTimeBoundExactlyOne,
	combinedRequirements ManyCombinedOptionRequirements,
) (OptionSpecification, error) {
	optionCodes := options.codeMap()
	if err := validateOptionCodes(packageOnlyOptions, optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid package only options", 0)
	}

	if err := validateOptionCodes(includedOptions.codes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid included options", 0)
	}

	if err := validateOptionCodes(options.forbiddenOptionCodes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid forbidden options", 0)
	}

	if err := validateOptionCodes(combinedRequirements.codes(), optionCodes); err != nil {
		return OptionSpecification{},
			errors.WrapPrefix(err, "invalid combined requirements", 0)
	}

	return OptionSpecification{
		options:              options,
		packageOnlyOptions:   packageOnlyOptions,
		includedOptions:      includedOptions,
		combinedRequirements: combinedRequirements,
	}, nil
}

func validateOptionCodes(
	codes Codes,
	options map[Code]bool,
) error {
	for _, code := range codes {
		if _, ok := options[code]; !ok {
			return errors.Errorf(
				"%w: option %s is not in options %v",
				domainerror.InvalidOperation,
				code,
				options,
			)
		}
	}

	return nil
}

func (o OptionSpecification) Options() Options {
	return o.options
}

func (o OptionSpecification) PackageOnlyOptions() Codes {
	return o.packageOnlyOptions
}

func (o OptionSpecification) IncludedOptions() ManyTimeBoundExactlyOne {
	return o.includedOptions
}

func (o OptionSpecification) CombinedRequirements() []CombinedOptionRequirement {
	return o.combinedRequirements
}

func (o OptionSpecification) periods() ManyStructureWeekPeriods {
	options := o.options.periods()
	includedOptions := o.includedOptions.periods()

	return append(options, includedOptions...)
}

type Options []Option

func (o Options) periods() ManyStructureWeekPeriods {
	periods := make(ManyStructureWeekPeriods, len(o))
	for i, option := range o {
		periods[i] = option.period
	}

	return periods
}

func (o Options) codeMap() map[Code]bool {
	options := make(map[Code]bool, len(o))
	for _, option := range o {
		options[option.code] = true
	}
	return options
}

func (o Options) forbiddenOptionCodes() Codes {
	codesGroups := make([]Codes, len(o))
	for i, option := range o {
		codesGroups[i] = option.forbidsOptions.Codes()
	}

	return UnionOfCodes(codesGroups...)
}

func (o Options) Codes() Codes {
	codes := make(Codes, len(o))
	for i, option := range o {
		codes[i] = option.code
	}

	return codes
}

type Option struct {
	code                 Code
	requiredColors       ManyTimeBoundExactlyOne
	requiredUpholsteries ManyTimeBoundExactlyOne
	requiredOptions      ManyTimeBoundAtLeastOne
	requiredWheels       ManyTimeBoundExactlyOne
	forbidsOptions       ManyForbids
	forbidsColors        ManyForbids
	forbidsWheels        ManyForbids
	forbidsUpholsteries  ManyForbids
	period               StructureWeekPeriod
}

func NewOption(
	code Code,
	requiredColors ManyTimeBoundExactlyOne,
	requiredUpholsteries ManyTimeBoundExactlyOne,
	requiredOptions ManyTimeBoundAtLeastOne,
	requiredWheels ManyTimeBoundExactlyOne,
	forbidsOptions ManyForbids,
	forbidsColors ManyForbids,
	forbidsWheels ManyForbids,
	forbidsUpholsteries ManyForbids,
	period StructureWeekPeriod,
) (Option, error) {
	if !requiredColors.areValidInPeriod(period) {
		return Option{}, errors.Errorf(
			"%w: option %s has requierd colors outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	if !requiredUpholsteries.areValidInPeriod(period) {
		return Option{}, errors.Errorf(
			"%w: option %s has requierd upholsteries outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	if !requiredOptions.areValidInPeriod(period) {
		return Option{}, errors.Errorf(
			"%w: option %s has required options outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	if !requiredWheels.areValidInPeriod(period) {
		return Option{}, errors.Errorf(
			"%w: option %s has required wheels outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	return Option{
		code:                 code,
		requiredColors:       requiredColors,
		requiredUpholsteries: requiredUpholsteries,
		requiredOptions:      requiredOptions,
		requiredWheels:       requiredWheels,
		forbidsOptions:       forbidsOptions,
		forbidsColors:        forbidsColors,
		forbidsWheels:        forbidsWheels,
		forbidsUpholsteries:  forbidsUpholsteries,
		period:               period,
	}, nil
}

func (o Option) Code() Code {
	return o.code
}

func (o Option) RequiredColors() ManyTimeBoundExactlyOne {
	return o.requiredColors
}

func (o Option) RequiredUpholsteries() ManyTimeBoundExactlyOne {
	return o.requiredUpholsteries
}

func (o Option) RequiredOptions() ManyTimeBoundAtLeastOne {
	return o.requiredOptions
}

func (o Option) RequiredWheels() ManyTimeBoundExactlyOne {
	return o.requiredWheels
}

func (o Option) ForbidsOptions() ManyForbids {
	return o.forbidsOptions
}

func (o Option) ForbidsColors() ManyForbids {
	return o.forbidsColors
}

func (o Option) ForbidsWheels() ManyForbids {
	return o.forbidsWheels
}

func (o Option) ForbidsUpholsteries() ManyForbids {
	return o.forbidsUpholsteries
}

