type CombinedOptionRequirement struct {
	requiringCodes Codes
	requiredCode   Code
}

func NewCombinedOptionRequirement(
	requiring Codes,
	required Code,
) (CombinedOptionRequirement, error) {
	if len(requiring) < 2 {
		return CombinedOptionRequirement{},
			errors.Errorf(
				"%w: must have at least 2 requiring codes. Got %d",
				domainerror.InvalidOperation,
				len(requiring),
			)
	}

	if requiring.contains(required) {
		return CombinedOptionRequirement{},
			errors.Errorf(
				"%w: cannot have the same code as requiring and required. Got %v and %q",
				domainerror.InvalidOperation,
				requiring,
				required,
			)
	}

	return CombinedOptionRequirement{
		requiringCodes: requiring,
		requiredCode:   required,
	}, nil
}

func (r CombinedOptionRequirement) RequiringCodes() Codes {
	return r.requiringCodes
}

func (r CombinedOptionRequirement) RequiredCode() Code {
	return r.requiredCode
}

type ManyCombinedOptionRequirements []CombinedOptionRequirement

func (requirements ManyCombinedOptionRequirements) codes() Codes {
	var codes Codes
	for _, requirement := range requirements {
		codes = append(codes, requirement.RequiringCodes()...)
		codes = append(codes, requirement.RequiredCode())
	}

	dedupedCodes := codes.Dedupe()
	return dedupedCodes
}

