package specification

import (
	"slices"

	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type PackageSpecification struct {
	packages         Packages
	includedPackages ManyTimeBoundExactlyOne
}

func (p PackageSpecification) Packages() Packages {
	return p.packages
}

func (p PackageSpecification) IncludedPackages() ManyTimeBoundExactlyOne {
	return p.includedPackages
}

func (p PackageSpecification) periods() ManyStructureWeekPeriods {
	return p.packages.Periods()
}

func NewPackageSpecification(
	packages Packages,
	includedPackages ManyTimeBoundExactlyOne,
) (PackageSpecification, error) {
	if err := validateIncludedPackages(includedPackages, packages); err != nil {
		return PackageSpecification{}, err
	}

	return PackageSpecification{
		packages:         packages,
		includedPackages: includedPackages,
	}, nil
}

func validateIncludedPackages(
	includedPackages ManyTimeBoundExactlyOne,
	packages Packages,
) error {
	includedPackageCodes := includedPackages.codes()
	packageCodes := packages.codeMap()
	for _, code := range includedPackageCodes {
		if _, ok := packageCodes[code]; !ok {
			return errors.Errorf(
				"%w: included package %s is not in packages %v",
				domainerror.InvalidOperation,
				code,
				packages,
			)
		}
	}
	return nil
}

type Packages []Package

func (p Packages) Periods() ManyStructureWeekPeriods {
	periodsMap := make(map[StructureWeekPeriod]bool)
	for _, pkg := range p {
		periodsMap[pkg.period] = true
	}

	var periods ManyStructureWeekPeriods
	for period := range periodsMap {
		periods = append(periods, period)
	}

	return periods
}

func (p Packages) codeMap() map[Code]bool {
	packages := make(map[Code]bool, len(p))
	for _, pkg := range p {
		packages[pkg.code] = true
	}

	return packages
}

func (p Packages) optionsCodeMap() map[Code]bool {
	options := make(map[Code]bool, len(p))
	for _, pkg := range p {
		for _, option := range pkg.requiredOptions {
			for _, code := range option.Codes() {
				options[code] = true
			}
		}
	}

	return options
}

func (p Packages) ContainingOption(code Code) Packages {
	var packagesWithOption Packages
	for _, pkg := range p {
		optionCodes := pkg.requiredOptions.Codes()
		if slices.Contains(optionCodes, code) {
			packagesWithOption = append(packagesWithOption, pkg)
		}
	}
	return packagesWithOption
}

func (p Packages) Codes() Codes {
	var codes Codes
	for _, pkg := range p {
		codes = append(codes, pkg.code)
	}
	return codes
}

func (p Packages) GroupCodesByPeriod() map[StructureWeekPeriod]Codes {
	codesByPeriod := make(map[StructureWeekPeriod]Codes)
	for _, pkg := range p {
		period := pkg.period
		codesByPeriod[period] = append(
			codesByPeriod[period],
			pkg.code,
		)
	}

	return codesByPeriod
}

type Package struct {
	code                 Code
	requiredColors       *ExactlyOne
	requiredUpholsteries *ExactlyOne
	requiredWheels       *ExactlyOne
	requiredOptions      ManyExactlyOne
	period               StructureWeekPeriod
}

func NewPackage(
	code Code,
	requiredColors *ExactlyOne,
	requiredUpholsteries *ExactlyOne,
	requiredWheels *ExactlyOne,
	requiredOptions ManyExactlyOne,
	period StructureWeekPeriod,
) Package {
	return Package{
		code:                 code,
		requiredColors:       requiredColors,
		requiredUpholsteries: requiredUpholsteries,
		requiredWheels:       requiredWheels,
		requiredOptions:      requiredOptions,
		period:               period,
	}
}

func (p Package) Code() Code {
	return p.code
}

func (p Package) RequiredColors() *ExactlyOne {
	return p.requiredColors
}

func (p Package) RequiredUpholsteries() *ExactlyOne {
	return p.requiredUpholsteries
}

func (p Package) RequiredWheels() *ExactlyOne {
	return p.requiredWheels
}

func (p Package) RequiredOptions() ManyExactlyOne {
	return p.requiredOptions
}

func (p Package) Period() StructureWeekPeriod {
	return p.period
}

func (p Package) Requirements() ManyExactlyOne {
	var requirements ManyExactlyOne

	if p.requiredColors != nil {
		requirements = append(requirements, *p.requiredColors)
	}

	if p.requiredUpholsteries != nil {
		requirements = append(requirements, *p.requiredUpholsteries)
	}

	if p.requiredWheels != nil {
		requirements = append(requirements, *p.requiredWheels)
	}

	requirements = append(requirements, p.requiredOptions...)

	return requirements
}

