package specification

import (
	"sort"
	"time"

	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type StructureWeek struct {
	year int
	week int
}

func (s StructureWeek) Year() int {
	return s.year
}

func (s StructureWeek) Week() int {
	return s.week
}

// EarliestFrom is inclusive. It returns a timestamp of the first day of the week.
func (s StructureWeek) EarliestFrom() time.Time {
	if s.week == 1 {
		januaryFirst := time.Date(s.year, time.January, 1, 0, 0, 0, 0, time.UTC)
		return januaryFirst
	}

	// January 4th is always in week 1
	januaryFourth := time.Date(s.year, time.January, 4, 0, 0, 0, 0, time.UTC)
	week := januaryFourth.AddDate(0, 0, (s.week-1)*7)

	// Go: Sunday = 0, Monday = 1, ..., Saturday = 6
	daysToSubtract := int(week.Weekday()+6) % 7

	return week.AddDate(0, 0, -daysToSubtract)
}

// LatestTo is exclusive. It returns a timestamp of the first day of the week after its week.
func (s StructureWeek) LatestTo() (time.Time, error) {
	nextWeek, err := s.nextWeek()
	if err != nil {
		return time.Time{}, err
	}

	timestamp := nextWeek.EarliestFrom()

	return timestamp, nil
}

func (s StructureWeek) previousWeek() (StructureWeek, error) {
	previous := s.week - 1
	year := s.year

	if previous < 1 {
		year -= 1
		previous = weeksInYear(year)
	}

	week, err := NewStructureWeek(year, previous)
	if err != nil {
		return StructureWeek{}, errors.Errorf(
			"failed to get previous week for %v with error: %s",
			s,
			err.Error(),
		)
	}

	return week, nil
}

func (s StructureWeek) nextWeek() (StructureWeek, error) {
	next := s.week + 1
	year := s.year

	if next > weeksInYear(year) {
		year += 1
		next = 1
	}

	week, err := NewStructureWeek(year, next)
	if err != nil {
		return StructureWeek{}, errors.Errorf(
			"failed to get next week for %v with error: %s",
			s,
			err.Error(),
		)
	}

	return week, nil
}

func (week StructureWeek) IsWithin(period StructureWeekPeriod) bool {
	if week.IsBefore(period.From()) {
		return false
	}

	if week.IsAfter(period.To()) {
		return false
	}

	return true
}

func NewStructureWeekFromTimestamp(t time.Time) (StructureWeek, error) {
	year, week := calculateYearAndWeekFromTimestamp(t)
	return NewStructureWeek(year, week)
}

func calculateYearAndWeekFromTimestamp(t time.Time) (int, int) {
	year := t.Year()
	_, week := t.ISOWeek()

	// Adjust for the edge case where January overlaps with the last week of the previous year.
	// Example: 2021-01-01 is in week 53 and is shared with 2020.
	// so ISOWeek returns week 53, (year 2020) for 2021-01-01.
	if t.Month() == time.January && week > 51 {
		week = 1
	}

	// Adjust for the edge case where December overlaps to week 1.
	// Example: 2019-12-31 is in week 1 and is shared with 2020.
	// so ISOWeek returns week 1, (year 2020) for 2019-12-31.
	if t.Month() == time.December && week == 1 {
		week = weeksInYear(year)
	}

	return year, week
}

func NewStructureWeek(year, week int) (StructureWeek, error) {
	if year < 2000 || year > 9999 {
		return StructureWeek{},
			errors.Errorf(
				"%w year %d is not in valid range %d-%d",
				domainerror.InvalidOperation,
				year,
				2000,
				9999,
			)
	}

	if invalidWeek(year, week) {
		return StructureWeek{},
			errors.Errorf(
				"%w week %d is not valid in year %d",
				domainerror.InvalidOperation,
				week,
				year,
			)
	}

	return StructureWeek{
		year: year,
		week: week,
	}, nil
}

func invalidWeek(year int, week int) bool {
	return week < 1 || week > weeksInYear(year)
}

func weeksInYear(year int) int {
	// december 28th is always in the last week of the year
	december28 := time.Date(year, time.December, 28, 0, 0, 0, 0, time.UTC)
	_, week := december28.ISOWeek()
	return week
}

type ManyStructureWeekPeriods []StructureWeekPeriod

// Sorted returns a new slice of periods ordered by earliest "from" first.
// If two periods have equal "from", the one with the earlier "to" comes first.
func (s ManyStructureWeekPeriods) Sorted() ManyStructureWeekPeriods {
	sorted := make(ManyStructureWeekPeriods, len(s))
	copy(sorted, s)

	sort.Slice(sorted, func(i, j int) bool {
		periodI := sorted[i]
		periodJ := sorted[j]
		return periodI.isBefore(periodJ)
	})

	return sorted
}

func (s ManyStructureWeekPeriods) hasOverlap() bool {
	sorted := s.Sorted()
	for i := 0; i < len(sorted)-1; i++ {
		current := sorted[i]
		next := sorted[i+1]
		if current.overlaps(next) {
			return true
		}
	}

	return false
}

// nolint:gocyclo
func (periods ManyStructureWeekPeriods) Intersection() (StructureWeekPeriod, error) {
	if len(periods) == 0 {
		return StructureWeekPeriod{}, errors.Errorf(
			"%w: cannot calculate intersection of empty periods",
			domainerror.InvalidOperation,
		)
	}

	latestFrom := periods[0].From()
	earliestTo := periods[0].To()

	remainingPeriods := periods[1:]
	for _, period := range remainingPeriods {
		if period.From().IsAfter(latestFrom) {
			latestFrom = period.From()
		}

		if period.To().IsBefore(earliestTo) {
			earliestTo = period.To()
		}
	}

	intersectionFound := latestFrom.IsBefore(earliestTo) || latestFrom == earliestTo
	if intersectionFound {
		return StructureWeekPeriod{
			from: latestFrom,
			to:   earliestTo,
		}, nil
	}

	return StructureWeekPeriod{}, errors.Errorf(
		"%w: no intersection between periods %v",
		domainerror.InvalidOperation,
		periods,
	)
}

func (s ManyStructureWeekPeriods) latestTo() (StructureWeek, error) {
	if len(s) == 0 {
		return StructureWeek{}, errors.New(
			"cannot get latest to of empty periods",
		)
	}

	latestTo := s[0].To()
	for _, period := range s[1:] {
		if period.To().IsAfter(latestTo) {
			latestTo = period.To()
		}
	}

	return latestTo, nil
}

func (s ManyStructureWeekPeriods) earliestFrom() (StructureWeek, error) {
	if len(s) == 0 {
		return StructureWeek{}, errors.New(
			"cannot get earliest from of empty periods",
		)
	}

	earliestFrom := s[0].From()
	for _, period := range s[1:] {
		if period.From().IsBefore(earliestFrom) {
			earliestFrom = period.From()
		}
	}

	return earliestFrom, nil
}

func (s ManyStructureWeekPeriods) OverlapsAny(periodToCheck StructureWeekPeriod) bool {
	for _, period := range s {
		overlaps := period.overlaps(periodToCheck)
		if overlaps {
			return true
		}
	}

	return false
}

func (s ManyStructureWeekPeriods) IsAfter(week StructureWeek) (bool, error) {
	latestTo, err := s.latestTo()
	if err != nil {
		return false, err
	}

	return week.IsAfter(latestTo), nil
}

func (s ManyStructureWeekPeriods) IsBefore(week StructureWeek) (bool, error) {
	earliestFrom, err := s.earliestFrom()
	if err != nil {
		return false, err
	}

	return week.IsBefore(earliestFrom), nil
}

type StructureWeekPeriod struct {
	from StructureWeek
	to   StructureWeek
}

func NewStructureWeekPeriod(from, to StructureWeek) (StructureWeekPeriod, error) {
	if from.year > to.year || (from.year == to.year && from.week > to.week) {
		return StructureWeekPeriod{},
			errors.Errorf(
				"%w: from %d-%d is after to %d-%d",
				domainerror.InvalidOperation,
				from.year,
				from.week,
				to.year,
				to.week,
			)
	}

	return StructureWeekPeriod{
		from: from,
		to:   to,
	}, nil
}

// isBefore returns true if the receiver period is before the other period.
// If the "from" weeks are equal, the "to" weeks are compared such that the period
// that ends earlier is considered before.
func (p StructureWeekPeriod) isBefore(other StructureWeekPeriod) bool {
	if p.From().IsBefore(other.From()) {
		return true
	}

	if other.From().IsBefore(p.From()) {
		return false
	}

	return p.To().IsBefore(other.To())
}

func (p StructureWeekPeriod) From() StructureWeek {
	return p.from
}

func (p StructureWeekPeriod) To() StructureWeek {
	return p.to
}

func (p StructureWeekPeriod) Timestamps() (
	from time.Time,
	to time.Time,
	err error,
) {
	from = p.From().EarliestFrom()
	to, err = p.To().LatestTo()
	if err != nil {
		return time.Time{}, time.Time{}, err
	}

	return from, to, nil
}

// Difference returns the parts of this period that are not covered by the other period.
func (p StructureWeekPeriod) Difference(
	other StructureWeekPeriod,
) (ManyStructureWeekPeriods, error) {
	var parts ManyStructureWeekPeriods
	if p.from.IsBefore(other.from) {
		// Subtract one week from the "from" of the other period to avoid overlap.
		// Example: If s is 2021-W01 to 2021-W10 and other is 2021-W05 to 2021-W10.
		// The difference should be 2021-W01 to 2021-W04.
		previousWeek, err := other.from.previousWeek()
		if err != nil {
			return nil, err
		}
		parts = append(parts, StructureWeekPeriod{from: p.from, to: previousWeek})
	}

	if p.to.IsAfter(other.to) {
		// Add one week to the "to" of the other period to avoid overlap.
		// Example: If s is 2021-W01 to 2021-W10 and other is 2021-W01 to 2021-W05.
		// The difference should be 2021-W06 to 2021-W10.
		nextWeek, err := other.to.nextWeek()
		if err != nil {
			return nil, err
		}
		parts = append(parts, StructureWeekPeriod{from: nextWeek, to: p.to})
	}

	return parts, nil
}

func (p StructureWeekPeriod) differenceToMany(
	others ManyStructureWeekPeriods,
) (ManyStructureWeekPeriods, error) {
	remaining := ManyStructureWeekPeriods{p}

	for _, other := range others {
		var next ManyStructureWeekPeriods
		for _, period := range remaining {
			noOverlap := !period.overlaps(other)
			if noOverlap {
				next = append(next, period)
				continue
			}

			parts, err := period.Difference(other)
			if err != nil {
				return nil, err
			}
			next = append(next, parts...)
		}
		remaining = next
	}

	return remaining, nil
}

func (p StructureWeekPeriod) containsAll(others ManyStructureWeekPeriods) bool {
	for _, other := range others {
		if !p.contains(other) {
			return false
		}
	}

	return true
}

// contains checks if the other period is fully contained within this period,
// including the boundaries.
func (p StructureWeekPeriod) contains(other StructureWeekPeriod) bool {
	if other.from.IsBefore(p.from) {
		return false
	}

	if other.to.IsAfter(p.to) {
		return false
	}

	return true
}

func (p StructureWeekPeriod) overlaps(other StructureWeekPeriod) bool {
	if p.from.IsAfter(other.to) {
		return false
	}

	if other.from.IsAfter(p.to) {
		return false
	}

	return true
}

// ConnectsTo returns true if two StructureWeekPeriods share any weeks,
// including boundaries.
func (p StructureWeekPeriod) ConnectsTo(other StructureWeekPeriod) bool {
	return p.from.isBeforeOrEqual(other.to) && other.from.isBeforeOrEqual(p.to)
}

// Join returns a new StructureWeekPeriod that covers both periods.
func (p StructureWeekPeriod) Join(other StructureWeekPeriod) StructureWeekPeriod {
	from := p.from
	if other.from.IsBefore(from) {
		from = other.from
	}

	to := p.to
	if other.to.IsAfter(to) {
		to = other.to
	}

	return StructureWeekPeriod{
		from: from,
		to:   to,
	}
}

func (s StructureWeek) IsBefore(other StructureWeek) bool {
	if s.year < other.year {
		return true
	}

	if s.year == other.year && s.week < other.week {
		return true
	}

	return false
}

func (s StructureWeek) IsAfter(other StructureWeek) bool {
	if s.year > other.year {
		return true
	}

	if s.year == other.year && s.week > other.week {
		return true
	}

	return false
}

// isBeforeOrEqual returns true if the receiver represents a week that comes before
// or is equal to the other week.
func (s StructureWeek) isBeforeOrEqual(other StructureWeek) bool {
	if s.year < other.year {
		return true
	}

	if s.year == other.year && s.week <= other.week {
		return true
	}

	return false
}

