package specification

import (
	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type StylingSpecification struct {
	colors              Colors
	upholsteries        Upholsteries
	defaultColors       ManyTimeBoundCodes
	defaultUpholsteries ManyTimeBoundCodes
}

func NewStylingSpecification(
	colors Colors,
	upholsteries Upholsteries,
	defaultColors ManyTimeBoundCodes,
	defaultUpholsteries ManyTimeBoundCodes,
) (StylingSpecification, error) {
	validator := newStylingValidator(
		colors,
		upholsteries,
		defaultColors,
		defaultUpholsteries,
	)
	err := validator.validate()
	if err != nil {
		return StylingSpecification{}, err
	}

	return StylingSpecification{
		colors:              colors,
		upholsteries:        upholsteries,
		defaultColors:       defaultColors,
		defaultUpholsteries: defaultUpholsteries,
	}, nil
}

func (s StylingSpecification) Colors() Colors {
	return s.colors
}

func (s StylingSpecification) Upholsteries() Upholsteries {
	return s.upholsteries
}

func (s StylingSpecification) DefaultColors() ManyTimeBoundCodes {
	return s.defaultColors
}

func (s StylingSpecification) DefaultUpholsteries() ManyTimeBoundCodes {
	return s.defaultUpholsteries
}

func (s StylingSpecification) periods() ManyStructureWeekPeriods {
	colors := s.colors.periods()
	upholsteries := s.upholsteries.periods()

	return append(upholsteries, colors...)
}

type Upholsteries []Upholstery

func (u Upholsteries) Codes() Codes {
	codes := make(Codes, len(u))
	for i, upholstery := range u {
