package specification

import (
	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type stylingValidator struct {
	periodByColor       map[Code]StructureWeekPeriod
	periodByUpholstery  map[Code]StructureWeekPeriod
	defaultColors       ManyTimeBoundCodes
	defaultUpholsteries ManyTimeBoundCodes
}

func newStylingValidator(
	colors Colors,
	upholsteries Upholsteries,
	defaultColors ManyTimeBoundCodes,
	defaultUpholsteries ManyTimeBoundCodes,
) *stylingValidator {
	periodByColor := make(map[Code]StructureWeekPeriod)
	for _, color := range colors {
		periodByColor[color.code] = color.period
	}

	periodByUpholstery := make(map[Code]StructureWeekPeriod)
	for _, upholstery := range upholsteries {
		periodByUpholstery[upholstery.code] = upholstery.period
	}

	return &stylingValidator{
		periodByColor:       periodByColor,
		periodByUpholstery:  periodByUpholstery,
		defaultColors:       defaultColors,
		defaultUpholsteries: defaultUpholsteries,
	}
}

func (s *stylingValidator) validate() error {
	if len(s.periodByColor) == 0 {
		return errors.Errorf(
			"%w: at least one color is required",
			domainerror.InvalidOperation,
		)
	}

	if len(s.periodByUpholstery) == 0 {
		return errors.Errorf(
			"%w: at least one upholstery is required",
			domainerror.InvalidOperation,
		)
	}

	return s.validateDefaultStylings()
}

func (s *stylingValidator) validateDefaultStylings() error {
	err := s.validateDefaultColors()
	if err != nil {
		return err
	}

	return s.validateDefaultUpholsteries()
}

func (s *stylingValidator) validateDefaultColors() error {
	periods := s.defaultColors.periods()
	if periods.hasOverlap() {
		return errors.Errorf(
			"%w: ambiguous default colors, at least two default colors have overlapping periods",
			domainerror.InvalidOperation,
		)
	}

	for _, color := range s.defaultColors {
		colorPeriod, colorExists := s.periodByColor[color.code]
		if !colorExists {
			return errors.Errorf(
				"%w: default color code %s does not exist in colors",
				domainerror.InvalidOperation,
				color.code,
			)
		}

		if !colorPeriod.contains(color.period) {
			return errors.Errorf(
				"%w: default period %v is not contained in color period %v",
				domainerror.InvalidOperation,
				color.period,
				colorPeriod,
			)
		}
	}

	return nil
}

func (s *stylingValidator) validateDefaultUpholsteries() error {
	periods := s.defaultUpholsteries.periods()
	if periods.hasOverlap() {
		return errors.Errorf(
			"%w: ambiguous default upholsteries, at least two default upholsteries have overlapping periods",
			domainerror.InvalidOperation,
		)
	}

	for _, upholstery := range s.defaultUpholsteries {
		upholsteryPeriod, upholsteryExists := s.periodByUpholstery[upholstery.code]
		if !upholsteryExists {
			return errors.Errorf(
				"%w: default upholstery code %s does not exist in upholsteries",
				domainerror.InvalidOperation,
				upholstery.code,
			)
		}

		if !upholsteryPeriod.contains(upholstery.period) {
			return errors.Errorf(
				"%w: default period %v is not contained in upholstery period %v",
				domainerror.InvalidOperation,
				upholstery.period,
				upholsteryPeriod,
			)
		}
	}

	return nil
}

