ast.text:
package specification

import (
	"github.com/go-errors/errors"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
)

type WheelSpecification struct {
	wheels        Wheels
	standardWheel *Code
}

func NewWheelSpecification(
	wheels Wheels,
	standardWheel *Code,
) (WheelSpecification, error) {
	if len(wheels) == 0 {
		return WheelSpecification{}, errors.Errorf(
			"%w: wheels are required",
			domainerror.InvalidOperation,
		)
	}

	err := validateStandardWheels(standardWheel, wheels)
	if err != nil {
		return WheelSpecification{}, err
	}

	return WheelSpecification{
		wheels:        wheels,
		standardWheel: standardWheel,
	}, nil
}

func validateStandardWheels(standardWheel *Code, wheels Wheels) error {
	if standardWheel == nil {
		return nil
	}

	wheelCodes := wheels.codeMap()
	if _, ok := wheelCodes[*standardWheel]; !ok {
		return errors.Errorf(
			"%w: standard wheel %s is not in wheels %v",
			domainerror.InvalidOperation,
			standardWheel,
			wheels,
		)
	}

	return nil
}

func (w WheelSpecification) Wheels() Wheels {
	return w.wheels
}

func (w WheelSpecification) periods() ManyStructureWeekPeriods {
	return w.wheels.periods()
}

func (w WheelSpecification) StandardWheel() *Code {
	return w.standardWheel
}

type Wheel struct {
	code                 Code
	requiredColors       ManyTimeBoundExactlyOne
	requiredOptions      ManyTimeBoundAtLeastOne
	requiredUpholsteries ManyTimeBoundExactlyOne
	forbidsOptions       ManyForbids
	forbidsUpholsteries  ManyForbids
	period               StructureWeekPeriod
}

func NewWheel(
	code Code,
	requiredColors ManyTimeBoundExactlyOne,
	requiredOptions ManyTimeBoundAtLeastOne,
	requiredUpholsteries ManyTimeBoundExactlyOne,
	forbidsOptions ManyForbids,
	forbidsUpholsteries ManyForbids,
	period StructureWeekPeriod,
) (Wheel, error) {
	if !requiredColors.areValidInPeriod(period) {
		return Wheel{}, errors.Errorf(
			"%w: wheel %s has required colors outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	if !requiredOptions.areValidInPeriod(period) {
		return Wheel{}, errors.Errorf(
			"%w: wheel %s has required options outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	if !requiredUpholsteries.areValidInPeriod(period) {
		return Wheel{}, errors.Errorf(
			"%w: wheel %s has required upholsteries outside its period %v",
			domainerror.InvalidOperation,
			code,
			period,
		)
	}

	return Wheel{
		code:                 code,
		requiredColors:       requiredColors,
		requiredOptions:      requiredOptions,
		requiredUpholsteries: requiredUpholsteries,
		forbidsOptions:       forbidsOptions,
		forbidsUpholsteries:  forbidsUpholsteries,
		period:               period,
	}, nil
}

func (w Wheel) Code() Code {
	return w.code
}

func (w Wheel) Period() StructureWeekPeriod {
	return w.period
}

func (w Wheel) RequiredColors() ManyTimeBoundExactlyOne {
	return w.requiredColors
}

func (w Wheel) RequiredOptions() ManyTimeBoundAtLeastOne {
	return w.requiredOptions
}

func (w Wheel) RequiredUpholsteries() ManyTimeBoundExactlyOne {
	return w.requiredUpholsteries
}

func (w Wheel) ForbidsOptions() ManyForbids {
	return w.forbidsOptions
}

func (w Wheel) ForbidsUpholsteries() ManyForbids {
	return w.forbidsUpholsteries
}

type Wheels []Wheel

func (w Wheels) periods() ManyStructureWeekPeriods {
	periods := make(ManyStructureWeekPeriods, len(w))
	for i, wheel := range w {
		periods[i] = wheel.period
	}

	return periods
}

func (w Wheels) codeMap() map[Code]bool {
	wheels := make(map[Code]bool, len(w))
	for _, wheel := range w {
		wheels[wheel.code] = true
	}

	return wheels
}

func (w Wheels) Codes() Codes {
	var codes Codes
	for _, wheel := range w {
		codes = append(codes, wheel.code)
	}

	return codes
}

