package usecase

import (
	"context"
	"maps"

	"github.com/go-errors/errors"
	"github.com/google/uuid"
	"github.com/ourstudio-se/puan-sdk-go/puan"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/domainerror"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type BaseCarKeyCalculator struct {
	creator    *puan.SolutionCreator
	repository CarRulesetRepository
}

func NewBaseCarKeyCalculator(
	creator *puan.SolutionCreator,
	repository CarRulesetRepository,
) *BaseCarKeyCalculator {
	return &BaseCarKeyCalculator{
		creator:    creator,
		repository: repository,
	}
}

func (c *BaseCarKeyCalculator) Calculate(
	ctx context.Context,
	id uuid.UUID,
) (ruleset.BaseCarKeys, error) {
	carRuleset, err := c.repository.GetRuleset(ctx, id)
	if err != nil {
		return ruleset.BaseCarKeys{}, err
	}

	baseCarKeys, err := c.calculateBaseCarKeys(carRuleset)
	if err != nil {
		return ruleset.BaseCarKeys{}, err
	}

	return baseCarKeys, nil
}

func (c *BaseCarKeyCalculator) calculateBaseCarKeys(
	carRuleset ruleset.CarRuleset,
) (ruleset.BaseCarKeys, error) {
	components := carRuleset.Components()

	packageComponents := carRuleset.PackageComponents()
	packageVariantComponents, err := packageComponents.AsVariants()
	if err != nil {
		return ruleset.BaseCarKeys{}, err
	}

	carKeysLookup, err := c.calculateComponentCarKeyLookup(
		carRuleset,
		components,
		packageVariantComponents,
	)
	if err != nil {
		return ruleset.BaseCarKeys{}, err
	}

	baseCarKeysCreator := ruleset.NewBaseCarKeysCreator(carKeysLookup)
	baseCarKeys, err := baseCarKeysCreator.New(components, packageVariantComponents)
	if err != nil {
		return ruleset.BaseCarKeys{}, err
	}

	return baseCarKeys, nil
}

func (c *BaseCarKeyCalculator) calculateComponentCarKeyLookup(
	carRuleset ruleset.CarRuleset,
	components ruleset.ManyComponents,
	packageVariantComponents ruleset.ManyPackageVariantComponents,
) (map[string][]ruleset.CarKeyInPeriod, error) {
	periods, err := carRuleset.StructureWeekPeriods()
	if err != nil {
		return nil, err
	}

	if len(periods) == 0 {
		return nil, errors.Errorf(
			"%w: calculating base car keys for ruleset with no structure week periods is not supported",
			domainerror.InvalidOperation,
		)
	}

	carKeysLookup := make(map[string][]ruleset.CarKeyInPeriod)

	for _, period := range periods {
		lookupForPeriod, err := c.calculateComponentCarKeyLookupForPeriod(
			carRuleset,
			period,
			components,
			packageVariantComponents,
		)
		if err != nil {
			return nil, err
		}

		for id, carKey := range lookupForPeriod {
			carKeysLookup[id] = append(carKeysLookup[id], carKey)
		}
	}

	return carKeysLookup, nil
}

func (c *BaseCarKeyCalculator) calculateComponentCarKeyLookupForPeriod(
	carRuleset ruleset.CarRuleset,
	period specification.StructureWeekPeriod,
	components ruleset.ManyComponents,
	packageVariantComponents ruleset.ManyPackageVariantComponents,
) (map[string]ruleset.CarKeyInPeriod, error) {
	envelope, err := c.calculateSolutionsBySelection(
		carRuleset,
		period,
		components,
		packageVariantComponents,
	)
	if err != nil {
		return nil, err
	}

	componentCarKeyLookup, err := c.newComponentCarKeyLookup(
		carRuleset,
		period,
		envelope,
		components,
		packageVariantComponents,
	)
	if err != nil {
		return nil, err
	}

	return componentCarKeyLookup, nil
}

func (c *BaseCarKeyCalculator) calculateSolutionsBySelection(
	carRuleset ruleset.CarRuleset,
	period specification.StructureWeekPeriod,
	components ruleset.ManyComponents,
	packageVariantComponents ruleset.ManyPackageVariantComponents,
) (puan.SolutionsBySelectionEnvelope, error) {
	selections := c.toSelections(components, packageVariantComponents)

	from := period.From().EarliestFrom()
	to, err := period.To().LatestTo()
	if err != nil {
		return puan.SolutionsBySelectionEnvelope{}, err
	}

	query, err := puan.NewSolutionQueryBuilder().
		WithSelections(selections).
		WithRuleset(*carRuleset.Ruleset()).
		WithFrom(&from).
		WithTo(&to).
		Build()
	if err != nil {
		return puan.SolutionsBySelectionEnvelope{}, err
	}

	envelope, err := c.creator.CreateSolutionsBySelection(query)
	if err != nil {
		return puan.SolutionsBySelectionEnvelope{}, err
	}

	return envelope, nil
}

func (c *BaseCarKeyCalculator) toSelections(
	components ruleset.ManyComponents,
	packageVariantComponents ruleset.ManyPackageVariantComponents,
) puan.Selections {
	var selections puan.Selections

	componentSelections := components.AsSelections()
	selections = append(selections, componentSelections...)

	packageVariantComponentSelections := packageVariantComponents.AsSelections()
	selections = append(selections, packageVariantComponentSelections...)

	return selections
}

func (c *BaseCarKeyCalculator) newComponentCarKeyLookup(
	carRuleset ruleset.CarRuleset,
	period specification.StructureWeekPeriod,
	envelope puan.SolutionsBySelectionEnvelope,
	components ruleset.ManyComponents,
	packageComponents ruleset.ManyPackageVariantComponents,
) (map[string]ruleset.CarKeyInPeriod, error) {
	componentLookup, err := c.newStandaloneComponentCarKeyLookup(
		carRuleset,
		period,
		envelope,
		components,
	)
	if err != nil {
		return nil, err
	}

	packageComponentLookup, err := c.newPackageComponentCarKeyLookup(
		carRuleset,
		period,
		envelope,
		packageComponents,
	)
	if err != nil {
		return nil, err
	}

	var lookup = make(map[string]ruleset.CarKeyInPeriod)
	maps.Copy(lookup, componentLookup)
	maps.Copy(lookup, packageComponentLookup)

	return lookup, nil
}

func (c *BaseCarKeyCalculator) newStandaloneComponentCarKeyLookup(
	carRuleset ruleset.CarRuleset,
	period specification.StructureWeekPeriod,
	envelope puan.SolutionsBySelectionEnvelope,
	components ruleset.ManyComponents,
) (map[string]ruleset.CarKeyInPeriod, error) {
	lookup := make(map[string]ruleset.CarKeyInPeriod)
	for _, component := range components {
		selection := component.AsAddSelection()

		solutionHolder, err := envelope.GetSolutionBySelection(selection)
		if err != nil {
			return nil, err
		}

		key, err := ruleset.NewCarKeyInPeriod(carRuleset, solutionHolder.Solution(), period)
		if err != nil {
			return nil, err
		}

		lookup[component.ID()] = key
	}

	return lookup, nil
}

func (c *BaseCarKeyCalculator) newPackageComponentCarKeyLookup(
	carRuleset ruleset.CarRuleset,
	period specification.StructureWeekPeriod,
	envelope puan.SolutionsBySelectionEnvelope,
	components ruleset.ManyPackageVariantComponents,
) (map[string]ruleset.CarKeyInPeriod, error) {
	lookup := make(map[string]ruleset.CarKeyInPeriod)
	for _, component := range components {
		selection := component.AsAddSelection()

		solutionHolder, err := envelope.GetSolutionBySelection(selection)
		if err != nil {
			return nil, err
		}

		key, err := ruleset.NewCarKeyInPeriod(carRuleset, solutionHolder.Solution(), period)
		if err != nil {
			return nil, err
		}

		lookup[component.ID()] = key
	}

	return lookup, nil
}

