package usecase

import (
	"context"
	"time"

	"github.com/go-errors/errors"
	"github.com/google/uuid"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type CarKeyCalculator struct {
	creator            *puan.SolutionCreator
	repository         CarRulesetRepository
	selectionValidator *ruleset.SelectionValidator
}

func NewCarKeyCalculator(
	creator *puan.SolutionCreator,
	repository CarRulesetRepository,
	selectionValidator *ruleset.SelectionValidator,
) *CarKeyCalculator {
	return &CarKeyCalculator{
		creator:            creator,
		repository:         repository,
		selectionValidator: selectionValidator,
	}
}

func (c *CarKeyCalculator) CalculateCarKeyV2(
	ctx context.Context,
	id uuid.UUID,
	selections puan.Selections,
	fromWeek *specification.StructureWeek,
	toWeek *specification.StructureWeek,
) (ruleset.CarKey, error) {
	carRuleset, err := c.repository.GetRuleset(ctx, id)
	if err != nil {
		return ruleset.CarKey{}, errors.Errorf(
			"%w: failed to get car ruleset",
			err,
		)
	}

	if err := carRuleset.ValidateTimestamps(
		fromWeek,
		toWeek,
	); err != nil {
		return ruleset.CarKey{}, err
	}

	validSelections := c.selectionValidator.FilterOutInvalid(
		ctx,
		selections,
		carRuleset.Ruleset().SelectableVariables(),
	)

	query, err := c.newQuery(
		validSelections,
		carRuleset,
		fromWeek,
		toWeek,
	)
	if err != nil {
		return ruleset.CarKey{}, err
	}

	envelope, err := c.creator.Create(query)
	if err != nil {
		return ruleset.CarKey{}, err
	}

	solution := envelope.Solution()

	return ruleset.NewCarKey(carRuleset, solution, fromWeek)
}

func (c *CarKeyCalculator) newQuery(
	selections puan.Selections,
	carRuleset ruleset.CarRuleset,
	fromWeek *specification.StructureWeek,
	toWeek *specification.StructureWeek,
) (puan.SolutionQuery, error) {
	builder := puan.NewSolutionQueryBuilder().
		WithSelections(selections).
		WithRuleset(*carRuleset.Ruleset())

	if fromWeek != nil {
		from := fromWeek.EarliestFrom()
		builder = builder.WithFrom(&from)
	}

	if toWeek != nil {
		to, err := toWeek.LatestTo()
		if err != nil {
			return puan.SolutionQuery{}, err
		}
		builder = builder.WithTo(&to)
	}

	query, err := builder.Build()
	if err != nil {
		return puan.SolutionQuery{}, err
	}

	return query, nil
}

func (c *CarKeyCalculator) CalculateManyCarKeys(
	ctx context.Context,
	rulesetID uuid.UUID,
	selectionGroups []puan.Selections,
	fromWeek *specification.StructureWeek,
	toWeek *specification.StructureWeek,
) (ruleset.CarKeysBySelectionGroup, error) {
	carRuleset, err := c.repository.GetRuleset(ctx, rulesetID)
	if err != nil {
		return nil, errors.Errorf(
			"%w: failed to get car ruleset",
			err,
		)
	}

	if err := carRuleset.ValidateTimestamps(
		fromWeek,
		toWeek,
	); err != nil {
		return nil, err
	}

	validSelectionGroups := c.selectionValidator.FilterOutInvalidInGroups(
		ctx,
		selectionGroups,
		carRuleset.Ruleset().SelectableVariables(),
	)

	query, err := c.newManySolutionsQuery(
		validSelectionGroups,
		*carRuleset.Ruleset(),
		fromWeek,
		toWeek,
	)
	if err != nil {
		return nil, err
	}

	envelope, err := c.creator.CreateManySolutions(query)
	if err != nil {
		return nil, err
	}

	return ruleset.NewCarKeysBySelectionGroup(
		carRuleset,
		envelope.SolutionsBySelectionGroup(),
		fromWeek,
	)
}

func (c *CarKeyCalculator) newManySolutionsQuery(
	selectionGroups []puan.Selections,
	ruleset puan.Ruleset,
	fromWeek *specification.StructureWeek,
	toWeek *specification.StructureWeek,
) (puan.ManySolutionsQuery, error) {
	var from, to *time.Time
	if fromWeek != nil {
		earliestFrom := fromWeek.EarliestFrom()
		from = &earliestFrom
	}
	if toWeek != nil {
		latestTo, err := toWeek.LatestTo()
		if err != nil {
			return puan.ManySolutionsQuery{}, err
		}
		to = &latestTo
	}

	return puan.NewManySolutionsQuery(
		selectionGroups,
		ruleset,
		from,
		to,
	)
}

