	return &CarRulesetCreator{
		repository: repo,
		logger:     logger,
	}
}

func (c *CarRulesetCreator) Create(
	ctx context.Context,
	spec specification.CarSpecification,
) (uuid.UUID, error) {
	cleaner := specification.NewCarSpecificationCleaner(&spec, c.logger)
	if err := cleaner.RemoveRedundantForbids(ctx); err != nil {
		return uuid.Nil, err
	}

	ruleset, err := ruleset.NewFromSpecification(spec)
	if err != nil {
		return uuid.Nil, err
	}

	enrichedCtx := observability.EnrichLogsWithRulesetID(ctx, ruleset.ID())

	if err := c.repository.CreateRulesetForSpecification(
		enrichedCtx,
		ruleset,
		spec,
	); err != nil {
		return uuid.Nil, err
	}
	c.logger.Info(enrichedCtx, "Created ruleset")

	return ruleset.ID(), nil
}

