package usecase

import (
	"context"

	"github.com/go-errors/errors"
	"github.com/google/uuid"
	"github.com/ourstudio-se/puan-sdk-go/puan"

	"github.com/volvo-cars/caas-car-configurator/internal/domain/ruleset"
	"github.com/volvo-cars/caas-car-configurator/internal/domain/specification"
)

type StartCarKeysCalculator struct {
	creator    *puan.SolutionCreator
	repository CarRulesetRepository
}

func NewStartCarKeysCalculator(
	creator *puan.SolutionCreator,
	repository CarRulesetRepository,
) *StartCarKeysCalculator {
	return &StartCarKeysCalculator{
		creator:    creator,
		repository: repository,
	}
}

func (c *StartCarKeysCalculator) CalculateStartCarKeys(
	ctx context.Context,
	id uuid.UUID,
) ([]ruleset.CarKeyInPeriod, error) {
	carRuleset, err := c.repository.GetRuleset(ctx, id)
	if err != nil {
		return nil, errors.Errorf(
			"%w: failed to get car ruleset",
			err,
		)
	}

	periods, err := carRuleset.StructureWeekPeriods()
	if err != nil {
		return nil, err
	}

	startKeys := make([]ruleset.CarKeyInPeriod, len(periods))
	for i, period := range periods {
		startKeys[i], err = c.calculateStartCarKey(period, carRuleset)
		if err != nil {
			return nil, err
		}
	}

	return startKeys, nil
}

func (c *StartCarKeysCalculator) calculateStartCarKey(
	period specification.StructureWeekPeriod,
	carRuleset ruleset.CarRuleset,
) (ruleset.CarKeyInPeriod, error) {
	from := period.From().EarliestFrom()
	query, err := puan.NewSolutionQueryBuilder().
		WithRuleset(*carRuleset.Ruleset()).
		WithFrom(&from).
		Build()
	if err != nil {
		return ruleset.CarKeyInPeriod{}, err
	}
	envelope, err := c.creator.Create(query)
	if err != nil {
		return ruleset.CarKeyInPeriod{}, err
	}

	solution := envelope.Solution()

	return ruleset.NewCarKeyInPeriod(carRuleset, solution, period)
}

