package httpclient

import (
	"net/http"

	retryablehttp "github.com/hashicorp/go-retryablehttp"
)

type RoundTripper interface {
	WithRoundTripper(next http.RoundTripper) http.RoundTripper
}

func New(
	retryClient *retryablehttp.Client,
	metricsRoundTripper *MetricsRoundTripper,
) *http.Client {
	client := retryClient.StandardClient()
	addRoundTrippersInReverseOrder(
		client,
		metricsRoundTripper,
	)

	return client
}

func addRoundTrippersInReverseOrder(
	client *http.Client,
	roundTrippers ...RoundTripper,
) {
	next := client.Transport

	for i := len(roundTrippers) - 1; i >= 0; i-- {
		roundTripper := roundTrippers[i]
		next = roundTripper.WithRoundTripper(next)
	}

	client.Transport = next
}

