package httpclient

import (
	"net/http"
	"strconv"
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
	semconv "go.opentelemetry.io/otel/semconv/v1.21.0"
)

type MetricsRoundTripper struct {
	next http.RoundTripper

	callDurationHistogram metric.Int64Histogram
	requestCounter        metric.Int64Counter
}

func NewMetricsRoundTripper(
	meter metric.Meter,
) (*MetricsRoundTripper, error) {
	histogram, err := meter.Int64Histogram(
		"http.client.request.duration",
		metric.WithDescription("Outgoing HTTP request duration"),
		metric.WithUnit("ms"),
	)
	if err != nil {
		return nil, err
	}

	requestCounter, err := meter.Int64Counter(
		"http.client.request.total",
		metric.WithDescription("Outgoing requests"),
	)
	if err != nil {
		return nil, err
	}

	return &MetricsRoundTripper{
		callDurationHistogram: histogram,
		requestCounter:        requestCounter,
	}, nil
}

func (rt *MetricsRoundTripper) WithRoundTripper(next http.RoundTripper) http.RoundTripper {
	rt.next = next

	return rt
}

func (rt *MetricsRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	start := time.Now()

	resp, err := rt.next.RoundTrip(req)

	duration := time.Since(start).Milliseconds()
	rt.collectMetrics(req, resp, duration)

	return resp, err
}

func (rt *MetricsRoundTripper) collectMetrics(
	req *http.Request,
	resp *http.Response,
	duration int64,
) {
	attributes := rt.getAttributes(req, resp)
	options := metric.WithAttributes(attributes...)

	rt.callDurationHistogram.Record(req.Context(), duration, options)

	rt.requestCounter.Add(req.Context(), 1, options)
}

// https://opentelemetry.io/docs/specs/semconv/http/http-metrics/#http-client
func (rt *MetricsRoundTripper) getAttributes(
	req *http.Request,
	resp *http.Response,
) []attribute.KeyValue {
	attrs := []attribute.KeyValue{
		semconv.HTTPRequestMethodKey.String(req.Method),
		semconv.NetworkProtocolName("http"),
		semconv.ServerAddress(req.URL.Hostname()),
		// When we have routes with path parameters, we should
		// replace them with placeholders ("SE/solve" -> ":market/solve")
		// to reduce metric cardinality
		semconv.HTTPRoute(req.URL.Path),
	}

	port := req.URL.Port()
	if port != "" {
		portNumber, err := strconv.Atoi(port)
		if err == nil {
			attrs = append(attrs, semconv.ServerPort(portNumber))
		}
	}

	if resp != nil {
		attrs = append(attrs, semconv.HTTPResponseStatusCode(resp.StatusCode))
	}

	return attrs
}

