package httpclient

import (
	"context"
	"time"

	retryablehttp "github.com/hashicorp/go-retryablehttp"
	loggingsdk "github.com/volvo-cars/ooe-product-offer-logging"
)

type retryLogAdapter struct {
	logger *loggingsdk.Logger
}

func (l *retryLogAdapter) Debug(msg string, keysAndValues ...any) {
	l.logger.Debugw(
		context.Background(),
		msg,
		keysAndValues...,
	)
}

func (l *retryLogAdapter) Info(msg string, keysAndValues ...any) {
	l.logger.Infow(
		context.Background(),
		msg,
		keysAndValues...,
	)
}

func (l *retryLogAdapter) Warn(msg string, keysAndValues ...any) {
	l.logger.Warnw(
		context.Background(),
		msg,
		keysAndValues...,
	)
}

// Error is called when request fails and will be retried.
// We log these as warnings. If all retries fail, the final
// error will be logged as error by the caller.
func (l *retryLogAdapter) Error(msg string, keysAndValues ...any) {
	l.logger.Warnw(
		context.Background(),
		msg,
		keysAndValues...,
	)
}

var _ retryablehttp.LeveledLogger = (*retryLogAdapter)(nil)

func NewRetryClient(
	logger *loggingsdk.Logger,
) *retryablehttp.Client {
	logAdapter := &retryLogAdapter{
		logger: logger,
	}
	retryClient := retryablehttp.NewClient()
	retryClient.Backoff = retryablehttp.LinearJitterBackoff
	retryClient.RetryWaitMin = time.Millisecond * 200
	retryClient.RetryWaitMax = time.Millisecond * 400
	retryClient.Logger = logAdapter

	return retryClient
}

