package observability

import (
	"context"
	"time"

	"go.opentelemetry.io/contrib/instrumentation/runtime"
	"go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetricgrpc"
	"go.opentelemetry.io/otel/metric"
	"go.opentelemetry.io/otel/metric/noop"
	"go.opentelemetry.io/otel/sdk/instrumentation"
	sdk "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/resource"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
)

type MetricsSubmitter struct {
	metric.Meter

	provider *sdk.MeterProvider
}

func NewNoopMetricsSubmitter() (*MetricsSubmitter, error) {
	return &MetricsSubmitter{
		provider: nil,
		Meter:    noop.NewMeterProvider().Meter(""),
	}, nil
}

func NewMetricsSubmitter(serviceName string) (*MetricsSubmitter, error) {
	reader, err := newOtelReader()
	if err != nil {
		return nil, err
	}

	meterProvider := newMeterProvider(serviceName, reader)

	meter := meterProvider.Meter(
		serviceName,
		metric.WithInstrumentationVersion("v0.0.0"),
	)

	return &MetricsSubmitter{
		meter,
		meterProvider,
	}, nil
}

func newOtelReader() (*sdk.PeriodicReader, error) {
	exporter, err := otlpmetricgrpc.New(
		context.Background(),
	)
	if err != nil {
		return nil, err
	}

	reader := sdk.NewPeriodicReader(
		exporter,
		sdk.WithInterval(30*time.Second),
	)
	return reader, nil
}

func newMeterProvider(
	serviceName string,
	reader *sdk.PeriodicReader,
) *sdk.MeterProvider {
	resources := resource.NewWithAttributes(
		semconv.SchemaURL,
		semconv.ServiceNameKey.String(serviceName),
	)

	views := newMetricViews(serviceName)

	provider := sdk.NewMeterProvider(
		sdk.WithResource(resources),
		sdk.WithReader(reader),
		sdk.WithView(views...),
	)
	return provider
}

func newMetricViews(serviceName string) []sdk.View {
	return []sdk.View{
		sdk.NewView(
			sdk.Instrument{
				Name: "http.client.request.duration",
				Kind: sdk.InstrumentKindHistogram,
				Scope: instrumentation.Scope{
					Name:    serviceName,
					Version: "v0.0.0",
				},
			},
			sdk.Stream{
				Aggregation: sdk.AggregationExplicitBucketHistogram{
					Boundaries: []float64{
						1,
						5,
						10,
						25,
						50,
						100,
						250,
						500,
						1000,
						2500,
						5000,
						10000,
						30000,
					},
				},
			},
		),
		sdk.NewView(
			sdk.Instrument{
				Name: "rpc.grpc.server.duration",
				Kind: sdk.InstrumentKindHistogram,
				Scope: instrumentation.Scope{
					Name:    serviceName,
					Version: "v0.0.0",
				},
			},
			sdk.Stream{
				Aggregation: sdk.AggregationExplicitBucketHistogram{
					Boundaries: []float64{
						1,
						5,
						10,
						25,
						50,
						100,
						250,
						500,
						1000,
						2500,
						5000,
						10000,
						30000,
					},
				},
			},
		),
	}
}

func (submitter *MetricsSubmitter) Start(ctx context.Context) error {
	if submitter.provider == nil {
		return nil
	}

	runtimeOpts := []runtime.Option{
		runtime.WithMeterProvider(submitter.provider),
		runtime.WithMinimumReadMemStatsInterval(time.Minute * 2),
	}
	return runtime.Start(runtimeOpts...)
}

func (submitter *MetricsSubmitter) Shutdown(ctx context.Context) error {
	if submitter.provider == nil {
		return nil
	}

	return submitter.provider.Shutdown(ctx)
}
